  const battleResultV06=battleResult;battleResult=function(){if(['tutorial','practice','self-test'].includes(state.battle?.mode)){const r=state.battle.history.result;return '<div class="battle-result"><h2>'+ (state.battle.mode==='self-test'?'Test de défense terminé':r.status==='won'?'Entraînement réussi !':'Prépare une nouvelle tentative')+'</h2><p>'+ (state.battle.mode==='self-test'?'Test privé : aucune énergie consommée, aucun gain de ressource, XP ou cote.':'Adversaire BOT · aucun gain de cote.')+'</p>'+stats([[r.gold,'Or'],[r.elixir,'Élixir']])+'<div class="center-actions">'+button('Retour à mon château','tutorial-return')+'</div></div>';}return battleResultV06();};
  const actionV06=action;action=function(a,d,node){try{
    if(a==='self-test'){selfTest();return;}
    if(a==='tutorial-start'){close();newJourney(false);state.hideTutorial=false;saveJourney();renderCastle();renderHUD();return;}
    if(a==='tutorial-welcome'){journeyEvent('welcome');return;}
    if(a==='tutorial-install'){const o=PreviewGame.TUTORIAL_KIT_V07.find(o=>o.id===d.id);if(!o)throw Error('Bâtiment de départ inconnu.');state.edit={pending:{...PreviewGame.withFloor(homeLayout,{id:o.id,type:o.type,level:1},o.floor,o.x)},currency:'gold',price:0};close();renderCastle();toast('Choisis une case verte, ou l’emplacement conseillé : étage '+(o.floor+1)+', case '+(o.x+1)+'.');return;}
    if(a==='place'&&state.journey?.step==='build'&&state.edit?.pending){const o=state.edit.pending;const prescribed=PreviewGame.TUTORIAL_KIT_V07.find(k=>k.id===o.id);if(Number(d.floor)!==prescribed.floor||Number(d.x)!==prescribed.x)throw Error('Pour ce premier exercice, utilise l’emplacement conseillé.');if(!canPlace(o,Number(d.floor),Number(d.x)))throw Error('Choisis une case verte.');o.floor=Number(d.floor);o.x=Number(d.x);o.y=homeLayout.floors-1-o.floor;(o.type==='archers'?homeLayout.defenses:homeLayout.buildings).push(o);state.edit=null;state.selected=o.id;journeyEvent('install',{target:o.id});return;}
    if(a==='tutorial-door'){close();state.edit={door:0};renderCastle();return;}
    if(a==='place'&&state.journey?.step==='build'&&state.edit?.door!==undefined){const f=state.edit.door;if(Number(d.floor)!==f||Number(d.x)!==11||!doorFree(f,Number(d.x)))throw Error('Pour cet exercice, déplace la porte à la case 12 du même étage.');homeLayout.doors[f].x=Number(d.x);state.edit=null;journeyEvent('door');return;}
    if(a==='tutorial-collect'||a==='collect'&&state.journey?.step==='collect'){journeyEvent('collect');return;}
    if(a==='claim'&&d.id==='calendar'&&state.journey&&!state.journey.done){if(state.journey.step!=='daily'){toast('Le premier cadeau a déjà été récupéré, ou l’étape n’est pas encore ouverte.');return;}journeyEvent('daily');renderModal();return;}
    if(a==='tutorial-army'){journeyEvent('army');return;}
    if(a==='tutorial-search'){open('training-search');return;}
    if(a==='tutorial-battle'){trainingBattle();return;}
    if(a==='tutorial-return'){stopBattle();close();renderHUD();return;}
    if(a==='tutorial-upgrade'){journeyEvent('upgrade-start');return;}
    if(a==='tutorial-speed'){journeyEvent('speed-tutorial');return;}
    if(a==='tutorial-hide'){state.hideTutorial=true;renderHUD();return;}
    if(a==='code-redeem'){const code=PreviewGame.v07NormalizeCode($('#reward-code').value);if(code!==demoGiftCode)throw Error('Code inconnu dans cet aperçu.');if(state.redeemedCodes.includes(code))throw Error('Ce code a déjà été utilisé sur ce compte.');const grant=PreviewGame.v07CodeGrant({id:'demo-thanks',active:true,startsAt:0,expiresAt:Date.now()+86400000,maxUses:100,createdBefore:Date.now(),reward:{diamonds:20,items:{'mana-10':1}}},{id:'preview-player',createdAt:0});state.redeemedCodes.push(code);state.giftMails.push({...grant,id:grant.grantKey,title:'Merci, aventurier !',text:'Le cadeau associé à ton code t’attend.'});saveJourney();open('gift-mails');return;}
    if(a==='gift-claim'){const ix=state.giftMails.findIndex(m=>m.id===d.id),r=PreviewGame.v07ClaimGift(giftAccount(),state.giftMails[ix],{gold:capFor('gold'),elixir:capFor('elixir')});state.xpRewardRemainder0307=r.account.xpRewardRemainder0307||state.xpRewardRemainder0307;state.wallet=r.account.wallet;state.cosmetics.owned=r.account.ownedCosmetics;for(const id of r.account.ownedHeroes)state.ownedHeroes.add(id);for(const [id,n]of Object.entries(r.account.inventory))if(id.startsWith('xp-'))state.vials[id.slice(3)]=n;else state.inventory[id]=n;state.giftMails[ix]=r.mail;if(state.journey){state.journey.wallet=structuredClone(state.wallet);state.journey.inventory=structuredClone(state.inventory);state.journey.vials=structuredClone(state.vials);saveJourney();}renderHUD();renderModal();return;}
    if(a==='gift-delete'){const m=state.giftMails.find(m=>m.id===d.id);if(!PreviewGame.v07CanDeleteMail(m))throw Error('Récupère d’abord le cadeau.');state.giftMails=state.giftMails.filter(m=>m.id!==d.id);saveJourney();renderModal();return;}
    if(['account-google','account-email','play-check'].includes(a)){toast(a==='play-check'?'La vérification sera disponible après le branchement Google Play.':'Ce bouton présente le parcours. L’authentification réelle sera branchée au serveur.');return;}
    if(a==='purchase-confirm'&&state.purchase?.currency==='eur'){open('play-billing');return;}
    if(a==='channel'&&d.channel==='clan'||a==='chat-clan'){if(!PreviewGame.v07Gates(state.level,Boolean(state.clan)).clanChat){state.channel='clan';state.chatOpen=true;close();renderChat();return;}}
    if(a==='battle'&&state.level<3){open('training-search');return;}
    actionV06(a,d,node);
  }catch(error){toast(error.message);}};
  setInterval(()=>{if(state.journey?.job&&Date.now()>=state.journey.job.endsAt)journeyEvent('upgrade-finish');},1000);
  if(PLAYER_PREVIEW.scenario==='new-player')newJourney(true);

// Déplacement tactile, navigation et présentation de la version courante.
// Ce fichier est inclus dans la même fermeture que player.mjs ; aucun accès serveur.
  const navStack=[];
  function navSnapshot(){const keys=['modal','tab','category','infoId','catalogType','heroId','monsterId','monsterPreviewLevel','purchase','cosmeticId','visited','visitedPlayer','region','stage','diamondPrompt','mapPage','warNodeId','warNodeSide'];return {values:Object.fromEntries(keys.map(k=>[k,state[k]])),scroll:$('#modal-body').scrollTop,scrollTargets:Object.fromEntries(['.shop-products','.purchase-ledger','.member-list'].map(q=>[q,$(q)?.scrollTop||0]))};}
  function navigateBack(){state.previewCosmetic=null;applyAppearance();const previous=navStack.pop();if(!previous){close();return;}Object.assign(state,previous.values);$('#modal-layer').hidden=false;renderModal();$('#modal-body').scrollTop=previous.scroll;for(const [q,y]of Object.entries(previous.scrollTargets||{}))if($(q))$(q).scrollTop=y;renderCastle();}
  function costLine(q){return '<span class="cost-line">'+icon('gold')+'<b>'+fmt(q.gold)+'</b>'+icon('elixir')+'<b>'+fmt(q.elixir)+'</b></span>';}
  function spellArt(id,slot){return art(PreviewGame.LEGEND_SPELL_ICONS[id]?.[slot-1]||'spell:'+id+'-'+slot);}
  function storageBlock(o,q){if(o.type!=='core'||!q)return null;return ['gold','elixir'].some(k=>capFor(k)<q[k])?'Améliore les deux réserves au niveau '+o.level+' pour pouvoir financer le trône.':null;}
  function passiveDescription(id){return ({aegis:'Bonus héros :<br>Structures défensives · dégâts reçus −5 %.',lyrion:'Bonus héros :<br>Monstres et héros en attaque · dégâts +5 %.',vitalis:'Bonus héros :<br>Tous les bâtiments · vie +5 %.',valdorn:'Bonus héros :<br>Pillage obtenu +20 %.<br>Pertes de ressources lors d’un pillage : 5 %.<br>Production des mines +10 %.',tiko:'Bonus héros constructeur :<br>Coût de construction −1 % par tranche de 2 niveaux.<br>Durée de construction −1 % par niveau.'})[id]||'';}
  function passiveLabels(o){const bonus=PreviewGame.defenseHeroBonuses(homeLayout),labels=[];if(!o.hero&&meta(o).kind!=='Piège'&&bonus.buildingHP)labels.push('Vie +5 % · Vitalis');if(MODELS.DEFENSES.some(d=>d.id===o.type)&&bonus.damageReduction)labels.push('Dégâts reçus −5 % · Aegis');if(['mine','extracteur'].includes(o.type)&&bonus.production)labels.push('Production +10 % · Valdorn');if(['reserve','reservoir'].includes(o.type)&&bonus.raidLoss===.05)labels.push('Pertes de pillage limitées à 5 % · Valdorn');return labels.length?'<p class="hero-bonus">Bonus héros · '+labels.join(' · ')+'</p>':'';}
  function appearancePreview(o,level){const m=meta(o),tier=Math.floor((level-1)/5);return '<div class="appearance-item" data-level="'+level+'" data-tier="'+tier+'">'+art(m.asset,'appearance-art',m.name,level)+'<span class="appearance-rank">'+(level>1?'◆ '.repeat(Math.min(4,tier+1)):'')+'</span><span class="appearance-runes">'+'✦ '.repeat((level-1)%5+1)+'</span><b>Niveau '+level+'</b></div>';}
  function appearancePair(o){return '<div class="appearance-pair">'+appearancePreview(o,o.level)+(o.level<20?'<span class="appearance-arrow">→</span>'+appearancePreview(o,o.level+1):'')+'</div>';}
  function profileMarkup(family,id,pose='idle',direction=1,slot=0){const prefix='profile:'+family+':'+id+':',fallback=family==='hero'?'hero:'+id:'monster:'+id+':n01',walk=ART[prefix+'walk']?prefix+'walk':fallback,attack=ART[prefix+'attack']?prefix+'attack':walk,legend=!ART[prefix+'walk-alt'];return '<span class="profile-rig '+pose+(legend?' legend-rig':'')+'" style="--facing:'+direction+';--phase:'+(-slot*.071)+'s">'+art(walk,'pose walk-a')+art(ART[prefix+'walk-alt']?prefix+'walk-alt':walk,'pose walk-b')+art(attack,'pose attack-pose')+(legend?art(walk,'pose legend-foot foot-left')+art(walk,'pose legend-foot foot-right'):'')+'</span>';}
  function castleFacade(skin,floors){
    const artLevel=(skin==='skin-castillet'||skin.startsWith('skin-campagne-'))?Math.max(3,Math.min(11,floors)):Math.max(5,Math.min(9,floors)),asset=MODELS.CASTLE_SKIN_FRAMES[skin]?.[artLevel]||MODELS.CASTLE_SKIN_FRAMES['skin-astral'][artLevel],slice=MODELS.FRAME_LAYOUTS[asset]?.slice||[210,180,105,180];
    return '<div class="castle-shell raster-castle" data-art-level="'+artLevel+'" data-asset="'+asset+'" role="img" aria-label="Façade '+floors+' niveaux" style="border-image-source:url(&quot;'+ART[asset]+'&quot;);border-image-slice:'+slice.join(' ')+';border-image-repeat:stretch"></div><div class="castle-foundation" aria-hidden="true"></div>';
  }
  function fitCastle(){const zone=$('#castle-zone'),floors=layout.floors+(!state.battle&&state.jobs.some(j=>j.floorJob)?1:0),width=layout.slots*CW()+104,height=floors*fh()+82;const fit=Math.min(1,(zone.clientWidth||1020)/width,(zone.clientHeight||492)/height);zone.style.alignItems=fit*state.zoom*height<=(zone.clientHeight||492)+1?'flex-end':'flex-start';$('#castle').style.zoom=fit*state.zoom;$('#castle').style.width=width+'px';$('#castle').style.height=height+'px';$('#castle').style.setProperty('--content-width',layout.slots*CW()+'px');$('#castle').style.setProperty('--floor-count',floors);}
  function scaffoldMarkup(label,width=1,endsAt=null){const id='ui:scaffold-'+(width==='floor'?'floor':Math.max(1,Math.min(3,width)));return '<span class="wood-scaffold raster-scaffold '+(width==='floor'?'floor-scaffold':'')+'" aria-label="En construction">'+art(id)+'<span class="scaffold-clock" '+(endsAt?'data-ends-at="'+endsAt+'"':'')+'>'+esc(label)+'</span></span>';}
  function experienceAction(a,d,node){
    if(a==='back'){navigateBack();return true;}
    if(['tab','category'].includes(a)){navStack.push(navSnapshot());if(a==='tab')state.tab=d.tab;else state.category=d.category;renderModal();$('#modal-body').scrollTop=0;return true;}
    if(a==='zoom'){state.zoom=Math.max(.8,Math.min(2.2,state.zoom+Number(d.dir)*.15));fitCastle();return true;}
    if(a==='demo-refill'){if(state.journey)throw Error('Le tutoriel conserve les règles des vrais joueurs.');for(const k of ['gold','elixir'])state.wallet[k]=capFor(k);renderHUD();renderModal();toast('Réserves remplies pour ce test.');return true;}
    if(a==='demo-height'){
      if(state.journey||state.battle)throw Error('Termine le tutoriel ou le combat.');const floors=Number(d.floors);if(![3,6,7,8,9,11].includes(floors))throw Error('Hauteur invalide.');state.level=floors===3?4:Math.max(12,PreviewGame.PROGRESSION_V06.extraFloorUnlocks[floors-2]);
      const l=floors===3?PreviewGame.blankCastle(4):structuredClone(MODELS.exampleLayout);l.castleLevel=state.level;l.slots=PreviewGame.castleSize(state.level).slots;l.floors=floors;
      if(floors===3)for(const [type,floor,x]of [['core',2,1],['reserve',1,3],['reservoir',0,3],['mine',0,8],['extracteur',1,8],['forge',2,6]])l.buildings.push(PreviewGame.withFloor(l,{id:'building:'+type,type,level:type==='core'?4:1},floor,x));
      const oldDoors=l.doors;l.doors=Array.from({length:floors},(_,f)=>({id:'door:'+f,floor:f,x:oldDoors.find(d=>d.floor===f)?.x??(f%2?l.slots-1:0)}));for(const o of [...l.buildings,...l.defenses,...l.barricades,...l.garrisons,...l.traps,...l.decorations]){o.y=floors-1-o.floor;o.underConstruction=false;if(o.type==='core')o.level=state.level;}
      l.path=Array.from({length:floors*l.slots},(_,i)=>{const f=Math.floor(i/l.slots),x=i%l.slots;return {x:f%2?l.slots-1-x:x,y:floors-1-f};});Object.assign(homeLayout,l);state.jobs=[];state.selected=null;state.zoom=1;clampWallet();close();renderCastle();renderHUD();toast('Configuration de test : '+floors+' niveaux.');return true;
    }
    if(a==='formation'&&!state.ownedHeroes.has(d.id))throw Error('Recrute ce héros dans la boutique.');
    if(a==='hero-level-up'&&!state.ownedHeroes.has(d.id))throw Error('Ce héros n’est pas encore recruté.');
    return false;
  }
  let drag=null,suppressClickUntil=0;
  function startDrag(){if(!drag||drag.started)return;drag.started=true;state.selected=drag.o?.id||state.selected;state.edit=drag.door!==undefined?{door:drag.door}:state.edit?.pending?state.edit:{id:drag.o.id};renderCastle();const ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=drag.door!==undefined?art('kit:floor-door'):art(meta(drag.o).asset);ghost.style.width=drag.width+'px';ghost.style.height=drag.height+'px';document.body.append(ghost);drag.ghost=ghost;$('#stage').setPointerCapture?.(drag.pointer);updateDrag(drag.px,drag.py);}
  function updateDrag(px,py){if(!drag?.started)return;drag.ghost.style.left=(px-drag.width*drag.grab)+'px';drag.ghost.style.top=(py-drag.height*.7)+'px';$('.drop-preview')?.remove();const zone=$('#castle-zone'),zr=zone.getBoundingClientRect();if(py<zr.top||py>zr.bottom||px<zr.left||px>zr.right){drag.drop=null;drag.ghost.classList.add('invalid');return;}
    const floor=[...document.querySelectorAll('.castle-floor:not(.floor-building)')].find(el=>{const r=el.getBoundingClientRect();return py>=r.top&&py<r.bottom;});if(!floor){drag.drop=null;return;}const f=Number(floor.dataset.floor),r=floor.getBoundingClientRect(),width=drag.door!==undefined?1:meta(drag.o).width,x=Math.round((px-r.left)/(r.width/layout.slots)-width*drag.grab);const valid=drag.door!==undefined?f===drag.door&&doorFree(f,x):canPlace(drag.o,f,x);drag.drop={floor:f,x,valid};drag.ghost.classList.toggle('invalid',!valid);floor.insertAdjacentHTML('beforeend','<span class="drop-preview '+(valid?'valid':'invalid')+'" style="left:'+x*CW()+'px;width:'+width*CW()+'px"><b>'+(valid?'✓':'×')+'</b></span>');
  }
  document.addEventListener('pointerdown',e=>{if(state.modal||state.battle||e.button>0)return;const target=e.target.closest('.building,.floor-door,[data-action="drag-new"]');if(!target)return;const o=target.dataset.id?object(target.dataset.id):state.edit?.pending;if(o?.underConstruction||o?.hero)return;const door=target.classList.contains('floor-door')?Number(target.dataset.floor):undefined;if(!o&&door===undefined)return;const r=target.getBoundingClientRect();drag={o,door,started:false,pointer:e.pointerId,px:e.clientX,py:e.clientY,startX:e.clientX,startY:e.clientY,width:r.width,height:r.height,grab:(e.clientX-r.left)/r.width,previousEdit:state.edit};drag.timer=setTimeout(startDrag,220);});
  document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;drag.px=e.clientX;drag.py=e.clientY;if(!drag.started&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>7){clearTimeout(drag.timer);drag=null;return;}if(drag.started){e.preventDefault();updateDrag(e.clientX,e.clientY);}},{passive:false});
  function finishDrag(e,cancel=false){if(!drag||e.pointerId!==drag.pointer)return;clearTimeout(drag.timer);const d=drag;drag=null;if(!d.started)return;suppressClickUntil=Date.now()+350;d.ghost?.remove();$('.drop-preview')?.remove();if(!cancel&&d.drop?.valid)action('place',{floor:d.drop.floor,x:d.drop.x},null);else{state.edit=d.previousEdit?.pending?d.previousEdit:null;renderCastle();if(!cancel)toast('Emplacement occupé : la structure reste à sa place.');}}
  document.addEventListener('pointerup',e=>finishDrag(e));document.addEventListener('pointercancel',e=>finishDrag(e,true));
  document.addEventListener('click',e=>{if(Date.now()<suppressClickUntil){e.stopImmediatePropagation();e.preventDefault();}else state.navBefore=navSnapshot();},true);
  state.ownedHeroes=new Set(state.journey?['gorvak']:['gorvak','tharos','elyra','brakk']);state.queueRoster={fantassin:state.queue};

// Systèmes joueur de l’édition du 10 octobre 2026, 19h08.
// État local de démonstration ; les règles pures sont partagées avec le futur service.
  function exactTime(seconds){const n=Math.max(0,Math.ceil(seconds)),d=Math.floor(n/86400),h=Math.floor(n%86400/3600),m=Math.floor(n%3600/60),s=n%60;return (d?d+' j ':'')+(h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
  function houseFor(id){return PreviewGame.heroHousing(homeLayout,id);}
  function profiles(){return Object.fromEntries(heroes.map(h=>[h.id,{unlocked:state.ownedHeroes.has(h.id),level:state.heroLevels[h.id],xp:state.heroXP[h.id]}]));}
  function syncGarrisons(){PreviewGame.syncHeroHousing(homeLayout);state.formation=homeLayout.garrisons.filter(g=>houseFor(g.hero)).map(g=>g.hero);}
  function tikoLevel(){return homeLayout.garrisons.some(g=>g.hero==='tiko'&&houseFor('tiko'))?state.heroLevels.tiko:0;}
  function constructionPrice(type,level){return PreviewGame.discountedConstruction(PreviewGame.v06BuildQuote(type,level),{tikoLevel:tikoLevel(),clanConstruction:state.clanTech.construction});}
  function floorPrice(){return PreviewGame.discountedConstruction(PreviewGame.v06FloorQuote(homeLayout.floors,state.level,{gold:capFor('gold'),elixir:capFor('elixir')}),{tikoLevel:tikoLevel(),clanConstruction:state.clanTech.construction});}
  function discountLine(q){return q.costReduction||q.timeReduction?'<p class="hero-bonus">'+(q.costReduction?'Tiko · coût −'+Math.round(q.costReduction*100)+' %<br>':'')+(q.timeReduction?'Durée réduite de '+Math.round(q.timeReduction*100)+' %':'')+'</p>':'';}
  function mineCapacity(o){return PreviewGame.v06Production(o.level)*10;}
  function settleMines(now=Date.now()){const bonus=PreviewGame.defenseHeroBonuses(homeLayout);for(const o of homeLayout.buildings.filter(o=>['mine','extracteur'].includes(o.type))){if(o.stored==null)o.stored=state.journey?0:Math.round(mineCapacity(o)*.88);o.producedAt??=now;if(!o.underConstruction)o.stored=Math.min(mineCapacity(o),o.stored+Math.max(0,now-o.producedAt)/3600000*PreviewGame.v06Production(o.level)*(1+bonus.production)*(1+.02*state.clanTech.yield));o.producedAt=now;}}
  function collectAmount(o){return Math.max(0,Math.min(Math.floor(o.stored||0),capFor(o.type==='mine'?'gold':'elixir')-state.wallet[o.type==='mine'?'gold':'elixir']));}
  function upgradeAvailable(o){const v=buildingUpgradeView(o);return Boolean(v&&!o.underConstruction&&v.allowed&&v.affordable);}
  function addCastleSignals(){if(state.battle||state.edit)return;settleMines();for(const o of [...homeLayout.buildings,...homeLayout.defenses,...homeLayout.barricades,...homeLayout.traps,...homeLayout.decorations]){const el=$('.building[data-id="'+o.id+'"]');if(!el)continue;for(const signal of el.querySelectorAll('.ready,.upgrade-plus,.collect-bubble'))signal.remove();if(upgradeAvailable(o))el.insertAdjacentHTML('beforeend','<span class="upgrade-plus" role="button" data-action="upgrade" data-id="'+o.id+'" aria-label="Améliorer '+esc(meta(o).name)+'">+</span>');if(['mine','extracteur'].includes(o.type)&&!o.underConstruction&&(o.stored||0)>=mineCapacity(o)*.85)el.insertAdjacentHTML('beforeend','<span class="collect-bubble" role="button" data-action="collect" data-id="'+o.id+'" title="Récolter '+fmt(collectAmount(o))+'">'+icon(o.type==='mine'?'gold':'elixir')+'</span>');}}
  function refreshCounters(){const now=Date.now(),energy=$('#energy-countdown'),shield=$('#shield-countdown');if(energy)energy.textContent=state.energy<5?'+1 dans '+exactTime(Math.max(0,(state.energyAt+PreviewGame.energyRechargeMs(state.level)-now)/1000)):'Énergie complète';if(shield)shield.textContent=state.shieldUntil>now?exactTime((state.shieldUntil-now)/1000):'Aucune protection';for(const el of document.querySelectorAll('[data-ends-at]'))el.textContent=exactTime((Number(el.dataset.endsAt)-now)/1000);}
  function buildersPanel(){const free=state.builders-PreviewGame.occupiedBuilders(state.jobs);return '<div class="builders-banner">'+art('ui:builder','builder-portrait')+'<div><span class="detail-label">L’atelier des bâtisseurs</span><h2>Ton équipe de construction</h2><p><b>'+free+' disponible'+(free>1?'s':'')+'</b> · '+state.jobs.length+' occupé'+(state.jobs.length>1?'s':'')+' · '+state.builders+' / 5 recrutés</p></div></div><div class="builder-grid">'+Array.from({length:5},(_,i)=>{const owned=i<state.builders,j=state.jobs[i],price=PreviewGame.PROGRESSION_V06.builderPrices[Math.max(0,state.builders-1)];return '<article class="paper-card builder-card '+(!owned?'locked-builder':'')+'">'+art('ui:builder')+'<div><span class="detail-label">Constructeur '+(i+1)+'</span><h3>'+(!owned?'À recruter':j?esc(j.name):'Prêt à travailler')+'</h3>'+(j?'<b class="builder-time" data-ends-at="'+j.endsAt+'">'+exactTime((j.endsAt-Date.now())/1000)+'</b><div class="progress-bar"><i style="width:'+Math.max(0,Math.min(100,100*(1-(j.endsAt-Date.now())/(j.durationSeconds||1800)/1000)))+'%"></i></div><div class="builder-actions">'+button('Voir le chantier','view-job','data-id="'+j.id+'"','secondary')+button('Accélérer','job-speed','data-id="'+j.id+'"','secondary')+button(icon('diamonds')+Math.max(1,Math.ceil((j.endsAt-Date.now())/3600000)*5)+' · Terminer','job-finish','data-id="'+j.id+'"')+'</div>':owned?'<p>Choisis un bâtiment ou un nouvel étage.</p>':i===state.builders?'<p>Un chantier supplémentaire en parallèle.</p>'+button(icon('diamonds')+fmt(price)+' · Recruter','buy-builder'):'<p>Recrute d’abord le constructeur précédent.</p>')+'</div></article>';}).join('')+'</div><p class="settings-note">Tiko est un héros distinct : en garnison, il réduit les coûts et les durées. Les recherches de monstres utilisent leur propre créneau.</p>';}
  function housingPanel(o){const g=homeLayout.garrisons.find(g=>g.caserneId===o.id),available=heroes.filter(h=>state.ownedHeroes.has(h.id));return '<section class="housing-panel"><h3>Héros en garnison</h3>'+(g?'<div class="housing-current">'+heroArt(g.hero)+'<div><b>'+heroes.find(h=>h.id===g.hero).name+' · niveau '+state.heroLevels[g.hero]+'</b><p>Défend '+(o.floor?'l’étage '+o.floor:'le rez-de-chaussée')+' · disponible en attaque</p></div></div>':'<p>Cette caserne n’accueille pas encore de héros.</p>')+'<p>Niveau maximum du héros : <b>'+o.level+'</b>. Chaque combat terminé lui rapporte 25 XP.</p><label>Choisir un héros<select id="housing-hero">'+available.map(h=>'<option value="'+h.id+'" '+(g?.hero===h.id?'selected':'')+'>'+h.name+' · Niv. '+state.heroLevels[h.id]+(state.heroLevels[h.id]>o.level+2?' · caserne trop faible':'')+'</option>').join('')+'</select></label><div class="detail-actions">'+button('Mettre en garnison','housing-assign','data-id="'+o.id+'" '+(o.underConstruction||!available.length?'disabled':''))+ (g?button('Retirer le héros','housing-clear','data-id="'+o.id+'"','secondary'):'')+'</div>'+(o.underConstruction?'<p>Défense suspendue pendant le chantier. Le héros reste disponible en attaque.</p>':'')+'</section>';}
  function heroHousingChoice(id){const houses=homeLayout.buildings.filter(b=>b.type==='caserne-heros'),g=homeLayout.garrisons.find(g=>g.hero===id);return '<div class="hero-defense-control"><label>Sa garnison<select id="hero-housing-choice">'+houses.map(h=>'<option value="'+h.id+'" '+(g?.caserneId===h.id?'selected':'')+'>'+ (h.floor?'Étage '+h.floor:'Rez-de-chaussée')+' · garnison niveau '+h.level+'</option>').join('')+'</select></label>'+button('Mettre en garnison','hero-house-assign','data-id="'+id+'" '+(!houses.length?'disabled':''),'secondary')+'<small>Déplace la caserne dans le château pour changer l’étage défendu.</small></div>';}
  function recruitmentState(){return {level:state.level,wallet:state.wallet,monsterLevels:state.monsterLevels,unlockedTroops:state.unlockedTroops,roster:state.roster,recruitment:state.recruitment};}
  function acceptRecruitment(s){state.wallet=s.wallet;state.roster=s.roster;state.recruitment=s.recruitment;state.troops=state.roster.reduce((n,r)=>n+r.count,0);state.queue=PreviewGame.recruitmentCount(s);}
  function recruitmentPanel(){const cap=PreviewGame.v06ArmyCapacity(state.level),now=Date.now(),first=state.recruitment[0],queueTotal=first?Math.max(0,(state.recruitment.at(-1).endsAt-now)/1000):0;return '<div class="recruit-summary"><div>'+icon('attack')+'<b>'+state.troops+' prêts · '+state.queue+' en attente</b><small>Capacité réservée : '+(state.troops+state.queue)+' / '+cap+'</small></div><div><b>'+ (first?'Prochaine unité dans <span data-ends-at="'+first.nextAt+'">'+exactTime((first.nextAt-now)/1000)+'</span>':'File de recrutement vide')+'</b><small>'+ (first?'Tout sera prêt dans <span data-ends-at="'+state.recruitment.at(-1).endsAt+'">'+exactTime(queueTotal)+'</span>':'Choisis tes troupes ci-dessous')+'</small></div>'+button(icon('diamonds')+Math.max(1,Math.ceil(queueTotal/60))+' · Terminer','finish-queue',first?'':'disabled','secondary')+'</div><div class="recruit-orders">'+state.recruitment.map((q,i)=>'<article class="paper-card recruit-order">'+monsterArt(q.troop,state.monsterLevels[q.troop])+'<div><b>'+MODELS.TROOPS.find(t=>t.id===q.troop).name+' · '+q.completed+' / '+q.total+' terminés</b><small>'+q.remaining+' restants · '+(i?'En attente':'En cours')+'</small><div class="progress-bar"><i style="width:'+q.completed/q.total*100+'%"></i></div></div>'+button('×','cancel-recruit','data-id="'+q.id+'" aria-label="Annuler les unités restantes"','secondary')+'</article>').join('')+'</div><div class="card-grid recruit-grid">'+MODELS.TROOPS.map(t=>{const unlocked=state.unlockedTroops?state.unlockedTroops.includes(t.id):t.unlock<=1,qty=Math.max(0,state.recruitChoices[t.id]??0),queued=state.recruitment.filter(q=>q.troop===t.id).reduce((n,q)=>n+q.remaining,0),secs=PreviewGame.recruitUnitSeconds(t.id,state.monsterLevels[t.id]),owned=state.roster.find(r=>r.troop===t.id)?.count||0;return '<article class="paper-card unit-card '+(!unlocked?'locked-troop':'')+'"><span class="card-level">'+(unlocked?'Niv. '+state.monsterLevels[t.id]:'Académie '+t.unlock+' requise')+'</span>'+button('i','monster','data-id="'+t.id+'"','info-button')+'<div class="recruit-art">'+monsterArt(t.id,state.monsterLevels[t.id])+(queued?'<span class="queued-count">'+queued+' en attente</span>':'')+'</div><strong>'+t.name+'</strong><span class="card-desc">'+owned+' disponibles · '+(t.id==='brise-mur'?'Priorité barricades':t.role==='pillage'?'Pillage des réserves':'Cible la plus proche')+'</span><div class="quantity-picker">'+button('−','recruit-quantity','data-id="'+t.id+'" data-dir="-1" '+(!unlocked?'disabled':''),'secondary')+'<input aria-label="Quantité de '+t.name+'" id="recruit-qty-'+t.id+'" data-recruit-id="'+t.id+'" type="number" min="0" max="'+cap+'" value="'+qty+'" '+(!unlocked?'disabled':'')+'>'+button('+','recruit-quantity','data-id="'+t.id+'" data-dir="1" '+(!unlocked?'disabled':''),'secondary')+'</div><small>Durée : '+exactTime(qty*secs)+' · '+secs+' s / unité</small>'+button(unlocked?icon('elixir')+fmt(PreviewGame.recruitUnitPrice(t.id)*qty)+' · Recruter':'Débloqué au trône '+t.unlock,'recruit','data-id="'+t.id+'" '+(!unlocked||qty===0||state.troops+state.queue>=cap?'disabled':''))+'</article>';}).join('')+'</div>';}
  function systemTick(){refreshCounters();if(state.recruitment?.length){const s=PreviewGame.settleRecruitment(recruitmentState());if(s.delivered.length){acceptRecruitment(s);renderHUD();if((state.modal==='army'&&state.tab==='recruit')||(state.modal==='building-function'&&homeObject(state.buildingFunctionId)?.type==='garnison')){const y=$('#modal-body').scrollTop;renderModal();$('#modal-body').scrollTop=y;}const names=[...new Set(s.delivered.map(d=>MODELS.TROOPS.find(t=>t.id===d.troop).name))];toast(names.join(', ')+' : '+s.delivered.length+' unité'+(s.delivered.length>1?'s':'')+' prête'+(s.delivered.length>1?'s':'')+'.');}}}
  function deploymentOptions(){const b=state.battle;if(!b?.engine?.manualDeployment||b.replay)return [];return [...b.attacker.army.roster.map(r=>({key:'troop:'+r.troop,id:r.troop,hero:false,name:MODELS.TROOPS.find(t=>t.id===r.troop).name})),...b.attacker.army.heroes.map(id=>({key:'hero:'+id,id,hero:true,name:heroes.find(h=>h.id===id).name}))].map(v=>({...v,count:b.engine.units.filter(u=>!u.deployed&&(v.hero?u.hero===v.id:!u.hero&&u.troop===v.id)).length}));}
  function deploymentPanel(){const b=state.battle,options=deploymentOptions();if(!options.length)return '';if(!options.some(o=>o.key===b.deploySelection&&o.count))b.deploySelection=options.find(o=>o.count)?.key||null;return '<div class="deployment-bar"><div class="deployment-help"><b>'+ (b.engine.started?'Déploie tes renforts':'Prépare ton attaque')+'</b><small>Tout déployer, ou choisis un personnage puis touche un emplacement autorisé.</small></div><div class="deployment-cards">'+options.map(o=>button((o.hero?heroArt(o.id):monsterArt(o.id,state.monsterLevels[o.id]))+'<b>× '+o.count+'</b><small>'+o.name+'</small>','deploy-type','data-key="'+o.key+'" '+(!o.count?'disabled':''),'deploy-card '+(b.deploySelection===o.key?'selected':'')+(o.hero?' deploy-hero':''))).join('')+'</div>'+button('Tout déployer','deploy-all328',b.deploySelection?'':'disabled','primary gold deploy-one')+'</div>';}
  function refreshDeployment(){const b=state.battle;if(!b?.engine?.manualDeployment||b.replay)return;$('.deployment-bar')?.remove();$('#battle-hud').insertAdjacentHTML('beforeend',deploymentPanel());for(const el of document.querySelectorAll('.spell-button')){const [id,slot]=el.dataset.id.split('-'),u=b.engine.units.find(u=>u.hero===id);el.disabled=!u?.deployed||u.hp<=0||b.engine.time<u.spawnAt||u.usedSpells.includes(Number(slot));el.classList.toggle('used',Boolean(u?.usedSpells.includes(Number(slot))));}const label=$('#battle-status');if(label)label.textContent=!b.engine.started?'Le chronomètre démarre à ta première unité.':'Ciblage du plus proche · Portes : 0,3 s';}
  function returnSurvivors(b){if(!b?.engine?.manualDeployment||b.replay||b.returnedTroops)return;b.returnedTroops=true;for(const u of b.engine.units.filter(u=>u.deployed&&!u.hero&&u.hp>0)){let r=state.roster.find(r=>r.troop===u.troop);if(!r)state.roster.push(r={troop:u.troop,count:0});r.count++;}state.troops=state.roster.reduce((n,r)=>n+r.count,0);}
  function loyaltyCalendar(){const cycle=state.loyalty.cycle,day=state.loyalty.day,next=day+1,claimed=state.loyalty.lastClaim===dailyKey(),hero=cycle===1?'nyra':cycle===2?'aigle':null;return '<p class="panel-subtitle">Mois '+cycle+' · '+day+' / 30 cadeaux récupérés<br>Une récompense par jour. Une absence conserve ta progression.</p><div class="rewards-grid loyalty-grid">'+Array.from({length:30},(_,i)=>{const n=i+1,last=n===30,asset=last?(hero?'hero:'+hero:'item:crown'):n%7===0?'item:shield-1d':n%3===0?'item:diamonds':n%2?'item:xp-small':'item:gold',label=last?(hero?heroes.find(h=>h.id===hero).name:cycle===3?'Tiko / Morghul / Kryos':'Coffre de fidélité'):n%7===0?'Bouclier 1 jour':n%3===0?'5 diamants':n%2?'Petite potion d’XP':'2 000 or + élixir';return '<article class="day-card '+(n<=day?'claimed':'')+' '+(n===next?'today':'')+'"><b>Jour '+n+'</b>'+art(asset)+'<small>'+label+'</small>'+(n===next?button(claimed?'Demain':'Récupérer','claim','data-id="calendar" '+(claimed?'disabled':''),'primary claim-day'):'')+'</article>';}).join('')+'</div>';}
  function systemsAction(a,d,node){
    if(a==='claim'&&d.id==='calendar'){if(state.loyalty.lastClaim===dailyKey())throw Error('Le cadeau du jour a déjà été récupéré.');state.loyalty.lastClaim=dailyKey();state.loyalty.day++;const day=state.loyalty.day;if(day===30){const id=PreviewGame.loyaltyHero(state.loyalty.cycle,dailyKey(),[...state.ownedHeroes]);if(id&&!state.ownedHeroes.has(id)){state.ownedHeroes.add(id);toast(heroes.find(h=>h.id===id).name+' rejoint ton royaume !');}else{state.wallet.diamonds+=500;toast('Coffre de fidélité : 500 diamants.');}state.loyalty.day=0;state.loyalty.cycle++;}else if(day%7===0)state.inventory['shield-1d']++;else if(day%3===0)state.wallet.diamonds+=5;else if(day%2)PreviewGame.grantFreeXP0307(state,{small:1});else{state.wallet.gold+=2000;state.wallet.elixir+=2000;clampWallet();}renderHUD();renderModal();return true;}
    if(a==='housing-assign'||a==='hero-house-assign'){const house=a==='housing-assign'?d.id:$('#hero-housing-choice').value,hero=a==='housing-assign'?$('#housing-hero').value:d.id;Object.assign(homeLayout,PreviewGame.assignHeroHousing(homeLayout,profiles(),house,hero));syncGarrisons();renderCastle();renderHUD();renderModal();toast('Héros en garnison : attaque et défense de cet étage.');return true;}
    if(a==='housing-clear'){homeLayout.garrisons=homeLayout.garrisons.filter(g=>g.caserneId!==d.id);syncGarrisons();renderCastle();renderModal();return true;}
    if(a==='hero-level-up'){const house=houseFor(d.id);if(!house||house.underConstruction)throw Error('Affecte le héros à une caserne disponible.');if(state.heroLevels[d.id]>=Math.min(20,state.level+2,house.level+2))throw Error('Améliore sa garnison avant le Level up.');return false;}
    if(a==='move'&&object(d.id)?.hero){const house=houseFor(object(d.id).hero);if(!house)throw Error('Cette garnison n’a pas de caserne.');close();state.selected=house.id;state.edit={id:house.id};renderCastle();return true;}
    if(a==='formation'||a==='hero-defense'){if(homeLayout.garrisons.some(g=>g.hero===d.id)){homeLayout.garrisons=homeLayout.garrisons.filter(g=>g.hero!==d.id);syncGarrisons();renderCastle();renderModal();}else{state.heroId=d.id;open('hero');toast('Choisis une caserne pour ce héros.');}return true;}
    if(a==='view-job'){const j=state.jobs.find(j=>j.id===d.id);if(!j)return true;if(j.floorJob){close();$('#castle-zone').scrollTop=0;}else{state.selected=j.target;state.infoId=j.target;open('info');}return true;}
    if(a==='recruit-quantity'){state.recruitChoices[d.id]=Math.max(0,Math.min(PreviewGame.v06ArmyCapacity(state.level),(state.recruitChoices[d.id]??0)+Number(d.dir)));const y=$('#modal-body').scrollTop;renderModal();$('#modal-body').scrollTop=y;return true;}
    if(a==='recruit'){if(state.jobs.some(j=>j.target==='building:garnison'))throw Error('La garnison est en chantier.');const count=Number($('#recruit-qty-'+d.id)?.value||state.recruitChoices[d.id]||1);if(count<1)throw Error('Choisis au moins une unité.');acceptRecruitment(PreviewGame.enqueueRecruitment(recruitmentState(),d.id,count));state.recruitChoices[d.id]=0;renderHUD();renderModal();toast(count+' unité'+(count>1?'s':'')+' ajoutée'+(count>1?'s':'')+' à la file.');return true;}
    if(a==='finish-queue'){if(!state.recruitment.length)return true;const cost=Math.max(1,Math.ceil((state.recruitment.at(-1).endsAt-Date.now())/60000));if(state.wallet.diamonds<cost)throw Error('Diamants insuffisants.');state.wallet.diamonds-=cost;acceptRecruitment(PreviewGame.settleRecruitment(recruitmentState(),state.recruitment.at(-1).endsAt));renderHUD();renderModal();toast('Tous les renforts sont prêts.');return true;}
    if(a==='cancel-recruit'){const s=PreviewGame.cancelRecruitment(recruitmentState(),d.id);acceptRecruitment(s);renderHUD();renderModal();toast(fmt(s.refund)+' élixir remboursés pour les unités non commencées.');return true;}
    if(a==='collect'){if(state.journey?.step==='collect')return false;const o=object(d.id);if(!o||!['mine','extracteur'].includes(o.type))throw Error('Choisis une mine.');if(o.underConstruction)throw Error('La mine est en chantier.');settleMines();const r=o.type==='mine'?'gold':'elixir',n=collectAmount(o);if(!n)throw Error(state.wallet[r]>=capFor(r)?'Ta réserve est pleine.':'Aucune ressource à récolter.');o.stored-=n;state.wallet[r]+=n;renderCastle();renderHUD();if(state.modal)renderModal();toast('+'+fmt(n)+' '+(r==='gold'?'or':'élixir')+' récoltés.');const e=$('.building[data-id="'+o.id+'"]');e?.insertAdjacentHTML('beforeend','<span class="harvest-float">+'+fmt(n)+'</span>');setTimeout(()=>e?.querySelector('.harvest-float')?.remove(),1400);return true;}
    if(a==='deploy-type'){state.battle.deploySelection=d.key;refreshDeployment();return true;}
    if(a==='deploy-unit'){const b=state.battle;if(!b?.engine?.manualDeployment||b.replay)return true;const opt=deploymentOptions().find(o=>o.key===b.deploySelection&&o.count);if(!opt)throw Error('Sélectionne une unité disponible.');if(!opt.hero&&!(state.roster.find(r=>r.troop===opt.id)?.count>0))throw Error('Stock de troupe indisponible.');const u=PreviewGame.deployBattleUnit(b.engine,opt.hero?{hero:opt.id}:{troop:opt.id});if(!opt.hero){const r=state.roster.find(r=>r.troop===opt.id);if(!r||r.count<=0)throw Error('Stock de troupe indisponible.');r.count--;state.troops--;}b.frames.push(frameOf(b.engine));refreshDeployment();renderBattleFrame(b.engine);return true;}
    return false;
  }
  state.recruitChoices={};state.recruitment=[];state.loyalty={cycle:1,day:0,lastClaim:null};state.campaignCleared=[];
  if(!state.journey){state.queue=0;const s=PreviewGame.enqueueRecruitment(recruitmentState(),'fantassin',4);acceptRecruitment(s);}
  syncGarrisons();settleMines();setInterval(systemTick,1000);
  document.addEventListener('input',e=>{const id=e.target.dataset.recruitId;if(!id)return;state.recruitChoices[id]=Math.max(0,Math.min(PreviewGame.v06ArmyCapacity(state.level),Number(e.target.value)||0));const card=e.target.closest('.unit-card'),qty=state.recruitChoices[id];card.querySelector('.chosen-count').textContent='× '+qty;card.querySelector('[data-action="recruit"]').disabled=qty===0;card.querySelector('[data-action="recruit"]').innerHTML=icon('elixir')+fmt(PreviewGame.recruitUnitPrice(id)*qty)+' · Recruter';card.querySelector('.quantity-picker + small').textContent='Durée : '+exactTime(qty*PreviewGame.recruitUnitSeconds(id,state.monsterLevels[id]))+' · '+PreviewGame.recruitUnitSeconds(id,state.monsterLevels[id])+' s / unité';});

// Édition 21h30 : devis virtuels, confirmations, garnisons par cartes et cartes de campagne.
// Toutes les données de cet aperçu restent locales ; aucune dépense réelle.
  state.diamondPrompt=null;state.pendingPlacement=null;
  state.campaignStars={};if(!state.journey){state.campaignCleared=Array.from({length:18},(_,i)=>i+1);for(const n of state.campaignCleared)state.campaignStars[n]=n%5===0?3:4;}
  function bonusCard(id,lines){const h=heroes.find(h=>h.id===id);return '<article class="bonus-card" data-bonus-hero="'+id+'">'+heroArt(id)+'<div><b>'+h.name+'</b>'+lines.map(s=>'<span>'+s+'</span>').join('')+'</div></article>';}
  function unitBonusCards(){return PreviewGame.defenseHeroBonuses(homeLayout).attack?'<div class="bonus-cards">'+bonusCard('lyrion',['Attaque des monstres et héros +5 %'])+'</div>':'';}
  passiveLabels=function(o){const b=PreviewGame.defenseHeroBonuses(homeLayout),cards=[];
    if(!o.hero&&meta(o).kind!=='Piège'&&b.buildingHP)cards.push(bonusCard('vitalis',['Vie des bâtiments +5 %']));
    if(MODELS.DEFENSES.some(d=>d.id===o.type)&&b.damageReduction)cards.push(bonusCard('aegis',['Dégâts reçus −5 %']));
    if(['mine','extracteur'].includes(o.type)&&b.production)cards.push(bonusCard('valdorn',['Production +10 %']));
    if(['reserve','reservoir'].includes(o.type)&&b.raidLoss===.05)cards.push(bonusCard('valdorn',['Pertes lors d’un pillage : 5 %']));
    if(['mine','extracteur'].includes(o.type)&&state.clanTech.yield)cards.push('<article class="bonus-card" data-bonus-clan="yield"><div><b>Rendement du clan</b><span>Production +'+(state.clanTech.yield*2)+' %</span></div></article>');
    return cards.length?'<div class="bonus-cards" aria-label="Bonus des héros en garnison">'+cards.join('')+'</div>':'';
  };
  v06ItemValues=function(o,n){const item={...o,level:n},base=PreviewGame.structureInfo({...homeLayout,garrisons:[]},item),total=PreviewGame.structureInfo(homeLayout,item),b=PreviewGame.defenseHeroBonuses(homeLayout);
    const values={...base,range:base.range||0,interval:base.interval||0,bonuses:{hp:Math.max(0,total.hp-base.hp),damage:Math.max(0,total.damage-base.damage)}};
    if(['mine','extracteur'].includes(o.type)){values.production=PreviewGame.v06Production(n);values.bonuses.production=Math.round(values.production*(1+b.production)*(1+.02*state.clanTech.yield))-values.production;}
    if(['reserve','reservoir'].includes(o.type))values.capacity=PreviewGame.v06ResourceCap(n);
    if(o.type==='core')values.army=PreviewGame.v06ArmyCapacity(n);return values;
  };
  comparisonTable=function(current,next){const b=PreviewGame.defenseHeroBonuses(homeLayout),units=['hero','monster'].includes(state.modal);
    for(const v of [current,next])if(!v.bonuses)v.bonuses={damage:units&&b.attack?Math.round(v.damage*(1+b.attack))-v.damage:0};
    const fields=[['hp','Points de vie','PV'],['damage','Dégâts / attaque','dégâts'],['range','Portée · cases',''],['interval','Intervalle · secondes',''],['production','Production / heure','/ h'],['capacity','Stockage maximal',''],['army','Capacité d’armée','']];
    const cell=(v,k,unit)=>'<b>'+fmt(v[k]||0)+(k==='production'?' / h':'')+'</b>'+(v.bonuses[k]?'<span class="stat-added"> (+'+fmt(v.bonuses[k])+' '+unit+')</span><small class="stat-total">Total : '+fmt((v[k]||0)+v.bonuses[k])+(k==='production'?' / h':'')+'</small>':'');
    return '<table class="comparison-table"><thead><tr><th>Statistique</th><th>Actuel · '+current.level+'</th><th></th><th>Suivant · '+next.level+'</th><th>Gain</th></tr></thead><tbody>'+fields.filter(([k])=>current[k]||next[k]).map(([k,label,unit])=>{const delta=Math.round(((next[k]||0)+(next.bonuses[k]||0)-(current[k]||0)-(current.bonuses[k]||0))*100)/100;return '<tr><td>'+label+'</td><td>'+cell(current,k,unit)+'</td><td class="stat-arrow">→</td><td class="stat-gain">'+cell(next,k,unit)+'</td><td class="stat-gain stat-delta">'+(delta>0?'+':'')+fmt(delta)+'</td></tr>';}).join('')+'</tbody></table>';
  };
  housingPanel=function(o){const g=homeLayout.garrisons.find(g=>g.caserneId===o.id),owned=heroes.filter(h=>state.ownedHeroes.has(h.id));return '<section class="housing-panel"><h3>Héros en garnison</h3>'+(g?'<div class="housing-current">'+heroArt(g.hero)+'<div><b>'+heroes.find(h=>h.id===g.hero).name+' · niveau '+state.heroLevels[g.hero]+'</b><p>Défend '+(o.floor?'l’étage '+o.floor:'le rez-de-chaussée')+' · disponible en attaque</p></div>'+button('Retirer','housing-clear','data-id="'+o.id+'"','secondary')+'</div>':'<p>Choisis un héros de ta collection.</p>')+'<p>Héros au maximum niveau <b>'+Math.min(20,state.level+2,o.level+2)+'</b> · XP gagnée par les héros déployés en combat.</p><div class="housing-cards">'+owned.map(h=>{const assigned=houseFor(h.id),active=g?.hero===h.id,blocked=o.underConstruction||state.heroLevels[h.id]>o.level+2;return button(heroArt(h.id)+'<strong>'+h.name+'</strong><span>Niveau '+state.heroLevels[h.id]+'</span><small>'+ (active?'En garnison ici':blocked?'Garnison niveau '+state.heroLevels[h.id]+' requise':assigned?'Déplacer depuis '+(assigned.floor?'l’étage '+assigned.floor:'le RDC'):'Disponible')+'</small>','housing-assign','data-id="'+o.id+'" data-hero="'+h.id+'" '+(blocked||active?'disabled':''),'housing-card '+(active?'active':''));}).join('')+'</div>'+(o.underConstruction?'<p>Défense suspendue pendant le chantier. Le héros reste disponible en attaque.</p>':'')+'</section>';};
  heroHousingChoice=function(id){const houses=homeLayout.buildings.filter(b=>b.type==='caserne-heros'),current=houseFor(id);return '<section class="hero-defense-control"><h3>Choisir sa garnison</h3><div class="housing-cards house-cards">'+houses.map(h=>{const g=homeLayout.garrisons.find(g=>g.caserneId===h.id),active=current?.id===h.id,disabled=h.underConstruction||h.level+2<state.heroLevels[id]||active;return button(art('building:caserne-heros')+'<strong>'+(h.floor?'Étage '+h.floor:'Rez-de-chaussée')+'</strong><span>Garnison niveau '+h.level+'</span><small>'+(active?'Affectation actuelle':h.underConstruction?'En construction':h.level+2<state.heroLevels[id]?'Niveau insuffisant':g?'Remplacer '+heroes.find(x=>x.id===g.hero).name:'Garnison libre')+'</small>','hero-house-assign','data-id="'+id+'" data-house="'+h.id+'" '+(disabled?'disabled':''),'housing-card '+(active?'active':''));}).join('')+'</div>'+(current?button('Retirer de la garnison','housing-clear','data-id="'+current.id+'"','secondary'):'')+'<small>Déplace sa garnison pour changer l’étage défendu.</small></section>';};
  const resourceProductsBefore=products;products=function(){return resourceProductsBefore().map(p=>{if(!p.resource)return p;const q=PreviewGame.resourcePurchaseQuote(capFor(p.resource),Math.floor(state.wallet[p.resource]),p.fraction||.5);return {...p,...q,owned:!q.amount,description:fmt(q.amount)+' '+(p.resource==='gold'?'or':'élixir')+' à ajouter'+(q.fraction===.5?' · offre demi-réserve':'')};});};
  function enoughDiamonds(cost){if(state.wallet.diamonds<cost)throw Error('Il te manque '+fmt(cost-state.wallet.diamonds)+' diamants : '+fmt(cost)+' nécessaires, '+fmt(state.wallet.diamonds)+' disponibles.');}
