  function diamondConfirmation(){const p=state.diamondPrompt;if(!p)return '<p>Choisis un chantier.</p>';const missing=state.wallet.diamonds<p.cost,finish=p.kind==='finish';return '<div class="diamond-confirmation">'+icon('diamonds')+'<h2>'+ (finish?'Terminer '+esc(state.jobs.find(j=>j.id===p.id)?.name||'le chantier'):'Compléter les ressources manquantes')+'</h2>'+(finish?'<p>Le constructeur sera disponible immédiatement.</p>':'<p>Il manque '+fmt(p.missing.gold)+' or et '+fmt(p.missing.elixir)+' élixir.<br>Le chantier démarrera avec sa durée normale.</p>')+'<div class="diamond-cost"><b>'+fmt(p.cost)+'</b> diamants</div><p>Ton solde : <b>'+fmt(state.wallet.diamonds)+'</b> diamants</p>'+(missing?'<p class="payment-shortage" role="alert">Il te manque '+fmt(p.cost-state.wallet.diamonds)+' diamants.</p>':'')+'<div class="center-actions">'+button('Confirmer · '+fmt(p.cost)+' diamants','confirm-diamonds',missing?'disabled':'')+button('Annuler','back','','secondary')+'</div></div>';}
  function busyBuildersPanel(){return '<div class="builder-blocked"><h2>Aucun constructeur disponible</h2><p>Ta structure n’a pas encore été achetée. Termine un chantier ou recrute un constructeur pour la placer.</p>'+ (state.pendingPlacement&&PreviewGame.occupiedBuilders(state.jobs)<state.builders?button('Construire à cet emplacement','resume-placement'):'')+'</div>'+buildersPanel();}
  function upgradeCheck(o){if(!o)throw Error('Choisis un bâtiment construit.');if(state.research&&['garnison','atelier-monstres'].includes(o.type))throw Error('Termine la recherche de monstres avant ce chantier.');const blocker=PreviewGame.v06UpgradeBlock({type:o.type,level:o.level,mainLevel:state.level,jobs:state.jobs.map(j=>({...j,target:homeObject(j.target)?.type||j.target})),builders:state.builders,garrisonLevel:homeObject('building:garnison')?.level||1,levels:PreviewGame.buildingLevelContext(homeLayout.buildings)});if(blocker)throw Error(blocker);const q=constructionPrice(o.type,o.level),limit=storageBlock(o,q);if(limit)throw Error(limit);return q;}
