  function commitPlacement(spec,useDiamonds=false){if(state.battle?.engine?.status==='running'&&document.body.classList.contains('battle-mode'))throw Error('Termine le combat avant de construire.');const o=spec.pending,m=meta(o);if(!m||!canPlace(o,spec.floor,spec.x))throw Error('Cet emplacement est occupé. Choisis une autre case.');if(objects().filter(i=>i.type===o.type).length>=PreviewGame.v06InstanceLimit(o.type,state.level))throw Error('Limite de construction atteinte.');const timed=['Bâtiment','Défense','Barricade'].includes(m.kind);
    if(timed&&PreviewGame.occupiedBuilders(state.jobs)>=state.builders){state.pendingPlacement=spec;state.edit=null;open('build-busy');return;}
    if(spec.quote){const missing=PreviewGame.missingResourceQuote(state.wallet,spec.quote);if(missing.diamonds&&!useDiamonds){state.pendingPlacement=spec;state.edit=null;fundingPrompt({kind:'placement'},spec.quote);return;}if(useDiamonds)state.wallet=PreviewGame.payConstructionWithDiamonds(state.wallet,spec.quote);else v06Pay(spec.quote);}else{if(state.wallet[spec.currency]<spec.price)throw Error('Ressources insuffisantes.');state.wallet[spec.currency]-=spec.price;}
    Object.assign(o,{floor:spec.floor,x:spec.x,y:homeLayout.floors-1-spec.floor,orientation:'front'});const list=m.kind==='Piège'?'traps':m.kind==='Barricade'?'barricades':m.kind==='Bâtiment'?'buildings':m.kind==='Décoration'?'decorations':'defenses';homeLayout[list].push(o);
    if(timed){o.underConstruction=true;const seconds=spec.quote?.durationSeconds||1800;state.jobs.push({id:'build-'+o.id,target:o.id,to:1,name:m.name,durationSeconds:seconds,endsAt:Date.now()+seconds*1000});}
    state.edit=null;state.pendingPlacement=null;state.diamondPrompt=null;state.selected=o.id;close();renderCastle();renderHUD();toast(timed?'Chantier lancé.':'Structure placée.');
  }
  function finishConstruction(id){const j=state.jobs.find(j=>j.id===id);if(!j)throw Error('Ce chantier est déjà terminé.');const cost=PreviewGame.constructionFinishPrice(j.endsAt);if(!cost){completeJobs();return;}enoughDiamonds(cost);state.diamondPrompt={kind:'finish',id,cost};open('diamond-confirm');}
  function floorBuild(useDiamonds=false){syncBuilderSlots();const workers=PreviewGame.floorWorkers(homeLayout.floors);if(PreviewGame.occupiedBuilders(state.jobs)+workers>state.builders)throw Error(workers+' constructeurs disponibles sont nécessaires pour cet étage.');if(state.jobs.some(j=>j.floorJob))throw Error('Un étage est déjà en construction.');const q=floorPrice();if(!q.allowed)throw Error('Cœur niveau '+q.unlock+' requis.');const missing=PreviewGame.missingResourceQuote(state.wallet,q);if(missing.diamonds&&!useDiamonds){fundingPrompt({kind:'floor'},q);return;}if(useDiamonds)state.wallet=PreviewGame.payConstructionWithDiamonds(state.wallet,q);else v06Pay(q);state.diamondPrompt=null;state.jobs.push({id:currentId('floor'),target:'floor',floor:homeLayout.floors+1,floorJob:true,workers,name:'Étage '+(homeLayout.floors),durationSeconds:q.durationSeconds,endsAt:Date.now()+q.durationSeconds*1000});renderCastle();renderHUD();open('castle-management','floors');}

  function campaignProgress(){const cleared=new Set(state.campaignCleared),next=Array.from({length:32},(_,i)=>i+1).find(n=>!cleared.has(n))||32;return {cleared,next};}
  const worldMapPoints=[[[8,75],[20,36],[37,56],[45,24],[59,48],[70.5,23],[85,47],[93,17]],[[10,69],[21,36],[38,54],[45.5,26],[59,48],[71,21],[85,45],[93,15]],[[8,77],[22,40],[37,59],[47,22],[60,51],[72,22],[86,52],[94,15]],[[8,77],[24.5,36],[37,62],[49,21],[60,53],[72,25],[85,49],[93,15]]];
  campaign=function(){const progress=campaignProgress(),starTotal=Object.values(state.campaignStars).reduce((a,b)=>a+b,0);if(state.tab==='map')return '<p class="panel-subtitle">'+starTotal+' étoiles · Quatre mondes à conquérir</p><div class="world-grid">'+worldNames.map((name,i)=>'<article class="world-card">'+art('campaign:map-'+i)+'<div><h2>'+name+'</h2><p>'+state.campaignCleared.filter(n=>n>i*8&&n<=i*8+8).length+' / 8 forteresses conquises</p>'+button(progress.next>=i*8+1?'Explorer':'Voir la carte','region','data-id="'+i+'"')+'</div></article>').join('')+'</div>';
    const region=Number(state.region)||0,active=progress.next>region*8&&progress.next<region*8+9;return '<div class="campaign-map-header"><div><h2>'+worldNames[region]+'</h2><span>'+state.campaignCleared.filter(n=>n>region*8&&n<=region*8+8).length+' / 8 châteaux conquis</span></div>'+button('Les mondes','tab','data-tab="map"','secondary')+'</div><div class="campaign-map" aria-label="Parcours de '+worldNames[region]+'">'+art('campaign:map-'+region,'campaign-map-art')+worldMapPoints[region].map(([x,y],i)=>{const stage=region*8+i+1,done=progress.cleared.has(stage),unlocked=stage<=progress.next;return '<button class="map-castle '+(done?'done':stage===progress.next?'current':'locked')+'" style="left:'+x+'%;top:'+y+'%" data-action="stage" data-id="'+(i+1)+'" aria-label="Château '+(i+1)+(done?' · conquis':unlocked?' · disponible':' · verrouillé')+'" '+(!unlocked?'disabled':'')+'>'+art('building:core','map-castle-art')+'<b>'+ (unlocked?i+1:icon('lock'))+'</b>'+stars(state.campaignStars[stage]||0)+'</button>';}).join('')+'</div><div class="campaign-map-footer"><span>'+ (active?'Préserve tes troupes pour obtenir quatre étoiles.':progress.next>region*8+8?'Ce monde est conquis. Tu peux rejouer ses combats.':'Termine le monde précédent pour ouvrir ce parcours.')+'</span>'+ (active?button('Combat suivant','stage','data-id="'+(progress.next-region*8)+'"'):'')+'</div>';
  };
  function refinementsAction(a,d,node){
    if(a==='housing-assign'||a==='hero-house-assign'){const house=a==='housing-assign'?d.id:d.house,hero=a==='housing-assign'?d.hero:d.id;if(!house||!hero)throw Error('Sélectionne une carte de héros et une caserne.');Object.assign(homeLayout,PreviewGame.assignHeroHousing(homeLayout,profiles(),house,hero));syncGarrisons();renderCastle();renderHUD();renderModal();toast('Garnison mise à jour.');return true;}
    if(a==='upgrade-confirm'){startUpgrade(d.id);return true;}
    if(a==='job-finish'){finishConstruction(d.id);return true;}
    if(a==='confirm-diamonds'){const p=state.diamondPrompt;if(!p)throw Error('Cette confirmation a expiré.');if(p.kind==='finish'){const j=state.jobs.find(j=>j.id===p.id);if(!j){state.diamondPrompt=null;completeJobs();navigateBack();return true;}const cost=PreviewGame.constructionFinishPrice(j.endsAt);enoughDiamonds(cost);state.wallet.diamonds-=cost;j.endsAt=Date.now();state.diamondPrompt=null;completeJobs();renderHUD();renderCastle();if(state.pendingPlacement)open('build-busy');else navigateBack();}else{const q=p.kind==='upgrade'?upgradeCheck(homeObject(p.id)):p.kind==='floor'?floorPrice():state.pendingPlacement?.quote;if(!q)throw Error('Choisis de nouveau ton emplacement.');const latest=PreviewGame.missingResourceQuote(state.wallet,q);enoughDiamonds(latest.diamonds);if(latest.diamonds>p.cost){fundingPrompt(p,q);toast('Le devis a changé. Vérifie le nouveau montant.');return true;}if(p.kind==='upgrade')startUpgrade(p.id,true);else if(p.kind==='floor')floorBuild(true);else commitPlacement(state.pendingPlacement,true);}return true;}
    if(a==='place'&&state.edit?.pending){const spec={...state.edit,floor:Number(d.floor),x:Number(d.x)};commitPlacement(spec);return true;}
    if(a==='resume-placement'){if(!state.pendingPlacement)throw Error('Choisis une structure dans la boutique.');commitPlacement(state.pendingPlacement);return true;}
    if(a==='buy-floor'){floorBuild();return true;}
    if(a==='purchase-confirm'&&state.purchase?.resource){const p=state.purchase,q=PreviewGame.resourcePurchaseQuote(capFor(p.resource),Math.floor(state.wallet[p.resource]),p.fraction||.5);if(!q.amount)throw Error('Ta réserve est pleine.');if(q.price!==p.price||q.amount!==p.amount){state.purchase={...p,...q};renderModal();toast('La quantité disponible a changé. Vérifie ton choix.');return true;}enoughDiamonds(p.price);return false;}
    if(a==='purchase-confirm'&&state.purchase?.structure){const p=state.purchase;if(p.quote&&(state.wallet.gold<p.quote.gold||state.wallet.elixir<p.quote.elixir)){// Pick the legal position before offering resource compensation.
      const pending={id:'new:'+Date.now(),type:p.structure,level:1};close();state.selected=null;state.edit={pending,price:p.price,currency:p.currency,quote:p.quote};renderCastle();return true;}}
    if(a==='region'){state.region=Number(d.id);open('campaign','route');return true;}
    if(a==='stage'){const stage=Number(d.id),global=Number(state.region||0)*8+stage;if(stage<1||stage>8||global>campaignProgress().next)throw Error('Termine le château précédent.');state.stage=stage;open('stage');return true;}
    if(a==='battle'&&d.mode==='campaign'&&Number(state.region||0)*8+Number(state.stage||1)>campaignProgress().next)throw Error('Termine le château précédent.');
    if(a==='close'){state.pendingPlacement=null;state.diamondPrompt=null;}
    return false;
  }
  // Click the scenery to deselect without interrupting a drag, placement or combat.
  document.addEventListener('click',e=>{if(state.modal||state.edit||state.battle||Date.now()<suppressClickUntil)return;if(e.target.closest('#castle,#selection,#hud,#chat,#modal-layer,.drag-ghost,[data-action]'))return;state.selected=null;state.previewCosmetic=null;renderSelection();$('.range-overlay')?.remove();for(const el of document.querySelectorAll('.building.selected'))el.classList.remove('selected');});

