  state.id='member-0';state.clanId=state.clan?'sentinelles-demo':null;state.flag='FR';state.photo={entitled:false,changes:0,lastChangedAt:null,pending:null};
  state.clanData={id:state.clanId,tech:state.clanTech,progress:{},treasury:state.clanTreasury,stock:{},ledger:[],donations:[]};state.clanWeek=PreviewGame.clanWeekKey();state.rewardWeeks=[];state.warDay=PreviewGame.v06ParisDay();state.demoWarOpen=false;state.mapPage=null;
  state.members.forEach((m,i)=>Object.assign(m,{clanId:state.clanId,lastSeenAt:Date.now()-(i%4?3600000*(i+1):30000)}));
