  function renderFullMap(reset=false){const el=fullMapLayer(),old=$('.full-map-scroll'),sx=old?.scrollLeft||0,sy=old?.scrollTop||0,war=state.mapPage==='war',progress=campaignProgress(),nodes=war?[...warPoints(state.warRoster,false),...warPoints(state.warEnemy,true)]:campaignPoints();el.hidden=false;
    const path=nodes.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join(' '),icons=nodes.map(p=>{if(!war){const done=progress.cleared.has(p.stage),available=p.stage<=progress.next;return '<button class="journey-castle '+(done?'done':p.stage===progress.next?'current':'locked')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="campaign-stage" data-stage="'+p.stage+'" '+(!available?'disabled':'')+' aria-label="Combat '+p.stage+'">'+art('war:castle:scout')+'<b>'+p.stage+'</b>'+stars(state.campaignStars[p.stage]||0)+'</button>';}
      const done=p.enemy&&warEligibility(p.id).conquered,kind=p.role==='chief'?'chief':p.role==='random'?'scout':'representative';return '<button class="journey-castle war-castle '+p.role+(done?' done':'')+(p.enemy?' enemy':' ally')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="war-node" data-id="'+p.id+'" data-side="'+(p.enemy?'enemy':'ally')+'">'+art('war:castle:'+kind+(done?':ruined':''))+'<strong>'+esc(p.name)+'</strong><small>'+currentRoles[p.role]+' · '+p.points+' pts</small>'+(done?'<b>✓</b>':'')+'</button>';}).join('');
    el.innerHTML='<div class="full-map-scroll"><div class="full-map-world '+(war?'war-world':'campaign-world')+'">'+art(war?'war:map':'campaign:unified','full-map-art')+(war?'':'<svg class="campaign-trail" viewBox="0 0 3000 1500" aria-hidden="true"><path d="'+path+'"/></svg>')+icons+'</div></div><header class="full-map-header">'+button('‹','map-return','aria-label="Retour"','square-button map-return')+'<div><h1>'+(war?'Guerre des clans':'Campagne d’Astral')+'</h1><span>'+(war?esc(state.clan)+' ◀ ▶ '+esc(state.warOpponent)+' · '+(state.demoWarOpen?'Session de test':'8 h – 22 h · Paris'):state.campaignCleared.length+' / 32 châteaux · Terre → Bois → Braise → Givre')+'</span></div><div class="map-summary">'+(war?'<b>'+state.warAttacks.filter(a=>a.playerId===state.id&&(a.day||PreviewGame.v06ParisDay(a.at))===state.warDay&&a.status==='won').length+' / 10 conquis</b><small>'+warEligibility('_').remaining+' défaites restantes</small>':'<b>✦ '+Object.values(state.campaignStars).reduce((n,v)=>n+v,0)+' étoiles</b>')+'</div></header><div class="full-map-footer">'+(war?button('Tournoi et récompenses','open','data-page="war-rewards"','secondary'):button('Combat suivant','campaign-stage','data-stage="'+Math.min(32,progress.next)+'"'))+'<span>Glisse la carte avec un doigt</span></div>';
    const scroller=$('.full-map-scroll');if(reset){if(war)scroller.scrollTop=1500;else{const p=nodes[Math.min(31,progress.next-1)];scroller.scrollLeft=Math.max(0,p.x-650);scroller.scrollTop=Math.max(0,p.y-350);}}else{scroller.scrollLeft=sx;scroller.scrollTop=sy;}}
  function warNodePanel(){const enemy=state.warNodeSide==='enemy',m=(enemy?state.warEnemy:state.warRoster).find(m=>m.id===state.warNodeId);if(!m)return '';const q=warEligibility(m.id),attacks=state.warAttacks.filter(a=>a.targetId===m.id&&(a.day||PreviewGame.v06ParisDay(a.at))===state.warDay),kind=m.role==='chief'?'chief':m.role==='random'?'scout':'representative';return '<div class="detail-layout">'+art('war:castle:'+kind+(enemy&&q.conquered?':ruined':enemy?':enemy':''),'detail-art')+'<div class="detail-copy"><h2>'+esc(m.name)+'</h2><p>'+currentRoles[m.role]+' · Trône '+m.mainLevel+'</p>'+stats([[m.points,'Points de conquête'],[attacks.length,'Attaques reçues'],[attacks.filter(a=>a.status!=='won').length,'Défenses gagnées'],[attacks.filter(a=>a.status==='won').length,'Défenses perdues']])+(enemy?(q.reason?'<p class="prerequisite-warning">'+esc(q.reason)+'</p>':'')+button(q.conquered?'✓ Conquis':'Attaquer','war-attack','data-id="'+m.id+'" '+(!q.allowed||!state.demoWarOpen&&!PreviewGame.v06WarIsOpen()?'disabled':'')):'<p>Sentinelle allié de la guerre actuelle.</p>')+'</div></div>';}
  const donationWait=id=>PreviewGame.clanDonationWait(clanAccount(),id);
  const treasuryHTML=()=>!officer()?'':'<div class="clan-treasury">'+icon('gold')+fmt(state.clanTreasury.gold)+icon('elixir')+fmt(state.clanTreasury.elixir)+'<small>Trésorerie du clan</small></div>';
  clanTechPanel=function(){return treasuryHTML()+'<p class="panel-subtitle">Conseil et Réserve : +2 diamants / don, toutes les 2 h. Prospérité et Bâtisseurs : +1 diamant / don, toutes les 1 h. Dons : 23 000 à 49 000 pour le niveau 0→1, puis 49 000 à 63 000 pour le niveau 1→2 ; les recherches coûtent un quart du tarif précédent.</p><div class="clan-lab-tools">'+button('∞ Ressources de démonstration','clan-lab-wallet','','secondary')+' <small>Laboratoire uniquement : dons collectifs par tranches de 100</small></div><div class="card-grid">'+PreviewGame.CLAN_TECH_V06.map(t=>{const n=state.clanTech[t.id]||0,done=state.clanData.progress?.[t.id]||0,q=n<t.maxLevel?PreviewGame.clanDonationQuote(t.id,n,done):null,wait=donationWait(t.id),diamonds=PreviewGame.clanDonationDiamonds(t.id);return '<article class="paper-card tech-card">'+icon('gear','tech-icon')+'<h3>'+t.name+'</h3><b>Niveau '+n+' / '+t.maxLevel+'</b><p>'+t.description+'</p>'+(q?'<div class="donation-progress"><div class="progress-bar"><i style="width:'+Math.min(100,done/q.target*100)+'%"></i></div><b>'+fmt(done)+' / '+fmt(q.target)+' dons</b></div><p class="donation-cost">'+icon(q.resource)+fmt(q.amount)+' '+(q.resource==='gold'?'or':'élixir')+' · +'+diamonds+' 💎</p><small>Un don toutes les '+(diamonds===1?'1 h':'2 h')+'</small>'+button(wait?'Prochain don dans '+exactTime(wait/1000):'Donner · +'+diamonds+' diamant'+(diamonds>1?'s':''),'clan-donation','data-id="'+t.id+'" '+(wait?'disabled':''))+button('Simuler +100 dons','clan-lab-batch','data-id="'+t.id+'" data-count="100"','secondary')+button('Simuler +200 dons','clan-lab-batch','data-id="'+t.id+'" data-count="200"','secondary')+button('Simuler +500 dons','clan-lab-batch','data-id="'+t.id+'" data-count="500"','secondary')+button('Simuler +1 000 dons','clan-lab-batch','data-id="'+t.id+'" data-count="1000"','secondary'):'<p>Maximum atteint</p>')+'</article>';}).join('')+'</div>';};
  function clanShopPanel(){const officer=['chief','admin'].includes(state.clanRole),stockView=state.tab==='stock'&&officer;const listings=stockView?PreviewGame.CLAN_SHOP_ITEMS:PreviewGame.visibleClanShop(state.clanData);return treasuryHTML()+'<p class="panel-subtitle">'+(stockView?'Approvisionnement responsable · coût prélevé sur la trésorerie.':'Seuls les objets approvisionnés par les responsables sont visibles. Ventes ordinaires : 85 % reversés à la trésorerie ; bannière : 100 %.')+'</p>'+(officer?'<div class="clan-lab-tools">'+button('Voir la boutique membres','tab','data-tab="shop"','secondary')+' '+button('Gérer les stocks','tab','data-tab="stock"','secondary')+'</div>':'')+'<div class="card-grid clan-stock-grid">'+(listings.length?listings.map(p=>{const q=PreviewGame.clanShopQuote(p.id),n=state.clanData.stock?.[p.id]||0,price=icon(p.resource)+fmt(p.price)+(p.secondaryResource?' + '+icon(p.secondaryResource)+fmt(p.secondaryPrice):''),cost=fmt(q.wholesale)+' '+(q.resource==='gold'?'or':'élixir')+(q.secondaryResource?' + '+fmt(q.secondaryWholesale)+' élixir':'');return '<article class="paper-card clan-stock">'+(p.id==='tiko'?heroArt('tiko','clan-stock-art'):art(p.asset,'clan-stock-art'))+'<h3>'+p.name+'</h3><b>'+n+' en stock</b><p>'+price+'</p>'+(!stockView?button('Acheter','clan-shop-buy','data-id="'+p.id+'" '+(!n?'disabled':'')):'<div class="officer-stock"><small>Mise en stock : '+cost+'</small>'+button('Ajouter 1','clan-restock','data-id="'+p.id+'"','secondary')+'</div>')+'</article>';}).join(''):'<p class="panel-subtitle">La boutique est vide : un responsable doit d’abord placer des objets en stock.</p>')+'</div><details class="clan-ledger"><summary>Journal de la trésorerie</summary>'+(state.clanData.ledger||[]).slice(-20).reverse().map(r=>'<p>'+esc(({donation:'Don',restock:'Réapprovisionnement',sale:'Vente'})[r.kind]||r.kind)+' · '+fmt(r.amount)+' '+(r.resource==='gold'?'or':'élixir')+'</p>').join('')+'</details>';}
  function contributorPanel(){const reward=PreviewGame.clanContributorRewards(state.clanData,state.clanWeek),weekDonations=state.clanData.donations.filter(d=>d.week===state.clanWeek),gold=weekDonations.filter(d=>d.resource==='gold').reduce((sum,d)=>sum+d.amount,0),elixir=weekDonations.filter(d=>d.resource==='elixir').reduce((sum,d)=>sum+d.amount,0);return '<p class="panel-subtitle">Chaque membre ayant donné reçoit entre 2,5 % et 1 % des ressources données cette semaine (selon son rang), sans prélèvement sur la trésorerie. À partir du 15e : 1 % par contributeur.</p><div class="clan-lab-tools">Or donné : '+fmt(gold)+' · Élixir donné : '+fmt(elixir)+' · '+reward.length+' contributeurs</div><div class="member-list">'+(reward.length?reward.map(r=>'<article class="member-row contributor-row"><b>'+r.rank+'</b><div><strong>'+esc(state.members.find(m=>m.id===r.playerId)?.name||r.playerId)+'</strong><small>'+fmt(r.count)+' dons · '+fmt(r.value)+' ressources</small></div><span>'+fmt(r.reward.gold)+' or · '+fmt(r.reward.elixir)+' élixir<small>'+ (r.rate*100).toLocaleString('fr-FR',{maximumFractionDigits:2})+' % · '+icon('diamonds')+r.reward.diamonds+' · '+Object.values(r.reward.vials).reduce((n,v)=>n+v,0)+' potions XP</small></span></article>').join(''):'<p>Classement vide. Utilise « Simuler +100 dons » dans Technologies.</p>')+'</div>';}
  function clanMembersPanel(){state.clanAdmins??=(state.clanAdmin?[state.clanAdmin]:[]);return '<div class="clan-overview">'+emblemMarkup()+'<div><h2>'+esc(state.clan)+'</h2><p>'+state.members.length+' / 30 membres · '+state.clanAdmins.length+' / 3 administrateurs · un admin minimum</p><p class="panel-subtitle">L’administrateur affecté à chaque guerre est tiré au sort une seule fois parmi les admins éligibles.</p></div></div><div class="member-list">'+state.members.map((m,i)=>{const presence=PreviewGame.clanMemberPresence({clanId:state.clanId},m),role=m.id===state.id?'chief':state.clanAdmins.includes(m.id)?'admin':state.clanChosen.includes(m.id)?'chosen':'member';return '<article class="member-row">'+heroArt(heroes[i%heroes.length].id)+'<div><strong>'+esc(m.id===state.id?state.name:m.name)+'</strong><small>'+currentRoles[role]+' · Trône '+m.mainLevel+'</small><small class="presence '+(presence.online?'online':'')+'">'+(presence.online?'● En ligne':'Déconnecté depuis '+v06Duration(presence.offlineMs/1000))+'</small></div>'+(state.clanRole==='chief'&&m.id!==state.id?(state.clanAdmins.includes(m.id)?button('Retirer admin','clan-admin-remove027','data-id="'+m.id+'" '+(state.clanAdmins.length<=1?'disabled':'') ,'secondary'):button('Nommer admin','clan-admin-add027','data-id="'+m.id+'" '+(state.clanAdmins.length>=3?'disabled':'') ,'secondary')):'')+(['chief','admin'].includes(state.clanRole)&&m.id!==state.id?button('Sentinelles','clan-nominate','data-id="'+m.id+'"','secondary'):'')+'</article>';}).join('')+'</div>';}
  function rolePanel(){return '<h2>'+esc(state.members.find(m=>m.id===state.nominateId)?.name)+'</h2><p>Les changements de représentation s’appliquent à la prochaine guerre.</p><div class="role-actions">'+(state.clanRole==='chief'?button('Nommer administrateur','clan-role','data-role="admin"'):'')+button('Nommer sentinelle','clan-role','data-role="chosen"','secondary')+'<label>Remplacer<select id="replace-representative">'+state.clanChosen.map(id=>'<option value="'+id+'">'+esc(state.members.find(m=>m.id===id)?.name)+'</option>').join('')+'</select></label>'+(state.clanTech.exclusion?button('Basculer l’exclusion du tirage','clan-role','data-role="excluded"','secondary'):'')+'</div>';}
  function activeAcademy(){return homeLayout.buildings.filter(b=>['academie','atelier-monstres'].includes(b.type)).sort((a,b)=>Number(a.underConstruction)-Number(b.underConstruction)||b.level-a.level)[0];}
  function researchState(){return {level:state.level,wallet:state.wallet,monsterLevels:state.monsterLevels,research:state.research,researchBuildingLevel:activeAcademy()?.underConstruction?0:activeAcademy()?.level||0,researchFunding:state.researchFunding,researchPayments:state.researchPayments};}
  function researchPanel(){return '<p class="panel-subtitle">Une recherche augmente une famille d’un niveau. Maximum : trône +2 et Centre de recherche +2, sans dépasser 20.</p><div class="card-grid">'+MODELS.TROOPS.map(t=>'<article class="paper-card unit-card">'+monsterArt(t.id,state.monsterLevels[t.id])+'<strong>'+t.name+'</strong><small>'+ (state.level<t.unlock?'Trône '+t.unlock+' requis':'Niveau '+state.monsterLevels[t.id])+'</small>'+button('Recherche et apparences','monster','data-id="'+t.id+'" '+(state.level<t.unlock?'disabled':''),'secondary')+'</article>').join('')+'</div>';}
  monsterDetail=function(){const t=MODELS.TROOPS.find(t=>t.id===state.monsterId)||MODELS.TROOPS[0],l=state.monsterLevels[t.id],n=state.monsterPreviewLevel||l,q=l<20?PreviewGame.v06ResearchQuote(l):null,a=PreviewGame.v06MonsterStats(t.id,l),b=PreviewGame.v06MonsterStats(t.id,Math.min(20,l+1)),s=researchState(),f=state.researchFunding?.id===t.id?state.researchFunding:null,block=state.unlockedTroops&&!state.unlockedTroops.includes(t.id)?'Débloque cette famille dans l’Académie':!q?'Niveau maximum':!s.researchBuildingLevel?'Construis l’Académie':activeAcademy()?.underConstruction?'Académie en chantier':state.research?'Une recherche est en cours':state.researchFunding&&!f?'Une autre famille est en financement':q.to>PreviewGame.monsterResearchLimit(s)?'Le Cœur ou l’Académie doit progresser':q.to>=8&&(s.forgeLevel||0)<q.to-1?'Forge niveau '+(q.to-1)+' requise':null;return '<div class="detail-layout"><div>'+monsterArt(t.id,n,'detail-art')+'<input class="level-slider" id="monster-level" aria-label="Voir les apparences" type="range" min="1" max="20" value="'+n+'"><p class="panel-subtitle">Apparence : niveau <strong>'+n+'</strong> / 20</p></div><div class="detail-copy"><h2>'+t.name+'</h2><p>Le curseur montre uniquement l’apparence.</p>'+comparisonTable({level:l,hp:a.hp,damage:a.damage,interval:a.attackInterval},{level:b.level,hp:b.hp,damage:b.damage,interval:b.attackInterval})+(q?'<p>Recherche niveau '+q.to+' · '+v06Duration(q.durationSeconds)+'</p>'+costLine(q):'')+(f?'<p>Financement : '+fmt(f.paid.gold)+' / '+fmt(q.gold)+' or<br>'+fmt(f.paid.elixir)+' / '+fmt(q.elixir)+' élixir</p>':'')+(state.research?'<p>Recherche en cours · '+exactTime((state.research.endsAt-Date.now())/1000)+'</p>'+button('Accélérer la recherche · 1 h','research-speed','','secondary'):'')+'<p>'+(block||'Le temps démarre quand les ressources sont déposées en totalité.')+'</p>'+button(f?'Ajouter les ressources disponibles':'Financer la recherche','research-fund','data-id="'+t.id+'" '+(block?'disabled':''))+'</div></div>';};
  army=function(){if(state.tab==='heroes')return '<p class="panel-subtitle">Tes héros recrutés · Garnison et attaque</p><div class="card-grid">'+heroes.filter(h=>state.ownedHeroes.has(h.id)).map(h=>'<article class="paper-card unit-card">'+heroArt(h.id)+'<strong>'+h.name+'</strong><span>'+h.tier+' · Niveau '+state.heroLevels[h.id]+'</span>'+button('Voir le héros','hero','data-id="'+h.id+'"','secondary')+'</article>').join('')+'</div>';return currentArmy().replace(/<div class="center-actions">[\s\S]*?<\/div>$/,'');};
  products=function(){return currentProducts().filter(p=>!p.id.startsWith('hero-')||heroes.find(h=>h.id===p.id.slice(5))?.active).map(p=>p.id==='xp-medium'?{...p,price:45}:p);};
  passiveDescription=function(id){return heroes.find(h=>h.id===id)?.desc||'';};
  passiveLabels=function(o){const cards=PreviewGame.heroPassiveLabels(homeLayout,o).map(r=>bonusCard(r.hero,[r.text]));return cards.length?'<div class="bonus-cards">'+cards.join('')+'</div>':'';};
  unitBonusCards=function(){return homeLayout.garrisons.filter(g=>['tortue','tharos','tanuki'].includes(g.hero)).map(g=>bonusCard(g.hero,[heroes.find(h=>h.id===g.hero).desc])).join('');};
  v06ItemValues=function(o,n){const item={...o,level:n},base=PreviewGame.structureInfo({...homeLayout,garrisons:[],cosmetics:null,bonusContext326:null},item),total=PreviewGame.structureInfo(homeLayout,item),b=PreviewGame.defenseHeroBonuses(homeLayout,item),values={...base,range:base.range||0,interval:base.interval||0,bonuses:{hp:Math.max(0,total.hp-base.hp),damage:Math.max(0,total.damage-base.damage)}};if(['mine','extracteur'].includes(o.type)){values.production=PreviewGame.v06Production(n);values.bonuses.production=Math.round(values.production*(1+b.productionQuantity)*(1+b.productionSpeed)*(1+.02*state.clanTech.yield))-values.production;}if(['reserve','reservoir'].includes(o.type))values.capacity=PreviewGame.v06ResourceCap(n);if(o.type==='core')values.army=PreviewGame.v06ArmyCapacity(n);return values;};
  function heroEffectComparison(id,n){const a=PreviewGame.heroSkillStats(id,n),b=PreviewGame.heroSkillStats(id,Math.min(20,n+1));return a.length?'<table class="hero-effect-table"><thead><tr><th>Effet</th><th>Avant</th><th></th><th>Après</th></tr></thead><tbody>'+a.map((r,i)=>'<tr><th>'+r.label+'</th><td>'+r.value+' '+r.unit+'</td><td>→</td><td>'+b[i].value+' '+b[i].unit+'</td></tr>').join('')+'</tbody></table>':'';}
  heroDetail=function(){const h=heroes.find(h=>h.id===state.heroId)||heroes[0],l=state.heroLevels[h.id],a=PreviewGame.v06HeroStats(h.id,l),b=PreviewGame.v06HeroStats(h.id,Math.min(20,l+1)),q=l<20?PreviewGame.v06HeroQuote(l,h.id):null,owned=state.ownedHeroes.has(h.id),house=houseFor(h.id);return '<div class="detail-layout">'+appearancePair({hero:h.id,level:l})+'<div class="detail-copy"><span class="detail-label">'+h.tier+' · '+h.role+'</span><h2>'+h.name+' · Niveau '+l+'</h2><p>'+esc(h.desc||h.description)+'</p>'+comparisonTable(a,b)+heroEffectComparison(h.id,l)+(a.heal?stats([[a.heal,'Soin par impulsion'],[a.selfHeal+' PV/s','Régénération propre']]):'')+(owned?'<div class="xp-bar"><i style="width:'+Math.min(100,q?state.heroXP[h.id]/q.xp*100:100)+'%"></i></div><p>'+fmt(state.heroXP[h.id])+' / '+fmt(q?.xp||0)+' XP</p><div class="vial-buttons">'+[['small','Petite',150],['medium','Moyenne',500],['large','Grande',1500]].map(([k,label,xp])=>button(icon('xp-'+k)+label+' · '+xp+' XP · '+state.vials[k],'vial','data-id="'+h.id+'" data-size="'+k+'" '+(!state.vials[k]?'disabled':''),'secondary')).join('')+'</div>'+(q?'<p>'+costLine(q)+'</p>':'')+button('Level up','hero-level-up','data-id="'+h.id+'" '+(!q||!house||house.underConstruction||Math.min(state.level+2,house.level+2)<q.to||state.heroXP[h.id]<q.xp?'disabled':''))+heroHousingChoice(h.id):'<p>Recrutement : '+fmt(h.priceDiamonds)+' diamants</p>'+button('Recruter ce héros','buy','data-id="hero-'+h.id+'"'))+'</div></div>';};
  settleMines=function(now=Date.now()){for(const o of homeLayout.buildings.filter(o=>['mine','extracteur'].includes(o.type))){o.stored??=state.journey?0:Math.round(mineCapacity(o)*.88);o.producedAt??=now;const b=PreviewGame.defenseHeroBonuses(homeLayout,o);if(!o.underConstruction)o.stored=Math.min(mineCapacity(o),o.stored+Math.max(0,now-o.producedAt)/3600000*PreviewGame.v06Production(o.level)*(1+b.productionQuantity)*(1+b.productionSpeed)*(1+.02*state.clanTech.yield));o.producedAt=now;}};
  function profilePanel(){const p=state.photo,wait=p.lastChangedAt!=null?Math.max(0,p.lastChangedAt+172800000-Date.now()):0,countries=[['FR','France'],['US','États-Unis'],['DE','Allemagne'],['GB','Royaume-Uni'],['JP','Japon'],['KR','Corée du Sud'],['BR','Brésil'],['MX','Mexique'],['CA','Canada'],['AU','Australie'],['RU','Russie']];return '<div class="profile-settings"><div class="profile-photo">'+(p.image?'<img src="'+p.image+'" alt="Photo validée">':heroArt('vexa'))+'<h2>'+esc(state.name)+'</h2><span>Trône '+state.level+' · '+fmt(state.rating)+' de cote</span></div><div><label>Drapeau<select id="profile-flag">'+countries.map(([code,name])=>'<option value="'+code+'" '+(state.flag===code?'selected':'')+'>'+flagEmoji(code)+' '+name+'</option>').join('')+'</select></label><p>Le drapeau est indépendant de la langue du salon de discussion.</p><h3>Photo personnelle</h3>'+(!p.entitled?'<p>Accès permanent : 0,99 € · Premier choix inclus.</p>'+button('Débloquer · 0,99 €','photo-unlock'):'<p>Ensuite : 30 diamants par changement et 48 h entre deux validations.</p><label class="photo-upload">Choisir une image<input type="file" id="profile-image" accept="image/png,image/jpeg,image/webp" '+(p.pending||wait?'disabled':'')+'></label>')+(p.pending?'<div class="photo-pending"><img src="'+p.pending.image+'" alt="En attente"><p>En attente de validation par la modération.</p></div>':'')+(wait?'<p>Prochain changement dans '+exactTime(wait/1000)+'</p>':'')+'</div></div>';}
  settings=function(){return currentSettings()+(!state.journey?'<details class="demo-tools"><summary>Tests du clan, des héros et du profil</summary><p>Outils locaux de démonstration, sans achat ou droit réel.</p><div class="center-actions">'+button('+50 000 diamants de test','demo-diamonds','','secondary')+button('Session de guerre de test','demo-war','','secondary')+button('Clôture hebdomadaire de test','demo-week','','secondary')+button('Activer la photo pour le test','demo-photo','','secondary')+button('Examen de la photo par un autre modérateur','open','data-page="demo-moderation"','secondary')+'</div></details>':'');};
  renderModal=function(){if(['campaign','war'].includes(state.modal)){state.mapPage=state.modal;$('#modal-layer').hidden=true;renderFullMap();return;}const body=state.modal==='research'?researchPanel():state.modal==='profile'?profilePanel():state.modal==='war-node'?warNodePanel():state.modal==='clan-role'?rolePanel():state.modal==='war-rewards'?'<h2>Tournoi hebdomadaire · '+state.warBracket+'</h2><p>Guerre quotidienne de 8 h à 22 h. Gagnants et perdants regroupés la semaine suivante. Clan BOT si aucun adversaire adapté.</p>'+button('Récompense quotidienne','war-claim')+contributorPanel():state.modal==='demo-moderation'?'<p>Validation simulée par un autre compte modérateur du serveur.</p>'+(state.photo.pending?'<div class="photo-pending"><img src="'+state.photo.pending.image+'" alt="Photo à examiner"></div><label>Motif du refus<input id="photo-reason"></label><div class="center-actions">'+button('Valider','demo-photo-review','data-approved="true"')+button('Refuser et rembourser','demo-photo-review','data-approved="false"','secondary')+'</div>':'<p>Aucune photo en attente.</p>')+'<p>Récompense hebdomadaire après activité validée : 500 diamants et 2 potions XP moyennes. Badge et fonction photo offerts.</p>':state.modal==='clan'&&state.clan?(state.tab==='tech'?clanTechPanel():['shop','stock'].includes(state.tab)?clanShopPanel():state.tab==='contributors'?contributorPanel():state.tab==='members'?clanMembersPanel():'<div class="clan-overview">'+emblemMarkup()+'<div><h2>'+esc(state.clan)+'</h2><p>'+state.members.length+' / 30 membres · '+state.warBracket+'</p>'+button('Guerre des clans','open','data-page="war"')+button('Discussion du clan','chat-clan','','secondary')+'</div></div>'):null;
    if(body!==null){$('#modal').classList.remove('shop-modal');$('#modal-title').textContent=({research:'Centre de recherche',profile:'Ton profil','war-node':'Château de guerre','clan-role':'Nommer un membre','war-rewards':'Tournoi et récompenses','demo-moderation':'Modération · Test local',clan:state.clan})[state.modal];$('#modal-body').innerHTML=(state.modal==='clan'&&state.tab!=='members'?'<div class="clan-mini-emblem027">'+emblemMarkup()+'</div>':'')+body;$('#modal-tabs').innerHTML=state.modal==='clan'?tabs([['overview','Mon clan'],['members','Membres'],['tech','Technologies'],['shop','Boutique du clan'],...(['chief','admin'].includes(state.clanRole)?[['stock','Approvisionnement']]:[]),['contributors','Contributeurs']]):'';return;}currentModal();if(state.modal==='info'&&object(state.infoId)?.type==='atelier-monstres')$('#modal-body').insertAdjacentHTML('beforeend',button('Ouvrir la recherche','open','data-page="research"'));};
  function contributorMails(week){if(state.rewardWeeks.includes(week))return;for(const r of PreviewGame.clanContributorRewards(state.clanData,week))if(r.playerId===state.id&&!state.giftMails.some(m=>m.id===r.id)){state.giftMails.push({id:r.id,playerId:'preview-player',kind:'gift',title:'Récompense des contributeurs',text:'Ton cadeau de la semaine.',claimed:false,remaining:PreviewGame.v07RewardBundle({gold:r.reward.gold,elixir:r.reward.elixir,diamonds:r.reward.diamonds,items:Object.fromEntries(Object.entries(r.reward.vials).map(([k,n])=>['xp-'+k,n]))})});}state.rewardWeeks.push(week);}
  action=function(a,d={},node){try{
    if(a==='battle-recruit-shortcut'){state.modal='army';state.tab='recruit';$('#modal-layer').hidden=false;renderModal();renderCastle();return;}
    if(a==='map-return'){const page=state.mapPage;close();if(page==='war')open('clan');return;}
    if(a==='campaign-stage'){const stage=Number(d.stage);if(!Number.isInteger(stage)||stage<1||stage>32||stage>campaignProgress().next)throw Error('Termine le château précédent.');state.region=Math.floor((stage-1)/8);state.stage=(stage-1)%8+1;open('stage');return;}
    if(a==='war-node'){state.warNodeId=d.id;state.warNodeSide=d.side;open('war-node');return;}
    if(a==='war-attack'){const q=warEligibility(d.id);if(!q.allowed)throw Error(q.reason||'Attaque indisponible.');if(!state.demoWarOpen&&!PreviewGame.v06WarIsOpen())throw Error('Guerre ouverte de 8 h à 22 h, heure de Paris.');state.warTarget=d.id;state.modal='war';beginBattle('war',0);return;}
    if(a==='battle-stop'&&state.battle&&!state.battle.replay){const b=state.battle;if(!b.engine.started){stopBattle();state.warTarget=null;return;}PreviewGame.finishBattle(b.engine,'finish');b.frames.push(frameOf(b.engine));b.paused=false;battleTick();return;}
    if(a==='clan-lab-wallet'){state.wallet.gold=500000000;state.wallet.elixir=500000000;state.wallet.diamonds=500000000;renderHUD();renderModal();saveCurrentProgress();toast('Ressources et diamants de démonstration chargés.');return;}
    if(a==='clan-lab-batch') {const t=PreviewGame.CLAN_TECH_V06.find(t=>t.id===d.id);if(!t)throw Error('Technologie inconnue');let count=Math.min(1000,Math.max(0,Number(d.count)||100)),done=0,total=0;const members=state.members.filter(m=>m.id!==state.id);if(!members.length)throw Error('Ajoute des membres de test');for(let k=0;k<count;k++){const level=state.clanData.tech[d.id]||0;if(level>=t.maxLevel)break;const step=state.clanData.progress[d.id]||0,q=PreviewGame.clanDonationQuote(d.id,level,step);state.clanData.treasury[q.resource]+=q.amount;state.clanData.progress[d.id]=step+1;const donor=members[k%members.length];state.clanData.donations.push({id:currentId('lot'),kind:'donation',playerId:donor.id,technology:d.id,resource:q.resource,amount:q.amount,at:Date.now(),week:state.clanWeek});done++;total+=q.amount;if(state.clanData.progress[d.id]>=q.target){state.clanData.tech[d.id]=level+1;state.clanData.progress[d.id]=0;}}state.clanTreasury=state.clanData.treasury;state.clanTech=state.clanData.tech;renderHUD();renderModal();saveCurrentProgress();toast(done+' dons collectifs de test · '+fmt(total)+' ressources, classement actualisé.');return;}
    if(a==='clan-admin-add027'){if(state.clanRole!=='chief')throw Error('Chef uniquement');state.clanAdmins??=[state.clanAdmin].filter(Boolean);if(state.clanAdmins.length>=3)throw Error('3 administrateurs maximum');if(!state.clanAdmins.includes(d.id))state.clanAdmins.push(d.id);state.clanAdmin=state.clanAdmins[0];renderModal();saveCurrentProgress();return;}
    if(a==='clan-admin-remove027'){if(state.clanRole!=='chief')throw Error('Chef uniquement');state.clanAdmins??=[state.clanAdmin].filter(Boolean);if(state.clanAdmins.length<=1)throw Error('Au moins un administrateur requis');state.clanAdmins=state.clanAdmins.filter(id=>id!==d.id);state.clanAdmin=state.clanAdmins[0];renderModal();saveCurrentProgress();return;}
    if(a==='clan-donation'){acceptClan(PreviewGame.donateClanTechnology(clanAccount(),state.clanData,d.id,{commandId:currentId('don')}));toast('Don enregistré · +'+PreviewGame.clanDonationDiamonds(d.id)+' diamant(s)');saveCurrentProgress();return;}
    if(a==='clan-restock'){acceptClan(PreviewGame.restockClanShop(clanAccount(),state.clanData,d.id,1,{commandId:currentId('stock')}));saveCurrentProgress();return;}
    if(a==='clan-shop-buy'){acceptClan(PreviewGame.buyClanShopItem(clanAccount(),state.clanData,d.id,{commandId:currentId('sale')}));if(d.id==='tiko')state.ownedHeroes.add('tiko');saveCurrentProgress();toast('Achat validé : objet reçu.');return;}
    if(['clan-donate','clan-tech'].includes(a))throw Error('Utilise le bouton Donner de la technologie.');
    if(a==='research-fund'||a==='monster-research'){const s=researchState(),q=PreviewGame.v06ResearchQuote(state.monsterLevels[d.id]),f=state.researchFunding?.id===d.id?state.researchFunding.paid:{gold:0,elixir:0},r=PreviewGame.fundMonsterResearch(s,d.id,{gold:Math.min(state.wallet.gold,q.gold-f.gold),elixir:Math.min(state.wallet.elixir,q.elixir-f.elixir),commandId:currentId('research')});state.wallet=r.wallet;state.research=r.research;state.researchFunding=r.researchFunding;state.researchPayments=r.researchPayments;renderHUD();renderModal();return;}
    if(a==='hero-level-up'){const h=heroes.find(h=>h.id===d.id),house=houseFor(d.id);if(!h||!state.ownedHeroes.has(d.id)||!house)throw Error('Place ce héros dans une caserne.');if(house.underConstruction)throw Error('La caserne est en chantier.');const r=PreviewGame.v06LevelUpHero({hero:d.id,level:state.heroLevels[d.id],xp:state.heroXP[d.id]},state.wallet,house.level);state.wallet=r.wallet;state.heroLevels[d.id]=r.profile.level;state.heroXP[d.id]=r.profile.xp;syncGarrisons();renderHUD();renderCastle();renderModal();return;}
    if(a==='clan-nominate'){if(!['chief','admin'].includes(state.clanRole))throw Error('Responsables uniquement.');state.nominateId=d.id;open('clan-role');return;}
    if(a==='clan-role'){const id=state.nominateId;if(!['chief','admin'].includes(state.clanRole))throw Error('Responsables uniquement.');if(d.role==='admin'){if(state.clanRole!=='chief')throw Error('Chef uniquement.');state.clanAdmins??=[state.clanAdmin].filter(Boolean);if(!state.clanAdmins.includes(id)&&state.clanAdmins.length>=3)throw Error('Trois administrateurs maximum');if(!state.clanAdmins.includes(id))state.clanAdmins.push(id);state.clanChosen=state.clanChosen.filter(x=>x!==id);state.clanAdmin=state.clanAdmins[0];state.clanExcluded=state.clanExcluded.filter(x=>x!==id);}else if(d.role==='chosen'){if(id===state.clanAdmin)throw Error('Administrateur déjà représenté.');if(!state.clanChosen.includes(id)){if(state.clanChosen.length<3+state.clanTech.selection)state.clanChosen.push(id);else throw Error('Retire d’abord un sentinelle pour libérer une place.');}state.clanExcluded=state.clanExcluded.filter(x=>x!==id);}else if(d.role==='excluded'){if(id===state.clanAdmin||state.clanChosen.includes(id))throw Error('Sentinelle nommé non excluable.');if(state.clanExcluded.includes(id))state.clanExcluded=state.clanExcluded.filter(x=>x!==id);else{if(state.clanExcluded.length>=Math.min(3,1+state.clanTech.exclusion))throw Error('Limite atteinte.');state.clanExcluded.push(id);}}renderModal();toast('Nomination enregistrée pour demain.');return;}
    if(a==='photo-unlock'){toast('Ce paiement s’ouvre avec Google Play dans l’application Android. Aucun paiement dans cette démo.');return;}
    if(a==='demo-photo'){state.photo.entitled=true;renderModal();return;}
    if(a==='demo-photo-review'){const r=PreviewGame.reviewProfilePhoto({id:state.id,wallet:state.wallet,photo:state.photo},{id:'other-moderator-demo',gameRole:'moderator',permissions:['avatars.review']},state.photo.pending?.id,{approved:d.approved==='true',reason:$('#photo-reason')?.value||''});state.wallet=r.wallet;state.photo=r.photo;renderHUD();renderModal();return;}
    if(a==='demo-war'){state.demoWarOpen=!state.demoWarOpen;renderModal();toast('Session test '+(state.demoWarOpen?'ouverte':'fermée'));return;}
    if(a==='demo-diamonds'){state.wallet.diamonds+=50000;renderHUD();toast('50 000 diamants de test ajoutés.');return;}
    if(a==='demo-week'){contributorMails(state.clanWeek);open('gift-mails');return;}
    currentAction(a,d,node);
  }catch(error){toast(error.message);}};
  document.addEventListener('change',async e=>{if(e.target.id==='profile-flag'){state.flag=e.target.value;renderHUD();}if(e.target.id==='profile-image'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>5242880)throw Error('Maximum 5 Mo.');const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const r=PreviewGame.requestProfilePhoto({id:state.id,wallet:state.wallet,photo:state.photo},image,{commandId:currentId('avatar')});state.wallet=r.wallet;state.photo=r.photo;renderModal();renderHUD();}catch(error){toast(error.message);}}});
  let currentPan=null;
