  function localizeInterface(){document.documentElement.lang=state.locale;const col=languageOrder.indexOf(state.locale);const walk=node=>{for(const c of node.childNodes){if(c.nodeType===3){const prior=translatedNodes.get(c),value=c.textContent,source=prior&&prior.rendered===value?prior.source:value,trim=source.trim(),words=uiWords[trim];if(!words)continue;const next=source.replace(trim,col<0?trim:words[col]);translatedNodes.set(c,{source,rendered:next});if(value!==next)c.textContent=next;}else if(c.nodeType===1&&!['SCRIPT','STYLE','SELECT','TEXTAREA'].includes(c.tagName))walk(c);}};walk(document.body);}
