function cameraLayer(){let el=$('#world-camera');if(!el){el=document.createElement('div');el.id='world-camera';$('#stage').prepend(el);for(const child of [...$('#stage').children])if(child!==el&&(child.matches('.landscape,.night,.stars,.earth,#castle-zone')))el.append(child);}return el;}
function applyCamera(){cameraLayer().style.transform='translate('+state.camera.x+'px,'+state.camera.y+'px) scale('+state.camera.z+')';}
fitCastle=function(){const zone=$('#castle-zone'),floors=layout.floors+(!state.battle&&state.jobs.some(j=>j.floorJob)?1:0),width=layout.slots*CW()+104,height=floors*fh()+82,fit=Math.min(1,(zone.clientWidth||1050)/width)*.8,castle=$('#castle');castle.style.zoom='';castle.style.width=width+'px';castle.style.height=height+'px';castle.style.left=((zone.clientWidth||1050)-width)/2+'px';castle.style.transform='scale('+fit+')';castle.style.setProperty('--content-width',layout.slots*CW()+'px');castle.style.setProperty('--floor-count',floors);castle.style.margin='0';zone.scrollTop=zone.scrollLeft=0;applyCamera();};
open=function(page,tab=null){if(page==='clan'&&state.clan&&(!tab||tab==='overview'))tab='members';if(tab==='stock'&&!officer()){toast('Accès réservé aux responsables.');return;}return polishOpen(page,tab);};
close=function(force=false){closeSelect();if(!force&&state.mapPage&&!state.battle){state.modal=state.mapPage;$('#modal-layer').hidden=true;navStack.length=0;renderFullMap();return;}return polishClose();};
const oldBeginBattle=beginBattle;beginBattle=function(mode,index){close(true);resetCamera();oldBeginBattle(mode,index);};
const oldStopBattle=stopBattle;stopBattle=function(clear=true){oldStopBattle(clear);if(clear)resetCamera();};
warPoints=function(rows,enemy){const left=[[238,1000],[294,909],[246,808],[300,703],[276,590],[228,485],[312,383],[245,279],[333,172],[302,75]],right=[[798,1000],[845,910],[797,809],[836,702],[811,590],[759,485],[844,383],[770,279],[820,172],[799,75]];return rows.map((r,i)=>({...r,x:(enemy?right:left)[i][0]*1600/1100,y:(enemy?right:left)[i][1]*1600/1100,enemy}));};
const mapRenderBefore=renderFullMap;renderFullMap=function(reset=false){mapRenderBefore(reset);const el=fullMapLayer();$('.full-map-header')?.remove();$('.full-map-footer span')?.remove();el.insertAdjacentHTML('beforeend',button('×','map-return','aria-label="Fermer la carte"','map-close'));if(state.mapPage==='war'){const won=state.warAttacks.filter(a=>a.playerId===state.id&&a.day===state.warDay&&a.status==='won').length;$('.full-map-footer')?.insertAdjacentHTML('beforeend','<div class="map-compact-score"><b>'+won+' / 10</b><small>'+warEligibility('_').remaining+' chances</small></div>');}};
function clanMemberRole(m){return m.id===state.members[0]?.id?'chief':m.id===state.clanAdmin?'admin':state.clanChosen.includes(m.id)?'chosen':state.clanExcluded.includes(m.id)?'reserve':'member';}
clanMembersPanel=function(){return '<div class="panel-mini-heading"><b>'+state.members.length+' / 30 membres</b>'+button('ⓘ','clan-info','data-kind="members"','info-orb')+'</div><div class="member-list">'+state.members.map((m,i)=>{const presence=PreviewGame.clanMemberPresence({clanId:state.clanId},m),role=clanMemberRole(m);return '<article class="member-row">'+heroArt(heroes[i%heroes.length].id)+'<div class="member-identity"><strong>'+esc(m.id===state.id?state.name:m.name)+'</strong><div class="member-meta"><b>'+({reserve:'Novice',...currentRoles})[role]+'</b><span>Trône '+m.mainLevel+'</span>'+(presence?'<span class="presence '+(presence.online?'online':'')+'">'+(presence.online?'● En ligne':'Déconnecté depuis '+v06Duration(presence.offlineMs/1000))+'</span>':'')+'</div></div>'+(officer()&&m.id!==state.id?button(menuGlyph,'clan-nominate','data-id="'+m.id+'" aria-label="Options de '+esc(m.name)+'"','member-menu'):'')+'</article>';}).join('')+'</div>';};
rolePanel=function(){const m=state.members.find(m=>m.id===state.nominateId);if(!m)return '';const chosen=state.clanChosen.includes(m.id),reserved=state.clanExcluded.includes(m.id),protectedMember=clanMemberRole(m)==='chief'||clanMemberRole(m)==='admin';return '<div class="member-role-profile">'+heroArt(heroes[state.members.indexOf(m)%heroes.length].id)+'<h2>'+esc(m.name)+'</h2></div><div class="role-actions">'+(state.clanRole==='chief'&&m.id!==state.clanAdmin?button('Administrateur du clan','clan-role','data-role="admin"'):'')+(protectedMember?'':button(chosen?'Retirer le rôle de sentinelle':'Nommer sentinelle de guerre','role-representative','data-id="'+m.id+'"','secondary')+button(reserved?'Retirer de la liste des exclus':'Exclure de la sélection de guerre','clan-role','data-role="excluded" '+(!reserved&&(state.clanExcluded.length>=Math.min(3,1+state.clanTech.exclusion)||chosen)?'disabled':'')+' title="Hors tirage de guerre"','secondary'))+(clanMemberRole(m)!=='chief'&&(clanMemberRole(m)!=='admin'||state.clanRole==='chief')?button('Exclure du clan','clan-kick-prepare','data-id="'+m.id+'"','danger-button'):'')+'</div>';};
clanTechPanel=function(){return treasuryHTML()+'<div class="panel-mini-heading"><b>Technologies</b>'+button('ⓘ','clan-info','data-kind="tech"','info-orb')+'</div><div class="card-grid">'+PreviewGame.CLAN_TECH_V06.map(t=>{const n=state.clanTech[t.id]||0,q=n<t.maxLevel?PreviewGame.clanDonationQuote(t.id,n):null,done=state.clanData.progress[t.id]||0,wait=donationWait(t.id),boost=PreviewGame.clanDonationAccelerationQuote(clanAccount(),t.id);return '<article class="paper-card tech-card">'+icon('gear','tech-icon')+'<h3>'+t.name+'</h3><b>Niveau '+n+'</b><p>'+t.description+'</p>'+(q?'<div class="donation-progress"><div class="progress-bar"><i style="width:'+done/q.target*100+'%"></i></div><b>'+done+' / '+q.target+' dons</b></div><div class="donation-cost">'+quantityIcon(q.resource,q.amount)+'</div>'+button('Donner','clan-donation','data-id="'+t.id+'" '+(wait?'disabled':''))+(wait?'<div class="donation-wait"><span data-ends-at="'+(Date.now()+wait)+'">'+exactTime(wait/1000)+'</span>'+button(icon('diamonds')+boost.diamonds+' · Accélérer','donation-boost-prepare','data-id="'+t.id+'"','secondary')+'</div>':''):'<b>Maximum atteint</b>')+'</article>';}).join('')+'</div>';};
clanShopPanel=function(){const stock=state.tab==='stock';if(stock&&!officer())return '';return treasuryHTML()+'<div class="card-grid clan-stock-grid">'+PreviewGame.CLAN_SHOP_ITEMS.map(p=>{const q=PreviewGame.clanShopQuote(p.id),n=state.clanData.stock[p.id]||0;return '<article class="paper-card clan-stock">'+art(p.asset,'clan-stock-art')+'<h3>'+p.name+'</h3><span class="stock-count">'+n+' en stock</span>'+button(quantityIcon(p.resource,stock?q.wholesale:p.price)+'<span>'+(stock?'Ajouter au stock':'Acheter')+'</span>',stock?'clan-restock-prepare':'clan-buy-prepare','data-id="'+p.id+'" '+(!stock&&!n?'disabled':''),stock?'secondary shop-price-button':'primary shop-price-button')+'</article>';}).join('')+'</div>'+(stock?'<details class="clan-ledger"><summary>Journal</summary>'+state.clanData.ledger.slice(-20).reverse().map(r=>'<p>'+esc(({donation:'Don',restock:'Approvisionnement',sale:'Vente','donation-boost':'Accélération'})[r.kind])+' · '+fmt(r.amount)+'</p>').join('')+'</details>':'');};
contributorPanel=function(){const ranks=PreviewGame.clanContributorRanking(state.clanData.donations,state.clanWeek),rewards=PreviewGame.clanContributorRewards(state.clanData,state.clanWeek);return '<div class="panel-mini-heading"><b>Classement de la semaine</b>'+button('ⓘ','clan-info','data-kind="contributors"','info-orb')+'</div><table class="contributors-table"><thead><tr><th>Rang · Joueur</th><th>Dons</th><th>Récompenses prévues</th></tr></thead><tbody>'+PreviewGame.CONTRIBUTOR_PRIZES.map((p,i)=>{const r=ranks[i],reward=rewards[i]?.reward,name=r?state.members.find(m=>m.id===r.playerId)?.name||state.name:'Place disponible';return '<tr><td><b class="rank-medal">'+(i+1)+'</b><strong>'+esc(name)+'</strong></td><td><b class="donation-count">'+(r?.count||0)+'</b></td><td><div class="contributor-prizes">'+quantityIcon('diamonds',p.diamonds)+quantityIcon('gold',reward?.gold||0)+quantityIcon('elixir',reward?.elixir||0)+Object.entries(p.vials).map(([k,n])=>quantityIcon('xp-'+k,n)).join('')+'</div></td></tr>';}).join('')+'</tbody></table>';};
function syncBuilderSlots(){const team=PreviewGame.constructionTeam(state.recruitedBuilders||0,tikoLevel(),state.jobs);state.builders=team.total;return team;}
const oldSyncGarrisons=syncGarrisons;syncGarrisons=function(){oldSyncGarrisons();syncBuilderSlots();};
tikoLevel=function(){const house=houseFor('tiko');return house&&!house.underConstruction?state.heroLevels.tiko:0;};
function assertTikoRemoval(houseId){if(homeLayout.garrisons.some(g=>g.hero==='tiko'&&g.caserneId===houseId)&&!syncBuilderSlots().canRemoveTiko)throw Error('Tiko est occupé : libère un constructeur avant de le retirer ou le remplacer.');}
discountLine=function(q){return q.costReduction||q.timeReduction?bonusCard('tiko',['Coût −'+(q.costReduction*100).toLocaleString('fr-FR',{maximumFractionDigits:1})+' %','Durée −'+(PreviewGame.builderHeroBonus(tikoLevel()).duration*100)+' %','+1 constructeur']):'';};
buildersPanel=function(){const team=syncBuilderSlots();return '<div class="builders-banner">'+art('ui:builder','builder-portrait')+'<div><h2>Les bâtisseurs</h2><b class="builder-total">'+team.free+' / '+team.total+' disponibles</b></div></div><div class="builder-grid">'+Array.from({length:5+Number(Boolean(tikoLevel()))},(_,i)=>{const bonus=i===5&&Boolean(tikoLevel()),owned=i<team.recruited||bonus,j=owned?state.jobs[bonus?team.recruited:i]:null,price=team.recruited?PreviewGame.PROGRESSION_V06.builderPrices[team.recruited-1]:0;return '<article class="paper-card builder-card '+(!owned?'locked-builder':'')+'">'+art(bonus?'hero:tiko':'ui:builder')+'<div><span class="detail-label">'+(bonus?'Aide de Tiko':'Constructeur '+(i+1))+'</span><h3>'+(!owned?'À recruter':j?esc(j.name):'Disponible')+'</h3>'+(j?'<b class="builder-time" data-ends-at="'+j.endsAt+'">'+exactTime((j.endsAt-Date.now())/1000)+'</b><div class="builder-actions">'+button('Voir','view-job','data-id="'+j.id+'"','secondary')+button('Accélérer','job-speed','data-id="'+j.id+'"','secondary')+button(quantityIcon('diamonds',PreviewGame.constructionFinishPrice(j.endsAt))+'Terminer','job-finish','data-id="'+j.id+'"')+'</div>':!owned&&i===team.recruited?button(price?quantityIcon('diamonds',price)+'Recruter':'Recruter gratuitement','buy-builder'):'')+'</div></article>';}).join('')+'</div>';};
const upgradeCheckBefore=upgradeCheck;upgradeCheck=function(o){syncBuilderSlots();if(o?.type==='caserne-heros'&&houseFor('tiko')?.id===o.id&&PreviewGame.occupiedBuilders(state.jobs)>=state.recruitedBuilders)throw Error('Libère un constructeur permanent avant le chantier de la caserne de Tiko.');return upgradeCheckBefore(o);};
function clanPurchasePanel(){const p=state.clanPurchase;if(!p)return '';const q=PreviewGame.clanShopQuote(p.id);return '<div class="confirmation">'+art(q.asset)+'<h2>'+q.name+'</h2><p>'+quantityIcon(q.resource,p.stock?q.wholesale:q.price)+'</p><div class="center-actions">'+button('Confirmer','clan-purchase-confirm','',p.stock?'secondary':'primary')+button('Annuler','back','','secondary')+'</div></div>';}
function acquiredPanel(){const p=state.acquired;return '<div class="acquired '+(p.hero?'hero-acquired':'')+'"><div class="acquired-sparkles">✦ ✧ ✦</div><small>'+(p.hero?'Un nouveau héros rejoint ton royaume':'Objet obtenu')+'</small><h2>'+(p.hero?'Félicitations !':esc(p.name))+'</h2>'+art(p.asset,'acquired-art')+'<b class="acquired-number">'+(p.hero?esc(p.name):'+'+(p.amount||1))+'</b>'+button('Continuer','acquired-close')+'</div>';}
renderModal=function(){const custom=state.modal==='clan-purchase'?clanPurchasePanel():state.modal==='acquired'?acquiredPanel():state.modal==='clan-info'?'<div class="information-sheet"><h2>'+({tech:'Technologies',contributors:'Classement des contributeurs',members:'Membres du clan'})[state.infoKind]+'</h2><p>'+({tech:'Un don par technologie toutes les deux heures. Chaque don rapporte deux diamants. Les dons font progresser la technologie et remplissent la trésorerie.',contributors:'Tous les contributeurs reçoivent un lot. Les dix premiers reçoivent les meilleurs lots, les rangs 11 à 15 un lot intermédiaire. Seuls les trois premiers reçoivent chacun un bouclier d’un jour. Le lot ressources total représente 1 % des dons de la semaine. Les montants affichés évoluent jusqu’à la clôture.',members:'Les sentinelles sont choisis pour la prochaine guerre. Les membres en réserve ne participent pas au tirage. La présence est visible uniquement dans ce clan.'})[state.infoKind]+'</p></div>':state.modal==='clan-replace'?'<h2>Remplacer un sentinelle</h2><div class="role-actions">'+state.clanChosen.map(id=>button(esc(state.members.find(m=>m.id===id)?.name),'role-replace','data-old="'+id+'"','secondary')).join('')+'</div>':state.modal==='clan-kick'?'<div class="confirmation"><h2>Exclure '+esc(state.members.find(m=>m.id===state.nominateId)?.name)+' ?</h2>'+button('Confirmer l’exclusion','clan-kick-confirm','','danger-button')+button('Annuler','back','','secondary')+'</div>':state.modal==='donation-boost'?'<div class="confirmation">'+icon('diamonds')+'<h2>Rendre ce don disponible</h2><p>'+quantityIcon('diamonds',PreviewGame.clanDonationAccelerationQuote(clanAccount(),state.boostTech).diamonds)+'</p>'+button('Confirmer','donation-boost-confirm')+button('Annuler','back','','secondary')+'</div>':null;
if(custom!==null){$('#modal-title').textContent=({acquired:'Ton royaume grandit','clan-purchase':'Confirmer l’achat','clan-info':'Informations','clan-replace':'Sentinelles','clan-kick':'Exclusion','donation-boost':'Accélérer'})[state.modal];$('#modal').classList.remove('shop-modal');$('#modal-body').innerHTML=custom;$('#modal-tabs').innerHTML='';}else if(state.modal==='clan'&&state.clan&&state.tab==='stock'){if(!officer()){state.tab='shop';}$('#modal-title').textContent=state.clan;$('#modal-body').innerHTML=clanShopPanel();$('#modal-tabs').innerHTML=clanTabs();}else polishModal();
if(state.modal==='clan'&&state.clan){if(!state.tab||state.tab==='overview'){state.tab='members';$('#modal-body').innerHTML=clanMembersPanel();}$('#modal-tabs').innerHTML=clanTabs();}enhanceSelects();setTimeout(()=>refreshTutorialPointer?.(),0);};
function clanTabs(){return tabs([['members','Membres'],['tech','Technologies'],['shop','Boutique'],...(officer()?[['stock','Approvisionnement']]:[]),['contributors','Contributeurs']]);}
function rewardFloat(asset,text,node=null){const el=document.createElement('div');el.className='reward-float';el.innerHTML=art(asset)+'<b>'+esc(text)+'</b>';const r=node?.getBoundingClientRect?.();if(r){el.style.left=r.left+r.width/2+'px';el.style.top=r.top+'px';}document.body.append(el);setTimeout(()=>el.remove(),2300);}
renderHUD=function(){syncBuilderSlots();polishHUD();$('#research-launch')?.remove();$('#hud .castle-tools')?.remove();const b=$('.builder-launch');if(b)b.innerHTML=art('ui:builder')+'<span>'+Math.max(0,state.builders-PreviewGame.occupiedBuilders(state.jobs))+' / '+state.builders+'</span>';};
action=function(a,d={},node){try{
if(a==='map-return'){state.mapPage=null;close(true);return;}
if(a==='clan-info'){state.infoKind=d.kind;open('clan-info');return;}
if(a==='clan-restock-prepare'||a==='clan-buy-prepare'){if(a==='clan-restock-prepare'&&!officer())throw Error('Responsables uniquement.');state.clanPurchase={id:d.id,stock:a==='clan-restock-prepare',commandId:currentId('clan-shop')};open('clan-purchase');return;}
if(a==='clan-purchase-confirm'){const p=state.clanPurchase;if(!p)throw Error('Confirmation expirée.');const q=PreviewGame.clanShopQuote(p.id),r=p.stock?PreviewGame.restockClanShop(clanAccount(),state.clanData,p.id,1,{commandId:p.commandId}):PreviewGame.buyClanShopItem(clanAccount(),state.clanData,p.id,{commandId:p.commandId});acceptClan(r);state.clanPurchase=null;state.modal='clan';state.tab=p.stock?'stock':'shop';navStack.length=0;renderModal();state.acquired={name:q.name,asset:q.asset,amount:1};open('acquired');return;}
if(a==='acquired-close'){navigateBack();return;}
if(a==='donation-boost-prepare'){state.boostTech=d.id;open('donation-boost');return;}
if(a==='donation-boost-confirm'){acceptClan(PreviewGame.accelerateClanDonation(clanAccount(),state.clanData,state.boostTech,{commandId:currentId('boost')}));navigateBack();return;}
if(a==='clan-donation'){const r=PreviewGame.donateClanTechnology(clanAccount(),state.clanData,d.id,{commandId:currentId('don')});acceptClan(r);rewardFloat('item:diamonds','+5',node);state.metrics&&(state.metrics.donations++);return;}
if(a==='role-representative'){if(!officer())throw Error('Responsables uniquement.');if(state.clanChosen.includes(d.id)){state.clanChosen=state.clanChosen.filter(id=>id!==d.id);renderModal();return;}if(state.clanChosen.length>=3+state.clanTech.selection){open('clan-replace');return;}state.clanChosen.push(d.id);state.clanExcluded=state.clanExcluded.filter(id=>id!==d.id);renderModal();return;}
if(a==='role-replace'){if(!officer()||!state.clanChosen.includes(d.old))throw Error('Sentinelle introuvable.');state.clanChosen=state.clanChosen.map(id=>id===d.old?state.nominateId:id);state.clanExcluded=state.clanExcluded.filter(id=>id!==state.nominateId);navigateBack();return;}
if(a==='clan-kick-prepare'){open('clan-kick');return;}
if(a==='clan-kick-confirm'){if(!officer()||['chief','admin'].includes(clanMemberRole(state.members.find(m=>m.id===state.nominateId))))throw Error('Ce responsable ne peut pas être exclu.');state.members=state.members.filter(m=>m.id!==state.nominateId);state.clanChosen=state.clanChosen.filter(id=>id!==state.nominateId);state.clanExcluded=state.clanExcluded.filter(id=>id!==state.nominateId);navStack.length=0;open('clan','members');return;}
if(a==='buy-builder'){if(state.recruitedBuilders>=5)return;const price=state.recruitedBuilders?PreviewGame.PROGRESSION_V06.builderPrices[state.recruitedBuilders-1]:0;enoughDiamonds(price);state.wallet.diamonds-=price;state.recruitedBuilders++;syncBuilderSlots();renderHUD();renderModal();rewardFloat('ui:builder','+1 constructeur');return;}
if(a==='housing-clear'){assertTikoRemoval(d.id);}
if(a==='housing-assign'||a==='hero-house-assign'){const house=a==='housing-assign'?d.id:$('#hero-housing-choice')?.value;assertTikoRemoval(house);}
if(['formation','hero-defense'].includes(a)&&d.id==='tiko'&&houseFor('tiko'))assertTikoRemoval(houseFor('tiko').id);
if(a==='select-open'){showSelect(d.id,node);return;}
const beforeHeroes=new Set(state.ownedHeroes),p=state.purchase,beforeWallet={...state.wallet};polishAction(a,d,node);
if(a==='purchase-confirm'&&p&&!p.structure&&p.currency!=='eur'&&state.wallet[p.currency]<beforeWallet[p.currency]){if(p.hero&&!beforeHeroes.has(p.hero)){state.acquired={hero:true,asset:p.asset,name:p.name};open('acquired');}else if(p.item){state.acquired={asset:p.asset,name:p.name,amount:1};open('acquired');}}
}catch(e){toast(e.message);}};
// Listes dessinées hors du stage mis à l’échelle : 18 px réels, même sur mobile.
let selectPopover=null;
function closeSelect(){selectPopover?.remove();selectPopover=null;}
function enhanceSelects(){for(const select of document.querySelectorAll('#modal select:not([multiple])')){if(select.dataset.enhanced)continue;select.dataset.enhanced='true';select.id||='select-'+currentId('ui');const trigger=document.createElement('button');trigger.className='game-select-trigger';trigger.dataset.action='select-open';trigger.dataset.id=select.id;trigger.disabled=select.disabled;trigger.innerHTML=esc(select.querySelector('option[selected]')?.textContent||select.options[select.selectedIndex]?.textContent||select.options[0]?.textContent)+'<span>⌄</span>';select.after(trigger);select.classList.add('native-select-hidden');select.addEventListener('change',()=>{trigger.innerHTML=esc(select.options[select.selectedIndex]?.textContent)+'<span>⌄</span>';});}}
function showSelect(id,node){closeSelect();const select=document.getElementById(id);if(!select||select.disabled)return;const el=document.createElement('div');el.className='game-select-popover';el.setAttribute('role','listbox');for(const option of select.options){const b=document.createElement('button');b.textContent=option.textContent;b.disabled=option.disabled;b.className=option.selected?'selected':'';b.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));closeSelect();});el.append(b);}document.body.append(el);const r=logicalRect0303(node),w=Math.min(Math.max(260,r.width),playWidth0303()-24);el.style.width=w+'px';el.style.left=Math.min(playWidth0303()-w-12,Math.max(12,r.left))+'px';el.style.maxHeight=Math.min(400,playHeight0303()-30)+'px';el.style.top=Math.max(12,Math.min(r.bottom+5,playHeight0303()-150))+'px';selectPopover=el;const h=el.getBoundingClientRect().height;if(r.bottom+h>playHeight0303()-10)el.style.top=Math.max(12,r.top-h-5)+'px';}
document.addEventListener('pointerdown',e=>{if(selectPopover&&!e.target.closest('.game-select-popover,.game-select-trigger'))closeSelect();});
// Une scène fixe avec caméra ; un glissement rapide déplace la vue, un maintien déplace un bâtiment.
const cameraPointers=new Map();let cameraGesture=null,lastCameraInput=0;
const stagePoint=e=>{const r=logicalRect0303($('#stage')),p=logicalPoint0303(e.clientX,e.clientY),s=playWidth0303()/1600;return {x:(p.x-r.left)/s,y:(p.y-r.top)/s};};
document.addEventListener('pointerdown',e=>{if(e.button>0||state.modal||!e.target.closest('#world-camera')||e.target.closest('.combat-entry'))return;const p=stagePoint(e);cameraPointers.set(e.pointerId,p);lastCameraInput=Date.now();if(cameraPointers.size===2){if(drag){clearTimeout(drag.timer);drag.ghost?.remove();drag=null;state.edit=null;renderCastle();}const [a,b]=[...cameraPointers.values()];cameraGesture={pinch:true,distance:Math.hypot(a.x-b.x,a.y-b.y),z:state.camera.z,cx:(a.x+b.x)/2,cy:(a.y+b.y)/2,x:state.camera.x,y:state.camera.y};}else cameraGesture={pinch:false,id:e.pointerId,start:p,x:state.camera.x,y:state.camera.y,moved:false};});
document.addEventListener('pointermove',e=>{if(!cameraPointers.has(e.pointerId)||!cameraGesture||drag?.started)return;const p=stagePoint(e);cameraPointers.set(e.pointerId,p);const g=cameraGesture;if(g.pinch&&cameraPointers.size===2){const [a,b]=[...cameraPointers.values()],z=Math.max(.55,Math.min(2.1,g.z*Math.hypot(a.x-b.x,a.y-b.y)/g.distance)),cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;state.camera={z,x:cx-(g.cx-g.x)*z/g.z,y:cy-(g.cy-g.y)*z/g.z};g.moved=true;}else if(g.id===e.pointerId){const dx=p.x-g.start.x,dy=p.y-g.start.y;if(!g.moved&&Math.hypot(dx,dy)<8)return;g.moved=true;if(drag){clearTimeout(drag.timer);drag=null;}state.camera.x=g.x+dx;state.camera.y=g.y+dy;}else return;suppressClickUntil=Date.now()+300;lastCameraInput=Date.now();applyCamera();e.preventDefault();},{passive:false});
const endCamera=e=>{cameraPointers.delete(e.pointerId);if(cameraGesture?.moved)suppressClickUntil=Date.now()+300;if(!cameraPointers.size)cameraGesture=null;};document.addEventListener('pointerup',endCamera);document.addEventListener('pointercancel',endCamera);
document.addEventListener('wheel',e=>{if(state.modal||!e.target.closest('#world-camera'))return;const p=stagePoint(e),before=state.camera.z,z=Math.max(.55,Math.min(2.1,before*Math.exp(-e.deltaY*.001)));state.camera={z,x:p.x-(p.x-state.camera.x)*z/before,y:p.y-(p.y-state.camera.y)*z/before};lastCameraInput=Date.now();applyCamera();e.preventDefault();},{passive:false});
