function exportMapLayouts(){const blob=new Blob([JSON.stringify(state.mapLayouts,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Blabox_Cartes_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
campaignPoints=function(){return state.mapLayouts.maps.campaign.routes[0].nodes.filter(n=>n.kind==='castle').map(n=>({...n}));};
warPoints=function(rows,enemy){const route=state.mapLayouts.maps.war.routes.find(r=>r.id===(enemy?'enemy':'ally'));return route.nodes.filter(n=>n.kind==='castle').map(n=>({...rows[n.slot],...n,mapNodeId:n.id,id:rows[n.slot]?.id,enemy}));};
function mapDotsMarkup(map){return '<svg class="map-dot-routes" viewBox="0 0 '+map.width+' '+map.height+'" aria-hidden="true">'+map.routes.map(r=>'<g class="route-'+r.id+'">'+PreviewGame.routeDots(r).map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="5.5"/>').join('')+'</g>').join('')+'</svg>';}
renderFullMap=function(reset=false){
 const el=fullMapLayer(),old=$('.full-map-scroll'),sx=old?.scrollLeft||0,sy=old?.scrollTop||0,war=state.mapPage==='war',progress=campaignProgress(),map=state.mapLayouts.maps[war?'war':'campaign'];
 const icons=war?[...warPoints(state.warRoster,false),...warPoints(state.warEnemy,true)].map(p=>{const done=p.enemy&&warEligibility(p.id).conquered,kind=p.role==='chief'?'chief':p.role==='random'?'scout':'representative';return '<button class="journey-castle war-castle '+p.role+' '+(p.enemy?'enemy ':'ally ')+(done?'done':'')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="war-node" data-id="'+esc(p.id)+'" data-side="'+(p.enemy?'enemy':'ally')+'" data-map-node="'+p.mapNodeId+'">'+art('war:castle:'+kind+(done?':ruined':p.enemy?':enemy':''))+'<b class="map-order">'+p.number+'</b><strong>'+esc(p.name)+'</strong><small>'+esc(currentRoles[p.role])+' · '+p.points+' pts</small>'+(done?'<i>✓</i>':'')+'</button>';}).join(''):campaignPoints().map(p=>{const cleared=state.campaignCleared.includes(p.stage),available=p.stage<=progress.next;return '<button class="journey-castle '+(cleared?'done':p.stage===progress.next?'current':'locked')+'" style="left:'+p.x+'px;top:'+p.y+'px" data-action="campaign-stage" data-stage="'+p.stage+'" data-map-node="'+p.id+'" '+(!available?'disabled':'')+' aria-label="Étape '+p.stage+'">'+art('war:castle:'+([9,15,23,30].includes(p.stage)?'representative':'scout')+':enemy')+'<b>'+p.number+'</b>'+stars(state.campaignStars[p.stage]||0)+'</button>';}).join('');
 el.hidden=false;el.innerHTML='<div class="full-map-scroll"><div class="full-map-world '+(war?'war-world':'campaign-world')+'" style="width:'+map.width+'px;height:'+map.height+'px">'+art(war?'war:map':'campaign:unified','full-map-art')+mapDotsMarkup(map)+icons+'</div></div>'+button('×','map-return','aria-label="Fermer la carte"','map-close')+'<div class="full-map-footer">'+(war?button('Récompenses','open','data-page="war-rewards"','secondary')+'<div class="map-compact-score"><b>'+state.warAttacks.filter(a=>a.playerId===state.id&&a.day===state.warDay&&a.status==='won').length+' / 10</b><small>'+warEligibility('_').remaining+' chances</small></div>':button(progress.next>30?'Campagne terminée':'Combat '+progress.next,'campaign-stage','data-stage="'+Math.min(30,progress.next)+'" '+(progress.next>30?'disabled':'')))+'</div>';
 const scroll=$('.full-map-scroll');if(reset){const n=war?map.routes[0].nodes.find(n=>n.kind==='castle'&&n.slot===0):campaignPoints().find(n=>n.stage===Math.min(30,progress.next));scroll.scrollLeft=Math.max(0,(n?.x||0)-(scroll.clientWidth||1600)/2);scroll.scrollTop=Math.max(0,(n?.y||0)-(scroll.clientHeight||720)/2);}else {scroll.scrollLeft=sx;scroll.scrollTop=sy;}
};
const mapSettingsBefore=settings;settings=function(){return mapSettingsBefore()+'<div class="detail-actions">'+button('Agencement des cartes','open','data-page="map-layout"','secondary')+'</div>';};
const mapModalBefore=renderModal;renderModal=function(){if(state.modal!=='map-layout'){mapModalBefore();return;}$('#modal-title').textContent='Agencement des cartes';$('#modal-tabs').innerHTML='';$('#modal').classList.remove('shop-modal');$('#modal-body').innerHTML='<div class="map-import-panel"><h2>Campagne et guerre des clans</h2><p>Importe le fichier JSON exporté par l’éditeur des cartes.</p><label class="map-import-file">Importer un agencement<input id="map-layout-file" type="file" accept=".json,application/json"></label><div class="center-actions">'+button('Exporter l’agencement actuel','map-layout-export','', 'secondary')+button('Restaurer les positions initiales','map-layout-reset','','secondary')+'</div><p id="map-import-status" role="status">30 étapes · 10 alliés · 10 ennemis</p></div>';};
const mapActionBefore=action;action=function(a,d,node){if(a==='campaign-stage'){const stage=Number(d.stage);if(!Number.isInteger(stage)||stage<1||stage>30||stage>campaignProgress().next)throw Error('Termine le château précédent.');state.campaignStage=stage;state.region=Math.floor((stage-1)/8);state.stage=(stage-1)%8+1;open('stage');return;}if(a==='map-layout-export'){exportMapLayouts();return;}if(a==='map-layout-reset'){applyMapLayouts(MODELS.MAP_LAYOUTS);$('#map-import-status').textContent='Positions initiales restaurées.';return;}return mapActionBefore(a,d,node);};
document.addEventListener('change',async e=>{if(e.target.id!=='map-layout-file'||!e.target.files?.[0])return;const status=$('#map-import-status');try{if(e.target.files[0].size>2000000)throw Error('Fichier de cartes trop volumineux.');applyMapLayouts(JSON.parse(await e.target.files[0].text()));status.textContent='Agencement importé. Tes deux cartes sont à jour.';}catch(error){status.textContent='Import refusé : '+error.message;}e.target.value='';});
window.blaboxMapLayouts=Object.freeze({inspect:()=>structuredClone(state.mapLayouts),apply:applyMapLayouts,reset:()=>applyMapLayouts(MODELS.MAP_LAYOUTS)});

// Le prochain combat passe à 31 quand les 30 étapes sont terminées.
campaignProgress=function(){const cleared=new Set(state.campaignCleared),next=Array.from({length:30},(_,i)=>i+1).find(n=>!cleared.has(n))||31;return {cleared,next};};

// Cette extension relie les sons à des transitions effectives, sans modifier la simulation.
