const audioKey='blabox-audio-preferences-v1';
let audioPreferences={enabled:true,musicEnabled:true,volumes:{...AUDIO_MANIFEST.mixing.defaults}},audioActionError=false;
try{const p=JSON.parse(window.localStorage?.getItem(audioKey)||'null');if(p?.volumes)audioPreferences={...audioPreferences,...p};}catch{}
