for(const [k,v]of Object.entries(state.audioVolumes))gameAudio.setVolume(k,v);
gameAudio.setEnabled(state.sound);gameAudio.setMusic(audioPreferences.musicEnabled);
function persistAudio(){audioPreferences={enabled:state.sound,musicEnabled:gameAudio.inspect().musicEnabled,volumes:{...state.audioVolumes}};try{window.localStorage?.setItem(audioKey,JSON.stringify(audioPreferences));}catch{}}
function audioScene(){return document.body.classList.contains('battle-mode')?'battle':state.mapPage||'castle';}
function syncAudioScene(){gameAudio.setScene(audioScene());gameAudio.setEnabled(state.sound);}
function audioCue(id,options){gameAudio.play(id,options);}
// Les anciens bips synthétiques par shot/dead sont remplacés par le filtrage ci-dessous.
testSound=function(kind,force=false){if(force)audioCue(kind==='break'?'hit.collapse':kind==='reward'?'reward.item':'hit.stone',{force:true});};
toggleMusic=function(){personalAudio?.pause();gameAudio.setMusic(!gameAudio.inspect().musicEnabled);persistAudio();};
audioPanel=function(){const a=gameAudio.inspect(),song=AUDIO_MANIFEST.music.find(m=>m.id===a.musicId)||AUDIO_MANIFEST.music.find(m=>m.scene===(audioScene()==='battle'?'castle':audioScene()));return '<div class="audio-track-card"><span class="audio-note">♫</span><div><small>Ambiance actuelle</small><h2>'+esc(song?.title||'Exploration')+'</h2></div>'+button(a.musicEnabled?'Couper la musique':'Activer la musique','audio-music','','secondary')+'</div><div class="audio-settings">'+[['music','Musique'],['effects','Effets'],['voices','Voix importée']].map(([id,label])=>'<label>'+label+'<input aria-label="Volume '+label+'" type="range" min="0" max="100" data-volume="'+id+'" value="'+Math.round(state.audioVolumes[id]*100)+'"><b>'+Math.round(state.audioVolumes[id]*100)+' %</b></label>').join('')+'</div><div class="center-actions">'+button('Tester un impact','audio-test','data-kind="hit"','secondary')+button('Tester une récompense','audio-test','data-kind="reward"','secondary')+button('Tester la voix importée','audio-voice',personalVoice?'':'disabled','secondary')+'</div><details class="personal-audio"><summary>Pistes personnelles</summary><label>Importer une musique<input id="personal-audio" type="file" accept="audio/*"></label>'+button('Écouter ma piste','audio-personal',personalAudio?'':'disabled','secondary')+'<label>Importer une voix<input id="personal-voice" type="file" accept="audio/*"></label></details>';};
const audioToastBefore=toast;toast=function(message){audioToastBefore(message);if(/pas assez|insuffisant|impossible|indisponible|refus|invalide|inconnu|introuvable|bloqué|occupé|pleine|plus disponible|expir|déjà|requis|au niveau|dois être|il te manque|il te faut|choisis une case|emplacement|choisis une mine|termine d’abord|responsables uniquement|a besoin|libère un|sélectionne une/i.test(message)){if(audioActionDepth)audioActionError=true;audioCue(/emplacement|occupé|case|placement/i.test(message)?'edit.reject':'ui.blocked');}};
let audioActionDepth=0;
const audioActionBefore=action;
function soundSnapshot(){return {battle:state.battle,modal:state.modal,map:state.mapPage,selected:state.selected,wallet:{...state.wallet},jobIds:new Set(state.jobs.map(j=>j.id)),research:state.research,researchFunding:JSON.stringify(state.researchFunding),queue:JSON.stringify(state.recruitment),builders:state.recruitedBuilders,claimed:state.claimed.size,claims:state.progressClaims.length,owned:state.ownedHeroes.size,vials:JSON.stringify(state.vials),inventory:JSON.stringify(state.inventory),garrisons:JSON.stringify(homeLayout.garrisons),edit:state.edit,tech:JSON.stringify(state.clanTech),levels:JSON.stringify(state.heroLevels)};}
action=function(a,d={},node){
 const outer=audioActionDepth===0;if(outer){audioActionError=false;gameAudio.unlock();}const before=soundSnapshot();audioActionDepth++;
 try{audioActionBefore(a,d,node);}finally{audioActionDepth--;syncAudioScene();}
 if(!outer||audioActionError)return;
 if(a==='audio-personal'){if(!state.sound){toast('Active le son dans les paramètres.');return;}gameAudio.setMusic(false);if(personalAudio){if(personalAudio.paused)personalAudio.play()?.catch(()=>toast('Cette piste ne peut pas être lue.'));else personalAudio.pause();}persistAudio();return;}
 if(a==='setting'&&d.id==='sound'){gameAudio.setEnabled(state.sound);if(!state.sound){personalAudio?.pause();personalVoice?.pause();}persistAudio();return;}
 if(a==='audio-music'||a==='audio-test'||a==='audio-voice'){if(!state.sound)personalVoice?.pause();return;}
 const newJobs=state.jobs.filter(j=>!before.jobIds.has(j.id));
 if(before.battle!==state.battle&&state.battle&&!state.battle.replay)audioCue('battle.found');
 else if(newJobs.length){audioCue(newJobs[0].floorJob?'build.floor':'build.start');audioCue('build.work');}
 else if(state.recruitedBuilders>before.builders)audioCue('build.worker');
 else if(a==='collect'&&(state.wallet.gold>before.wallet.gold||state.wallet.elixir>before.wallet.elixir))audioCue(state.wallet.gold>before.wallet.gold?'resource.gold':'resource.elixir');
 else if(a==='clan-donation'&&state.wallet.diamonds>before.wallet.diamonds)audioCue(before.tech!==JSON.stringify(state.clanTech)?'clan.tech':'clan.donation');
 else if(['progress-claim','claim','gift-claim','code-redeem','settings-code-redeem','return-claim','war-claim','mine-help'].includes(a)&&(state.progressClaims.length>before.claims||state.claimed.size>before.claimed||JSON.stringify(state.wallet)!==JSON.stringify(before.wallet)||JSON.stringify(state.inventory)!==before.inventory||JSON.stringify(state.vials)!==before.vials))audioCue(a==='progress-claim'&&d.key?.startsWith('achievement')?'reward.achievement':a==='return-claim'?'reward.loyalty':'reward.quest');
 else if(state.ownedHeroes.size>before.owned)audioCue('reward.unlock');
 else if(before.levels!==JSON.stringify(state.heroLevels))audioCue('build.upgraded');
 else if(a==='place'&&before.edit&&!state.edit)audioCue('edit.place');
 else if(['move','door'].includes(a)&&state.edit)audioCue('edit.pickup');
 else if(a==='select'&&state.selected===d.id){const o=object(d.id),id=o?.type;audioCue(id==='core'?'select.core':id==='mine'?'select.mine':['extracteur','reservoir'].includes(id)?'select.elixir':id==='reserve'?'select.gold-store':id==='forge'?'select.forge':['academie','atelier-monstres'].includes(id)?'select.academy':id==='mana'?'select.mana':layout.traps.includes(o)?'select.trap':layout.decorations.includes(o)?'select.decor':layout.defenses.includes(o)?'select.defense':'select.barracks');}
 else if(['back','acquired-close'].includes(a))audioCue('ui.back');
 else if(['close','map-return','chat-close'].includes(a))audioCue('ui.close');
 else if(['tab','category','channel'].includes(a))audioCue('ui.tab');
 else if(['recruit','recruit-confirm'].includes(a)&&before.queue!==JSON.stringify(state.recruitment))audioCue('army.queue');
 else if(a==='research-fund'&&(before.research!==state.research||before.researchFunding!==JSON.stringify(state.researchFunding)))audioCue('army.research');
 else if(/speed|finish-confirm|diamond-confirm|boost-confirm/.test(a)&&state.wallet.diamonds<before.wallet.diamonds)audioCue('build.speed');
 else if(a==='recovery-use'&&before.inventory!==JSON.stringify(state.inventory))audioCue(d.id.startsWith('mana')?'resource.mana':'resource.potion');
 else if(a==='vial'&&before.vials!==JSON.stringify(state.vials))audioCue('resource.potion');
 else if(a==='use-item'&&d.id?.startsWith('shield')&&before.inventory!==JSON.stringify(state.inventory))audioCue('resource.shield-on');
 else if(a==='clan-purchase-confirm'&&state.clanPurchase===null)audioCue(state.tab==='stock'?'clan.stock':'reward.item');
 else if(['purchase-confirm','cosmetic-buy','resource-claim'].includes(a)&&JSON.stringify(state.wallet)!==JSON.stringify(before.wallet))audioCue(a==='resource-claim'?'resource.'+d.id:'resource.spend');
 else if(state.modal!==before.modal||state.mapPage!==before.map)audioCue(state.mapPage!==before.map&&state.mapPage?'ui.map':state.modal==='inbox'?'social.mail':state.modal==='pvp'?'battle.search':'ui.open');
 else if(a==='setting')audioCue('ui.toggle');
 else if(!['deploy-unit','spell','cast-hero','cast-dismiss'].includes(a))audioCue(a.includes('confirm')?'ui.confirm':'ui.click');
};
const audioDragBefore=startDrag;startDrag=function(){const first=drag&&!drag.started;audioDragBefore();if(first&&drag?.started)audioCue('edit.pickup');};
const audioCompleteBefore=completeJobs;completeJobs=function(){const jobs=[...state.jobs],research=state.research;audioCompleteBefore();const done=jobs.filter(j=>!state.jobs.some(k=>k.id===j.id));if(done.length)audioCue(done.some(j=>j.to>1)?'build.upgraded':'build.complete');if(research&&!state.research)audioCue('army.research-done');};
const audioAcceptBefore=acceptRecruitment;acceptRecruitment=function(s){audioAcceptBefore(s);if(s.delivered?.length)audioCue('army.ready');};
const audioOpenBefore=open;open=function(...args){const r=audioOpenBefore(...args);syncAudioScene();return r;};
const audioCloseBefore=close;close=function(...args){const r=audioCloseBefore(...args);syncAudioScene();return r;};
const audioStopBefore=stopBattle;stopBattle=function(...args){const r=audioStopBefore(...args);syncAudioScene();return r;};
const audioFrames=new WeakMap();
function frameAudio(f){
 const b=state.battle;if(!b)return;let m=audioFrames.get(b);if(!m){m={seq:0,stars:0,started:false,secured:false,result:false,warning:false};audioFrames.set(b,m);}
 const st=typeof f.started==='boolean'?f.started:f.time>0;
 if(st&&!m.started){audioCue('battle.start');m.started=true;}
 const fresh=f===b.engine?(f.events||[]).slice(m.eventCursor||0):(f.events||[]).filter(e=>e.seq>m.seq);if(f===b.engine)m.eventCursor=(f.events||[]).length;
 for(const cue of PreviewGame.battleSoundEvents({...f,events:fresh})){if(cue.seq<=m.seq)continue;audioCue(cue.id,{variant:cue.seq});}for(const ev of fresh)m.seq=Math.max(m.seq,ev.seq||0);
 if(Date.now()>=(m.fireCheckAt||0)){m.fireCheckAt=Date.now()+2500;const visible=f.structures.some(s=>{if(s.hero||s.guard||s.hp>=s.maxHp*.3)return false;const r=$('.building[data-id="'+s.id+'"]')?.getBoundingClientRect?.();return r&&r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth;});if(visible)audioCue('hit.fire');}
 const n=f.destruction?.stars||0;if(n>m.stars){audioCue('battle.star');m.stars=n;}
 if(f.victorySecured&&!m.secured){m.secured=true;audioCue('battle.secured');}
 if(st&&900-f.time<=60&&!m.warning){m.warning=true;audioCue('battle.warning');}
 if(f.status&&f.status!=='running'&&!m.result){m.result=true;gameAudio.duck();audioCue(f.status==='won'?'battle.win':'battle.lose');}
}
const audioFrameBefore=renderBattleFrame;renderBattleFrame=function(f){audioFrameBefore(f);frameAudio(f);};
document.addEventListener('pointerdown',()=>gameAudio.unlock(),{capture:true});
document.addEventListener('click',e=>{if(e.target.closest('button')?.disabled){gameAudio.unlock();audioCue('ui.blocked');}},{capture:true});
document.addEventListener('change',e=>{if(e.target.id==='personal-audio'&&e.target.files?.[0]&&state.modal==='audio')renderModal();});
document.addEventListener('visibilitychange',()=>{gameAudio.setHidden(Boolean(document.hidden));personalAudio?.pause();personalVoice?.pause();});
document.addEventListener('input',e=>{const id=e.target.dataset.volume;if(id){gameAudio.setVolume(id,Number(e.target.value)/100);state.audioVolumes[id]=Number(e.target.value)/100;persistAudio();const label=e.target.closest('label')?.querySelector('b');if(label)label.textContent=e.target.value+' %';}if(e.target.matches?.('input[type="range"]:not([data-volume])'))audioCue('ui.adjust');});
document.addEventListener('submit',e=>{gameAudio.unlock();if(e.target.id==='chat-form')audioCue('social.send');if(e.target.id==='report-form')audioCue('social.report');});
const audioNotifyBefore=notifyGame;notifyGame=function(...args){const n=state.notificationsLog.length;audioNotifyBefore(...args);if(state.notificationsLog.length>n)audioCue('ui.notice');};
let previousEnergy=state.energy,previousShield=state.shieldUntil;const audioMinesFull=new Set();
setInterval(()=>{syncAudioScene();gameAudio.refresh();if(state.energy>previousEnergy)audioCue('resource.energy');previousEnergy=state.energy;if(previousShield>Date.now()&&state.shieldUntil<=Date.now())audioCue('resource.shield-off');previousShield=state.shieldUntil;const full=homeLayout.buildings.filter(o=>['mine','extracteur'].includes(o.type)&&o.stored>=mineCapacity(o));for(const o of full)if(!audioMinesFull.has(o.id))audioCue('resource.full');audioMinesFull.clear();full.forEach(o=>audioMinesFull.add(o.id));if(state.modal||state.battle){if(!document.body.classList.contains('battle-mode'))gameAudio.stopAmbient();return;}const rect=$('#castle')?.getBoundingClientRect?.();gameAudio.stopAmbient();},1000);

// Une fenêtre neuve repart en haut ; Retour restaure le panneau parent.
const stabilityOpen=open,stabilityModal=renderModal;
function updateReadableUI(){
 const scale=playWidth0303()/1600;
 const viewport=$('#viewport');if(viewport)viewport.scrollTop=viewport.scrollLeft=0;
 document.documentElement.style.setProperty('--ui-copy',Math.max(18,14/scale)+'px');
 document.documentElement.style.setProperty('--ui-small',Math.max(15,12/scale)+'px');
 document.documentElement.style.setProperty('--ui-button',Math.max(19,14/scale)+'px');
 document.documentElement.style.setProperty('--ui-touch',Math.max(44,36/scale)+'px');
 document.documentElement.style.setProperty('--ui-title',Math.max(30,18/scale)+'px');
}
open=function(page,tab=null){
 stabilityOpen(page,tab);
 if(state.modal===page){
  const body=$('#modal-body');if(body)body.scrollTop=body.scrollLeft=0;
  for(const el of document.querySelectorAll('#modal .shop-products,#modal .purchase-ledger,#modal .member-list'))el.scrollTop=el.scrollLeft=0;
 }
 if(typeof scheduleGuidePointer==='function')scheduleGuidePointer();
};
renderModal=function(){
 $('#modal').classList.remove('tutorial-modal');stabilityModal();
 $('#modal').classList.toggle('tutorial-modal',guideActive());
 $('#modal').classList.toggle('no-modal-tabs',!$('#modal-tabs').textContent.trim());
 if(typeof scheduleGuidePointer==='function')scheduleGuidePointer();
};
fitCastle=function(){
 const zone=$('#castle-zone'),floors=layout.floors+Number(!state.battle&&state.jobs.some(j=>j.floorJob));
 const width=layout.slots*CW()+104,height=floors*fh()+82;
 const fit=Math.min(.85,Math.max(.25,((zone.clientWidth||1050)-24)/width),Math.max(.25,((zone.clientHeight||490)-18)/height));
 const castle=$('#castle');castle.style.zoom='';castle.style.width=width+'px';castle.style.height=height+'px';
 castle.style.left=((zone.clientWidth||1050)-width)/2+'px';castle.style.transform='scale('+fit+')';
 castle.style.setProperty('--content-width',layout.slots*CW()+'px');castle.style.setProperty('--floor-count',floors);
 castle.style.margin='0';zone.scrollTop=zone.scrollLeft=0;applyCamera();
};
