const refinementHUD=renderHUD,refinementModal=renderModal,refinementMap=renderFullMap;
const refinementDetail=structureDetail,refinementAction=action,refinementAppearance=applyAppearance;
const CASTLE_PRESENTATION={
 'skin-astral':{side:52,top:50,bottom:32},
 'skin-frost':{side:86,top:116,bottom:66},
 'skin-obsidian':{side:98,top:134,bottom:72},
 'skin-castillet':{side:168,top:175,bottom:92},
 ...Object.fromEntries(['terre','bois','braise','givre'].map(id=>['skin-campagne-'+id,{side:112,top:105,bottom:55}]))
};
function sceneAnchors(){
 const zone=$('#castle-zone'),castle=$('#castle'),center=zone.offsetLeft+zone.clientWidth/2;
 const fit=Number(castle.dataset.fit)||.85,feet=zone.offsetTop+zone.clientHeight+8*fit;
 const bg=state.previewCosmetic?.kind==='background'?state.previewCosmetic.id:state.cosmetics.background;
 const anchor=MODELS.SCENE_LAYOUTS?.[bg]?.platform||[.5,.735];
 const width=1760,height=width*900/1600;
 cameraLayer().style.setProperty('--scene-image-width',width+'px');
 cameraLayer().style.setProperty('--scene-image-height',height+'px');
 cameraLayer().style.setProperty('--scene-image-x',(center-width*anchor[0]+900)+'px');
 cameraLayer().style.setProperty('--scene-image-y',(feet-height*anchor[1]+900)+'px');
 castle.dataset.platformCenter=String(center);
 castle.dataset.platformFeet=String(feet);
}
fitCastle=function(){
 const zone=$('#castle-zone'),castle=$('#castle'),floors=layout.floors+Number(!state.battle&&state.jobs.some(j=>j.floorJob));
 const skin=castle.dataset.skin||state.cosmetics.skin,m=CASTLE_PRESENTATION[skin]||CASTLE_PRESENTATION['skin-astral'];
 const content=layout.slots*CW(),width=content+2*m.side,height=floors*fh()+m.top+m.bottom;
 const fit=Math.min(.85,Math.max(.25,((zone.clientWidth||1050)-24)/width),Math.max(.25,((zone.clientHeight||490)-18)/height));
 Object.assign(castle.style,{zoom:'',position:'absolute',width:width+'px',height:height+'px',left:((zone.clientWidth||1050)-width)/2+'px',top:'auto',bottom:'0',margin:'0',transform:'scale('+fit+')',transformOrigin:'50% 100%'});
 for(const [key,value]of Object.entries({'content-width':content+'px','floor-count':floors,'castle-side':m.side+'px','castle-top':m.top+'px','castle-bottom':m.bottom+'px'}))castle.style.setProperty('--'+key,value);
 castle.dataset.fit=String(fit);castle.dataset.presentation=skin;zone.scrollTop=zone.scrollLeft=0;
 applyCamera();sceneAnchors();
};
applyAppearance=function(){refinementAppearance();if($('#castle-zone'))sceneAnchors();};
manaMarkup=function(battle=false){
 const m=battle?(state.battle?.replay?state.battle.history.frames[state.battle.cursor]?.mana:state.battle?.engine?.mana):state.recovery.mana;
 if(!m?.capacity)return '';
 const amount=Math.max(0,Math.min(m.capacity,m.amount)),ratio=amount/m.capacity;
 const wait=Math.ceil((Math.min(m.capacity,Math.floor(amount+1e-9)+1)-amount)/PreviewGame.MANA_RULES.perSecond);
 const caption=battle?'':m.enabled===false?'En construction':amount>=m.capacity-1e-8?'Mana complet':'+1 dans '+exactTime(wait);
 const dots=Array.from({length:5},(_,i)=>'<i class="'+(ratio>i/5?'':'empty')+'"><em style="width:'+Math.max(0,Math.min(100,(ratio*5-i)*100))+'%"></em></i>').join('');
 return button('<span class="mana-bar-row">'+icon('mana-5')+'<b>'+Math.floor(amount)+'/'+m.capacity+'</b><span class="energy-dots mana-dots">'+dots+'</span><span class="mana-more">+</span></span>'+(caption?'<small class="mana-countdown">'+caption+'</small>':''),battle?'cast-dismiss':'mana-open','aria-label="Mana '+Math.floor(amount)+' sur '+m.capacity+'"','mana-panel '+(battle?'mana-combat':'mana-home'));
};
renderHUD=function(){
 refinementHUD();
 const worker=$('.builder-launch'),actions=$('.profile-actions');
 if(worker&&actions){actions.append(worker);worker.classList.add('top-builder');worker.setAttribute('aria-label','Constructeurs');}
 const mana=$('#hud .mana-panel'),stats=$('#hud .stats-left');if(mana&&stats)stats.append(mana);
 const lower=stats?(stats.offsetTop||96)+(stats.offsetHeight||180)+15:280;
 const mission=$('.mission-peek'),chat=$('.chat-launch');
 const missionVisible=mission&&!mission.classList.contains('guide-unavailable')&&window.getComputedStyle?.(mission)?.display!=='none';
 if(mission)mission.style.top=lower+'px';
 if(chat)chat.style.top=(lower+(missionVisible?(mission.offsetHeight||90)+15:0))+'px';
};
// Une seule vérification pour les conditions affichées, le « + » et le paiement.
function buildingUpgradeView(o){
 if(!o||o.hero||o.level>=20||o.type.startsWith('decor-'))return null;
 syncBuilderSlots();
 const q=constructionPrice(o.type,o.level),status=PreviewGame.buildingUpgradeStatus({type:o.type,level:o.level,mainLevel:state.level,levels:PreviewGame.buildingLevelContext(homeLayout.buildings)});
 const rows=[...status.rows];
 if(o.type==='core')for(const resource of ['gold','elixir']){
  const type=resource==='gold'?'reserve':'reservoir',store=homeLayout.buildings.find(b=>b.type===type),capacity=capFor(resource);
  rows.push({type,name:resource==='gold'?'Réserve d’or':'Réserve d’élixir',actual:store?.level||1,capacity,requiredCapacity:q[resource],met:capacity>=q[resource]});
 }
 let reason=null;try{upgradeCheck(o);}catch(e){reason=e.message;}
 if(o.underConstruction)reason='Ce bâtiment est déjà en chantier.';
 return {q,rows,allowed:!reason,reason,affordable:state.wallet.gold>=q.gold&&state.wallet.elixir>=q.elixir,free:Math.max(0,state.builders-PreviewGame.occupiedBuilders(state.jobs))};
}
function prerequisiteMarkup(o){
 const view=buildingUpgradeView(o);if(!view||o.underConstruction)return '';
 return '<section class="building-prerequisites" aria-label="Conditions d’évolution"><h3>Conditions · niveau '+(o.level+1)+'</h3><div class="prerequisite-grid">'+view.rows.map(r=>{
  const type=r.type==='research'?'academie':r.type;
  const detail=r.requiredCapacity!==undefined?'Niveau '+r.actual+' · capacité '+fmt(r.capacity)+' / '+fmt(r.requiredCapacity)+' requis':'Niveau '+r.actual+' <b>→ '+r.level+'</b>';
  return '<div class="prerequisite '+(r.met?'met':'missing')+'" data-required-type="'+type+'">'+art('building:'+type)+'<div><strong>'+esc(r.name)+'</strong><span>'+detail+'</span></div><b class="prerequisite-state" aria-label="'+(r.met?'Condition remplie':'Condition requise')+'">'+(r.met?'✓':'!')+'</b></div>';
 }).join('')+'</div>'+(view.rows.length?'':'<p class="no-building-prerequisite">Aucun autre bâtiment requis.</p>')+'<div class="builder-requirement '+(view.free?'met':'missing')+'">'+art('ui:builder')+'<span><b>'+view.free+' constructeur'+(view.free>1?'s':'')+' disponible'+(view.free>1?'s':'')+'</b> · 1 requis</span></div>'+(view.reason?'<p class="upgrade-blocker" role="status">'+esc(view.reason)+'</p>':'')+'</section>';
}
structureDetail=function(upgrade=false){
 const html=refinementDetail(upgrade),o=v06ViewedObject();
 const requirements=prerequisiteMarkup(o);if(!requirements)return html;
 const marker='<p class="settings-note">';return html.includes(marker)?html.replace(marker,requirements+marker):html+requirements;
};
renderFullMap=function(reset=false){
 refinementMap(reset);if(state.mapPage==='war')fullMapLayer().insertAdjacentHTML('beforeend',button('i','war-info','aria-label="Règles de la guerre des clans"','map-information'));
};
function warInformationPanel(){
 return '<div class="war-information"><h2>Le parcours de guerre</h2><ul><li><b>10 châteaux</b><span>Chaque joueur vainc son propre parcours adverse dans l’ordre, du n° 1 au n° 10.</span></li><li><b>3 défaites</b><span>Chaque défaite consomme une chance. À la troisième, tes attaques sont terminées pour la journée.</span></li><li><b>Une victoire = aucune chance perdue</b><span>Elle ouvre le château suivant. Un château conquis ne peut plus être attaqué par toi.</span></li><li><b>8 h → 22 h</b><span>La guerre quotidienne suit l’heure de Paris.</span></li><li><b>5 · 10 · 15 · 40 points</b><span>Tirage au sort · sentinelle · administrateur · chef.</span></li><li><b>Tournoi de la semaine</b><span>Les points contribuent au classement du clan et à ses récompenses.</span></li></ul></div>';
}
renderModal=function(){
 if(state.modal==='war-info'){
  $('#modal-title').textContent='Guerre des clans';$('#modal').classList.remove('shop-modal','tutorial-modal');$('#modal').classList.add('no-modal-tabs');$('#modal-body').innerHTML=warInformationPanel();$('#modal-tabs').innerHTML='';return;
 }
 refinementModal();
 for(const el of document.querySelectorAll('#modal-tabs [data-page="gift-mails"],#modal-tabs [data-page="reward-code"],#modal-body .detail-actions [data-page="reward-code"]'))el.remove();
 if(state.modal==='inbox'&&!['purchases','history'].includes(state.tab)){
  const gifts=giftPanel();if(state.giftMails.length)$('#modal-body').insertAdjacentHTML('beforeend','<section class="inbox-gifts"><h2>Récompenses reçues</h2>'+gifts+'</section>');
 }
 if(state.modal==='audio')$('#modal-body').insertAdjacentHTML('beforeend','<div class="sound-results-test">'+button('⚒ Travaux','audio-test','data-kind="build.start"','secondary')+button('★ Victoire','audio-test','data-kind="battle.win"','secondary')+button('Défaite','audio-test','data-kind="battle.lose"','secondary')+'</div>');
 $('#modal').classList.toggle('no-modal-tabs',!$('#modal-tabs').textContent.trim());
};
action=function(a,d,node){
 if(a==='war-info'){open('war-info');return;}
 if(a==='audio-test'&&['build.start','battle.win','battle.lose'].includes(d.kind)){audioCue(d.kind,{force:true});return;}
 if(a==='prerequisite-see'){renderModal();return;}
 if(a==='settings-code-redeem'){
  const value=$('#settings-reward-code')?.value||'';
  let field=$('#reward-code');if(!field){field=document.createElement('input');field.id='reward-code';field.type='hidden';$('#modal-body').append(field);}field.value=value;
  refinementAction('code-redeem',d,node);if(state.modal==='gift-mails')open('inbox');return;
 }
 if(a==='gift-claim'||a==='gift-delete'){refinementAction(a,d,node);if(state.modal==='gift-mails')open('inbox');return;}
 return refinementAction(a,d,node);
};

// Édition 0.19 : corrections des interactions de construction ; interfaces métier dans les bâtiments et règles partagées.
state.unlockedTroops??=PLAYER_PREVIEW.scenario==='established-player'?MODELS.TROOPS.filter(t=>t.unlock<=(activeAcademy()?.level||1)).map(t=>t.id):['fantassin','bouclier'];
state.chatBlocks??={};state.chatBlockCounts??={};state.botTemplates??=[];state.releaseClaims??=[];state.weeklyActivity??={};state.visitsCache??={};
const r18Modal=renderModal,r18HUD=renderHUD,r18Castle=renderCastle,r18Select=renderSelection,r18Action=action,r18Tick=battleTick,r18Jobs=completeJobs,r18Settings=settings,r18History=historyEntry,r18Appearance=appearancePair,r18Begin=beginBattle,r18Army=army;
const r18Fields=['name','flag','unlockedTroops','chatBlocks','chatBlockCounts','botTemplates','releaseClaims','weeklyActivity','lastInteractionAt','serverLaunchAt','pvpSearchIndex','visitsCache'];
const r18SaveFields=guideSaveFields;guideSaveFields=function(){return {...r18SaveFields(),...Object.fromEntries(r18Fields.map(k=>[k,state[k]]))};};
const r18Save=saveCurrentProgress;saveCurrentProgress=function(){r18Save();};

function r18Clock(){const n=PreviewGame.settleEnergy({energy:state.energy,energyAt:state.energyAt,level:state.level});state.energy=n.energy;state.energyAt=n.energyAt;return n;}
function r18ResearchLevel(){return activeAcademy()?.underConstruction?0:activeAcademy()?.level||0;}
researchState=function(){return {level:state.level,wallet:state.wallet,monsterLevels:state.monsterLevels,research:state.research,researchBuildingLevel:r18ResearchLevel(),forgeLevel:homeLayout.buildings.find(b=>b.type==='forge'&&!b.underConstruction)?.level||0,unlockedTroops:state.unlockedTroops,researchFunding:state.researchFunding,researchPayments:state.researchPayments};};
const r18Recruitment=recruitmentState;recruitmentState=function(){return {...r18Recruitment(),unlockedTroops:state.unlockedTroops,researchBuildingLevel:r18ResearchLevel()};};
function r18Mail(id,title,reward,text='Une récompense t’attend.'){if(state.releaseClaims.includes(id))return;state.releaseClaims.push(id);state.giftMails.push({id:'release018:'+id,playerId:'preview-player',kind:'gift',title,text,claimed:false,remaining:PreviewGame.v07RewardBundle(reward)});notifyGame('mail:'+id,title,'item:gift');}
completeJobs=function(){const before=state.level;r18Jobs();if(state.level>before)for(const n of [3,4])if(before<n&&state.level>=n)r18Mail('throne-'+n,'Cœur niveau '+n,{diamonds:150,items:{'speed-3600':5}});};
appearancePair=function(o){return o.hero?'<div class="single-hero-portrait">'+heroArt(o.hero,'detail-art')+'</div>':r18Appearance(o);};
function r18Health(id){const h=state.recovery.heroes[id],ratio=h?.ratio??1,hp=PreviewGame.v06HeroStats(id,state.heroLevels[id]||1).hp;return '<div class="hero-life" data-life="'+id+'"><span><i style="width:'+(ratio*100)+'%"></i></span><b>'+fmt(Math.round(ratio*hp))+' / '+fmt(hp)+'</b>'+(ratio<=.15?'<em>Out</em>':'')+'</div>';}
function r18Recover(){for(const [id,h]of Object.entries(state.recovery.heroes)){h.level=state.heroLevels[id]||1;h.maxHP=PreviewGame.v06HeroStats(id,h.level).hp;}recoverNow();}
function r18Money(q){return '<span class="compact-cost">'+quantityIcon('gold',q.gold||0)+quantityIcon('elixir',q.elixir||0)+'</span>';}
function r18Upgrade(o){const a=v06ItemValues(o,o.level),b=v06ItemValues(o,Math.min(20,o.level+1));return '<div class="compact-upgrade"><div class="compact-upgrade-title">'+art(meta(o).asset)+'<div><h2>'+esc(meta(o).name)+'</h2><b>Niveau '+o.level+' → '+(o.level+1)+'</b></div></div>'+prerequisiteMarkup(o)+comparisonTable({...a,level:o.level},{...b,level:o.level+1})+(o.type==='mana'?'<p class="mana-increase">Mana '+PreviewGame.manaCapacity(o.level)+' → <b>'+PreviewGame.manaCapacity(o.level+1)+'</b> <strong>+'+(PreviewGame.manaCapacity(o.level+1)-PreviewGame.manaCapacity(o.level))+'</strong></p>':'')+(o.type==='core'?'<p>XP de combat : +'+Math.round(.1*o.level*100)+' % · énergie : '+exactTime(PreviewGame.energyRechargeMs(o.level+1)/1000)+'</p>':'')+'</div>';}

function r18Function(o){if(!o)return '';if(o.underConstruction)return '<p>Ce bâtiment est en chantier.</p>';const t=o.type;if(t==='garnison')return recruitmentPanel();if(['academie','atelier-monstres'].includes(t))return researchPanel();if(t==='caserne-heros')return housingPanel(o);if(t==='garde-monstres')return guardPanel(o);if(t==='mana')return r18Mana(o);if(t==='necropole')return '<div class="detail-layout">'+art('defense:necropole','detail-art')+'<div><h2>Nécropole</h2><p>Défend son étage. Les héros récupèrent naturellement 2 PV par seconde après le combat.</p></div></div>';return structureDetail(false);}
function r18Mana(o){r18Recover();const m=state.recovery.mana,cap=m.capacity,next=PreviewGame.manaCapacity(Math.min(20,o.level+1));return '<div class="mana-building-panel">'+art('building:mana','mana-vessel')+'<div><h2>Réservoir de mana</h2><div class="large-mana-gauge"><i style="width:'+(cap?m.amount/cap*100:0)+'%"></i><b>'+Math.floor(m.amount)+' / '+cap+'</b></div><p>'+ (m.amount>=cap?'Mana complet':'+1 dans '+exactTime((1-(m.amount%1))/PreviewGame.MANA_RULES.perSecond))+'</p><div class="mana-next">Niveau '+o.level+' : '+cap+' <span>→</span> Niveau '+Math.min(20,o.level+1)+' : '+next+' <strong>+'+(next-cap)+' mana</strong></div><div class="recovery-potions">'+PreviewGame.RECOVERY_ITEMS.filter(p=>p.mana).map(p=>button(art(p.asset)+'+'+p.mana+' · ×'+(state.inventory[p.id]||0),'recovery-use','data-id="'+p.id+'" '+(!state.inventory[p.id]||m.amount>=cap?'disabled':''),'secondary')).join('')+'</div></div></div>';}
researchPanel=function(){const academy=activeAcademy(),l=r18ResearchLevel();return '<div class="academy-heading">'+art('building:academie')+'<div><h2>Académie · niveau '+l+'</h2><span>'+ (state.research?'Recherche en cours · <b data-ends-at="'+state.research.endsAt+'">'+exactTime((state.research.endsAt-Date.now())/1000)+'</b>':'Choisis une famille')+'</span></div></div><div class="card-grid academy-grid">'+MODELS.TROOPS.map(t=>{const owned=state.unlockedTroops.includes(t.id),locked=l<t.unlock,unlock=PreviewGame.troopUnlockQuote(t.id,l);return '<article class="paper-card unit-card '+(locked?'locked-troop':'')+'">'+monsterArt(t.id,state.monsterLevels[t.id])+'<strong>'+t.name+'</strong><span>'+ (locked?'Académie niveau '+t.unlock:owned?'Niveau '+state.monsterLevels[t.id]:'À débloquer')+'</span>'+ (owned?button('Level up et apparences','monster','data-id="'+t.id+'"','secondary'):r18Money(unlock)+'<small>'+v06Duration(unlock.durationSeconds)+'</small>'+button('Débloquer','r18-unlock','data-id="'+t.id+'" '+(locked||state.research?'disabled':'')))+'</article>';}).join('')+'</div>';};
army=function(){const old=r18Army();return old.replace(/<div class="center-actions">[\s\S]*?<\/div>\s*$/,'');};
function buildingActionCard(image,label,a,id,cls='',sub=''){
 return button('<span class="action-card-art">'+image+'</span><span class="action-card-label">'+label+'</span>'+(sub?'<span class="action-card-sub">'+sub+'</span>':''),a,'data-id="'+id+'"','selection-card '+cls);
}
renderSelection=function(){
 r18Select();const o=object(state.selected);if(!o||state.edit||state.battle?.engine?.status==='running'||state.visiting||o.hero)return;
 const m=meta(o),q=o.level<20?constructionPrice(o.type,o.level):null,job=state.jobs.find(j=>j.target===o.id);
 const actionLabel=({garnison:'Recruter',academie:'Recherche','atelier-monstres':'Recherche',mana:'Mana','caserne-heros':'Garnison','garde-monstres':'Garnison'})[o.type];
 let actions=buildingActionCard(icon('scroll'),'Infos','info',o.id,'info-card');
 if(job){
  actions+=buildingActionCard(icon('speed-3600'),'Accélérer','job-speed',job.id,'speed-card','Choisir une durée')+buildingActionCard(icon('diamonds'),'Terminer','job-finish',job.id,'finish-card',quantityIcon('diamonds',PreviewGame.constructionFinishPrice(job.endsAt)));
 }else if(!o.underConstruction){
  if(q)actions+=buildingActionCard(icon('attack'),'Améliorer','upgrade',o.id,'upgrade-card',r18Money(q));
  if(actionLabel)actions+=buildingActionCard(o.type==='mana'?icon('mana-5'):o.type==='garnison'?monsterArt('fantassin',state.monsterLevels.fantassin):art(m.asset),actionLabel,'enter-building',o.id,'enter-card',o.type==='mana'?Math.floor(state.recovery.mana.amount)+' / '+state.recovery.mana.capacity:'');
  if(['mine','extracteur'].includes(o.type))actions+=buildingActionCard(icon(o.type==='mine'?'gold':'elixir'),'Récolter','collect',o.id,'collect-card',fmt(collectAmount(o)));
 }
 $('#selection').innerHTML='<div class="selection-title">'+esc(m.name)+' <span>Niveau '+o.level+'</span>'+(job?'<small class="selection-job-time" data-ends-at="'+job.endsAt+'">'+exactTime((job.endsAt-Date.now())/1000)+'</small>':'')+'</div><div class="selection-actions r18-actions">'+actions+'</div>';
};

drawRange=function(compareLevel=null){$('.range-overlay')?.remove();const o=object(state.selected);if(!o||state.edit||!MODELS.DEFENSES.some(d=>d.id===o.type)&&o.type!=='core')return;const w=meta(o).width,cx=(o.x+w/2)*CW(),cy=(layout.floors-1-o.floor+(!state.battle&&state.jobs.some(j=>j.floorJob)?1:0))*fh()+fh()/2;const contour=(n,future=false)=>{const s=o.type==='core'?{range:1,color:'#ffe39b'}:PreviewGame.v06DefenseStats(o.type,n),r=s.range*CW(),color=future?'#f3c76d':s.color;if(o.type==='baliste'){const dir=PreviewGame.v06BalistaDirection(o,layout.doors[o.floor].x)==='left'?-1:1,start=cx+dir*w*CW()/2,end=start+dir*r;return '<path d="M '+start+' '+cy+' L '+end+' '+cy+'" stroke="'+color+'" stroke-width="22" stroke-opacity=".2"/><path d="M '+start+' '+cy+' L '+end+' '+cy+'" stroke="'+color+'" stroke-width="2" stroke-dasharray="6 4"/>';}return '<rect x="'+(cx-w*CW()/2-r)+'" y="'+(cy-fh()/2-r)+'" width="'+(w*CW()+2*r)+'" height="'+(fh()+2*r)+'" rx="'+r+'" fill="'+color+'" fill-opacity="'+(future?0:.12)+'" stroke="'+color+'" stroke-width="2" '+(future?'stroke-dasharray="7 5"':'')+'/>';};const el=document.createElementNS('http://www.w3.org/2000/svg','svg');el.classList.add('range-overlay');el.setAttribute('viewBox','0 0 '+layout.slots*CW()+' '+layout.floors*fh());el.innerHTML=contour(o.level)+(compareLevel?contour(compareLevel,true):'');$('.castle-floors').append(el);};
renderCastle=function(){r18Castle();if(!state.battle&&!state.visiting){for(const e of document.querySelectorAll('.roaming-unit'))e.remove();const units=state.roster.filter(r=>r.count>0).flatMap(r=>Array.from({length:Math.min(r.count,homeLayout.floors*5)},()=>r));let index=0;for(let f=0;f<homeLayout.floors&&index<units.length;f++){const floor=$('.castle-floor[data-floor="'+f+'"]');for(let i=0;i<5&&index<units.length;i++,index++){const u=units[index];floor?.insertAdjacentHTML('beforeend','<span class="roaming-unit" style="left:'+((i+.6)*layout.slots/5*CW())+'px;animation-delay:'+(-index*.31)+'s" title="'+esc(MODELS.TROOPS.find(t=>t.id===u.troop)?.name)+' · Niv. '+(u.level||state.monsterLevels[u.troop])+'">'+profileMarkup('monster',u.troop,'walk',i%2?-1:1,index)+'</span>');}}for(const g of homeLayout.garrisons){const e=$('.building[data-id="'+g.id+'"]');e?.insertAdjacentHTML('beforeend',r18Health(g.hero));}for(const o of homeLayout.traps){const e=$('.building[data-id="'+o.id+'"]');if(e){e.dataset.trapOverflow=String(['trap-0','trap-4','trap-8','trap-16','trap-34'].includes(o.type));}}}if(state.visiting){for(const o of layout.buildings.filter(o=>['mine','extracteur'].includes(o.type)))$('.building[data-id="'+o.id+'"]')?.insertAdjacentHTML('beforeend',button(icon('gear'),'r18-visit-oil','data-id="'+o.id+'"','oil-bubble'));}};
renderHUD=function(){r18Clock();r18HUD();if(!state.battle&&!state.visiting&&!state.edit)addCastleSignals();$('#research-launch')?.remove();if(state.visiting){$('#hud').classList.add('visiting-hud');document.querySelectorAll('.visit-heading').forEach(e=>e.remove());$('#hud').insertAdjacentHTML('beforeend','<div class="visit-heading"><h2>'+esc(state.visiting.name)+'</h2>'+button('Sortir du château','r18-visit-exit')+'</div>');}else $('#hud').classList.remove('visiting-hud');};
function r18Float(asset,text){rewardFloat(asset,text);const e=document.querySelector('.reward-float:last-child');if(e){e.classList.add('reward-center');setTimeout(()=>e.remove(),2300);}}
function r18Particles(resource,amount,from){
 const target=$('#hud .resource-row.'+resource+' .resource-info'),to=target?.getBoundingClientRect();if(!from||!to)return;
 const x=from.x+from.width/2,y=from.y+from.height*.45,tx=to.x+to.width/2,ty=to.y+to.height/2;
 for(let i=0;i<9;i++){const e=document.createElement('span');e.className='harvest-particle';e.dataset.resource=resource;e.innerHTML=icon(resource);e.style.left=x+'px';e.style.top=y+'px';e.style.setProperty('--tx',(tx-x)+'px');e.style.setProperty('--ty',(ty-y)+'px');e.style.animationDelay=i*.045+'s';document.body.append(e);setTimeout(()=>e.remove(),1500);}
 rewardFloat('item:'+resource,'+'+fmt(amount),{getBoundingClientRect:()=>from});
}

function r18Contributor(){const rows=PreviewGame.clanContributorRewards(state.clanData,state.clanWeek);return '<div class="panel-mini-heading"><b>Classement de la semaine</b>'+button('i','clan-info','data-kind="contributors"','info-orb')+'</div><table class="contributors-table"><thead><tr><th>Rang · Joueur</th><th>Dons</th><th>Récompenses</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+r.rank+' · '+esc(state.members.find(m=>m.id===r.playerId)?.name||r.playerId)+'</td><td><b class="donation-count">'+r.count+'</b></td><td><div class="contributor-prizes">'+quantityIcon('diamonds',r.reward.diamonds)+quantityIcon('gold',r.reward.gold)+quantityIcon('elixir',r.reward.elixir)+Object.entries(r.reward.vials).map(([k,n])=>quantityIcon('xp-'+k,n)).join('')+Object.entries(r.reward.items).map(([k,n])=>quantityIcon(k,n)).join('')+'</div></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<p>Aucun don cette semaine.</p>':'');}
contributorPanel=r18Contributor;
settings=function(){return r18Settings()+'<section class="paper-card temporary-demo-tools"><h3>Test de la démo</h3>'+button('Remplir','demo-fill','aria-label="Remplir l’or, l’élixir et le mana"','secondary')+'</section>'+'<section class="paper-card"><h3>Joueurs ignorés</h3>'+Object.entries(state.chatBlocks).filter(([id])=>PreviewGame.chatPlayerBlocked(state.chatBlocks,id)).map(([id,b])=>'<div class="blocked-player"><b>'+esc(id)+'</b><span>'+(b.until?exactTime((b.until-Date.now())/1000):'Bloqué')+'</span>'+button('Débloquer','r18-unblock','data-id="'+esc(id)+'"','secondary')+'</div>').join('')+'</section><details class="demo-tools"><summary>Adversaires BOT</summary><label>Importer une défense<input id="r18-import-bot" type="file" accept="application/json,.json"></label><p>'+state.botTemplates.length+' défenses importées</p></details>';};
function r18Shield(){const q=state.shieldPrompt,o=PreviewGame.shieldReplacement(state.shieldUntil,q.days*86400000);return '<div class="confirmation">'+icon(q.id)+'<h2>Activer le bouclier</h2><p>Il te reste <b>'+exactTime(o.remaining/1000)+'</b> de protection.</p><p>Le nouveau bouclier dure <b>'+q.days+' jour'+(q.days>1?'s':'')+'</b>. Il remplace la protection actuelle. Les durées ne s’additionnent pas.</p>'+button('Confirmer','r18-shield-confirm')+button('Annuler','back','','secondary')+'</div>';}
function r18BlockPanel(){return '<div class="confirmation"><h2>Ignorer '+esc(state.blockTarget)+'</h2><p>Tu pourras le débloquer dans les paramètres.</p>'+button('Ignorer une heure','r18-block-confirm','data-mode="hour"')+button('Bloquer jusqu’au déblocage','r18-block-confirm','data-mode="permanent"','secondary')+'</div>';}
function r18SearchPanel(){const t=state.pvpTarget,q=PreviewGame.pvpSearchPrice(state.level);if(!t)return '';return '<div class="opponent-search"><div>'+art('war:castle:chief:enemy','opponent-portrait')+'<h2>'+esc(t.name)+'</h2><b>Cote '+fmt(t.rating)+' · Cœur '+t.level+'</b></div><div><div class="search-countdown">'+Math.max(0,Math.ceil((state.searchEndsAt-Date.now())/1000))+'</div>'+button('Combattre','r18-search-fight')+button('Suivant →','r18-search-next','','secondary')+r18Money(q)+button('Retour','close','','secondary')+'</div></div>';}
function r18ChooseTarget(){const pool=state.botTemplates.length?state.botTemplates:MODELS.TROOPS.slice(0,4).map((t,i)=>({id:'builtin-'+i,name:['Bastion de Brom','Garde du levant','Roche d’argent','Tour de cuivre'][i],rating:700+i*400,level:Math.min(20,Math.max(3,state.level-1+i))}));state.pvpSearchIndex=(state.pvpSearchIndex||0)+1;const sorted=[...pool].sort((a,b)=>Math.abs(a.rating-state.rating)-Math.abs(b.rating-state.rating));state.pvpTarget=sorted[(state.pvpSearchIndex-1)%sorted.length];state.searchEndsAt=Date.now()+5000;}
renderModal=function(){
 if(state.modal==='building-function'){const o=homeObject(state.buildingFunctionId);$('#modal-title').textContent=o?meta(o).name:'Bâtiment';$('#modal-body').innerHTML=r18Function(o);$('#modal-tabs').innerHTML='';$('#modal').classList.remove('shop-modal');enhanceSelects();return;}
 if(state.modal==='shield-confirm'||state.modal==='chat-block'||state.modal==='pvp-search'){$('#modal-title').textContent=state.modal==='shield-confirm'?'Protection':state.modal==='chat-block'?'Discussion':'Recherche d’adversaire';$('#modal-body').innerHTML=state.modal==='shield-confirm'?r18Shield():state.modal==='chat-block'?r18BlockPanel():r18SearchPanel();$('#modal-tabs').innerHTML='';return;}
 if(state.modal==='construction-confirm'){
  $('#modal-title').textContent='Confirmer l’accélération';$('#modal').classList.remove('shop-modal');$('#modal').classList.add('no-modal-tabs');
  $('#modal-body').innerHTML=constructionConfirmation();$('#modal-tabs').innerHTML='';return;
 }
 if(state.modal==='upgrade'&&(!state.journey||state.journey.done)){
  const o=v06ViewedObject();if(!o||o.level>=20){$('#modal-title').textContent='Niveau maximum';$('#modal-body').innerHTML='<p>Ce bâtiment a atteint le niveau maximum.</p>';$('#modal-tabs').innerHTML='';return;}
  const view=buildingUpgradeView(o),q=view.q;$('#modal').classList.remove('shop-modal','no-modal-tabs');$('#modal-title').textContent='Améliorer';$('#modal-body').innerHTML=r18Upgrade(o);
  $('#modal-tabs').innerHTML='<div class="upgrade-footer">'+r18Money(q)+'<b>'+v06Duration(q.durationSeconds)+'</b>'+button('Confirmer','upgrade-confirm','data-id="'+o.id+'" '+(!view.allowed?'disabled':''))+button('Annuler','back','','secondary')+'</div>';return;
 }

 r18Modal();
 if(state.modal==='army'){for(const e of document.querySelectorAll('#modal-tabs [data-tab="recruit"],#modal-body .center-actions [data-action="tab"][data-tab="recruit"],#modal-body .center-actions [data-page="shop"],#modal-body .hero-life'))e.remove();}
 if(state.modal==='info'&&(!state.journey||state.journey.done)){const o=v06ViewedObject();for(const e of document.querySelectorAll('#modal-body [data-action="move"],#modal-body [data-action="housing-assign"],#modal-body .housing-panel'))e.remove();if(o&&['garnison','academie','atelier-monstres','mana','caserne-heros','garde-monstres'].includes(o.type))$('#modal-body').insertAdjacentHTML('beforeend',button('Ouvrir','enter-building','data-id="'+o.id+'"'));}
 if(state.modal==='clan-role')$('#modal-body').insertAdjacentHTML('afterbegin','<div class="role-counters">Sentinelles '+state.clanChosen.length+' / '+(3+state.clanTech.selection)+' · Novice '+state.clanExcluded.length+' / '+Math.min(3,1+state.clanTech.exclusion)+'</div>');
 if(state.modal==='war-info')$('#modal-body').innerHTML=$('#modal-body').innerHTML.replace('8 h → 22 h','8 h → 22 h');
 if(state.modal==='hero'){const e=$('#modal-body .detail-copy');if(e&&!e.querySelector('.hero-life'))e.insertAdjacentHTML('beforeend',r18Health(state.heroId));}
};
function r18OpenVisit(id,name){if(state.battle?.engine?.status==='running')throw Error('Termine le combat avant une visite.');if(state.battle)stopBattle(true);const owner=state.members.find(m=>m.id===id),known=state.botTemplates.find(b=>b.id===id);const l=PreviewGame.publicCastleSnapshot(state.visitsCache[id]||known?.layout||known?.snapshot||homeLayout);state.visiting={id,name:name||owner?.name||id,layout:l};state.visitHome={layout,cosmetics:structuredClone(state.cosmetics)};close(true);layout=l;state.selected=null;state.edit=null;renderHUD();renderCastle();}
function r18ExitVisit(){if(!state.visiting)return;layout=state.visitHome?.layout||homeLayout;state.visiting=null;state.visitHome=null;state.battle=null;$('#selection').style.visibility='';renderHUD();renderCastle();saveCurrentProgress();}
function r18SyncResearch(){if(!state.research||state.research.endsAt>Date.now())return;const r=PreviewGame.v06SettleResearch(researchState());state.research=r.research;state.monsterLevels=r.monsterLevels;state.unlockedTroops=r.unlockedTroops||state.unlockedTroops;notifyGame('research-done:'+Date.now(),'Recherche terminée','building:academie');saveCurrentProgress();if(state.modal==='building-function')renderModal();}
historyEntry=function(b,frames,s,l,mode,name,at){const h=r18History(b,frames,s,l,mode,name,at);h.result.xp=PreviewGame.combatHeroXP(mode,state.level);h.heroXPBefore=structuredClone(state.heroXP);h.mainLevel=state.level;if(mode==='pvp'&&state.pvpTarget)h.name=state.pvpTarget.name;return h;};
battleTick=function(){const b=state.battle,ending=b&&!b.replay&&!b.reward018Done;if(b?.mode==='war'&&!state.demoWarOpen&&!PreviewGame.v06WarIsOpen()&&b.engine.status==='running'){PreviewGame.finishBattle(b.engine,'war-closed');b.paused=false;}r18Tick();if(ending&&b?.engine.status!=='running'&&b.history&&!b.reward018Done){b.reward018Done=true;for(const id of state.formation)if(!b.history.army.heroes.includes(id))state.heroXP[id]=b.history.heroXPBefore?.[id]||0;if(b.mode==='campaign'&&b.engine.status==='won'){const stage=state.campaignStage||((state.region||0)*8+(state.stage||1));r18Mail('campaign-'+stage,'Bastion '+stage+' conquis',PreviewGame.campaignReward018(stage,state.level));const earned=PreviewGame.earnedZoneRewards(state.campaignStars);for(const id of earned)if(!state.cosmetics.owned.includes(id))state.cosmetics.owned.push(id);}if(b.mode==='pvp'){const d=PreviewGame.pvpRatingDelta(state.rating,state.pvpTarget?.rating||1000,b.engine.status==='won');state.rating=Math.max(0,state.rating+d);b.history.result.ratingDelta=d;}saveCurrentProgress();}};
const r18Layout=battleLayout;battleLayout=function(weak=false){if(state.nextBattleMode==='pvp'&&(state.pvpTarget?.layout||state.pvpTarget?.snapshot))return structuredClone(state.pvpTarget.layout||state.pvpTarget.snapshot);return r18Layout(weak);};
beginBattle=function(mode,index){r18Clock();if(mode==='pvp'&&state.level<3){toast('Adversaires BOT d’entraînement avant le Cœur niveau 3.');mode='practice';}state.nextBattleMode=mode;try{r18Begin(mode,index);}finally{state.nextBattleMode=null;}};
action=function(a,d={},node){try{
 if(state.visiting&&!['r18-visit-exit','r18-visit-oil'].includes(a))return;
 if(a==='demo-fill'){
  if(state.battle||state.visiting)throw Error('Reviens à ton château pour remplir les réserves.');
  for(const k of ['gold','elixir'])state.wallet[k]=capFor(k);r18Recover();state.recovery.mana.amount=state.recovery.mana.capacity;state.recovery.mana.lastAt=Date.now();
  saveCurrentProgress();renderHUD();renderSelection();addCastleSignals();toast('Or, élixir et mana remplis pour le test.');return;
 }
 if(['job-speed','job-finish','speed-item-apply'].includes(a)&&!guideActive()){requestConstructionAcceleration(a,d);return;}
 if(a==='construction-confirm'){confirmConstructionAcceleration();return;}
 if(a==='battle'&&d.mode==='pvp'){r18ChooseTarget();open('pvp-search');return;}
 if(a==='enter-building'){state.buildingFunctionId=d.id;state.infoId=d.id;open('building-function');return;}
 if(a==='r18-unlock'){const s=PreviewGame.startTroopUnlock(researchState(),d.id);state.wallet=s.wallet;state.research=s.research;state.unlockedTroops=s.unlockedTroops;renderHUD();renderModal();saveCurrentProgress();return;}
 if(a==='use-item'&&d.id.startsWith('shield-')){const days={'shield-1d':1,'shield-7d':7,'shield-30d':30}[d.id];if(!(state.inventory[d.id]>0))throw Error('Bouclier indisponible.');state.shieldPrompt={id:d.id,days};open('shield-confirm');return;}
 if(a==='r18-shield-confirm'){const s=PreviewGame.activateShield({inventory:state.inventory,shieldUntil:state.shieldUntil},state.shieldPrompt.id,{confirmed:true});state.inventory=s.inventory;state.shieldUntil=s.shieldUntil;close();renderHUD();saveCurrentProgress();return;}
 if(a==='block-player'){state.blockTarget=d.name;open('chat-block');return;}
 if(a==='r18-block-confirm'){const p=PreviewGame.blockChatPlayer({chatBlocks:state.chatBlocks},state.blockTarget,{permanent:d.mode==='permanent'});state.chatBlocks=p.chatBlocks;state.blocked.add(state.blockTarget);close();renderChat();saveCurrentProgress();return;}
 if(a==='r18-unblock'){delete state.chatBlocks[d.id];state.blocked.delete(d.id);renderChat();renderModal();saveCurrentProgress();return;}
 if(a==='r18-visit-exit'){r18ExitVisit();return;}
 if(a==='visit-castle'){r18OpenVisit(d.id||'member-1',d.name);return;}
 if(a==='r18-visit-oil'){const owner={...state.visiting,bot:false},r=PreviewGame.helpMine({id:state.id,wallet:state.wallet,mineHelps:state.mineHelps,visitReceipts:state.visitReceipts},owner,d.id,{commandId:currentId('oil')});state.wallet=r.visitor.wallet;state.mineHelps=r.visitor.mineHelps;state.visitReceipts=r.visitor.visitReceipts;state.visiting=r.owner;layout=r.owner.layout;state.visitsCache[state.visiting.id]=structuredClone(layout);r18Float('item:diamonds','+1');renderCastle();saveCurrentProgress();return;}
 if(a==='r18-search-start'){r18ChooseTarget();open('pvp-search');return;}
 if(a==='r18-search-next'){const q=PreviewGame.pvpSearchPrice(state.level);if(state.wallet.gold<q.gold||state.wallet.elixir<q.elixir)throw Error('Ressources insuffisantes.');state.wallet.gold-=q.gold;state.wallet.elixir-=q.elixir;r18ChooseTarget();renderHUD();renderModal();return;}
 if(a==='r18-search-fight'){state.searchEndsAt=null;beginBattle('pvp',0);return;}
 const before=structuredClone(state.wallet),oldModal=state.modal,oldLevel=state.level,oldDone=state.journey?.done;const oil=a==='collect'?homeObject(d.id):null,harvestOrigin=oil?$('.building[data-id="'+oil.id+'"]')?.getBoundingClientRect():null;
 r18Action(a,d,node);
 if(a==='clan-donation'&&state.wallet.diamonds>before.diamonds){document.querySelectorAll('.reward-float').forEach(e=>e.remove());r18Float('item:diamonds','+1');}
 if(a==='collect'){const gold=state.wallet.gold-before.gold,elixir=state.wallet.elixir-before.elixir;if(gold||elixir){if(oil){oil.oiled=false;oil.helpUntil=0;}document.querySelectorAll('.reward-float').forEach(e=>e.remove());document.querySelectorAll('.harvest-float').forEach(e=>e.remove());r18Particles(gold?'gold':'elixir',gold||elixir,harvestOrigin);}}
 if(a==='return-claim'&&state.returnCampaign?.days.length===7){const h=state.returnCampaign.hero;if(h&&!state.ownedHeroes.has(h)){state.ownedHeroes.add(h);state.heroLevels[h]=1;state.heroXP[h]=0;r18Float('hero:'+h,heroes.find(x=>x.id===h).name+' obtenu');}}
 if(!oldDone&&state.journey?.done)r18Mail('starter-complete','Bienvenue dans ton royaume',{gold:6000,elixir:6000},'Ton aventure commence.');
 if(state.modal==='pvp')$('#modal-body').insertAdjacentHTML('afterbegin',button('Rechercher un adversaire','r18-search-start'));
 if(['guard-assign','guard-clear','housing-assign','housing-clear','recruit-add','recruit-remove','recruit-confirm','research-fund'].includes(a)&&oldModal==='building-function')renderModal();
 saveCurrentProgress();
 }catch(e){toast(e.message);}};
const r18Refresh=refreshCounters;refreshCounters=function(){r18Refresh();const e=$('#energy-countdown');if(e)e.textContent=state.energy>=5?'Énergie complète':'+1 dans '+exactTime(Math.max(0,(state.energyAt+PreviewGame.energyRechargeMs(state.level)-Date.now())/1000));};
document.addEventListener('change',async e=>{if(e.target.id!=='r18-import-bot'||!e.target.files?.[0])return;try{const raw=JSON.parse(await e.target.files[0].text()),bot=PreviewGame.botOpponent({id:raw.id||'bot-import-'+Date.now(),name:raw.name||raw.botName,rating:Number(raw.rating),level:raw.mainLevel||raw.level||raw.castleLevel||raw.layout?.castleLevel,layout:raw.layout||raw.snapshot});PreviewGame.v06ValidatePreviewLayout(bot.layout);state.botTemplates.push(bot);saveCurrentProgress();renderModal();toast('Défense BOT importée.');}catch(error){toast(error.message);}});
function r18Interaction(){state.lastInteractionAt=Date.now();const me=state.members.find(m=>m.id===state.id);if(me)me.lastSeenAt=state.lastInteractionAt;if(state.sessionInactive){constructionConfirmationsSkipped=false;state.constructionPrompt=null;state.sessionInactive=false;notifyGame('session-return:'+Date.now(),'Connexion reprise','item:info');}}
document.addEventListener('pointerdown',r18Interaction,{passive:true});document.addEventListener('keydown',r18Interaction);state.lastInteractionAt=Date.now();
setInterval(()=>{r18Clock();r18Recover();r18SyncResearch();if(Date.now()-state.lastInteractionAt>=300000)state.sessionInactive=true;if(state.modal==='pvp-search'){if(false)action('r18-search-fight');else{const c=$('.search-countdown');if(c)c.textContent=Math.max(0,Math.ceil((state.searchEndsAt-Date.now())/1000));}}for(const [id,b]of Object.entries(state.chatBlocks))if(b.until&&b.until<=Date.now()){delete state.chatBlocks[id];state.blocked.delete(id);}for(const e of document.querySelectorAll('[data-life]')){const id=e.dataset.life;if(id&&state.recovery.heroes[id])e.outerHTML=r18Health(id);}refreshCounters();},1000);
renderHUD();renderCastle();
// Parcours quotidiens : même tâche, quatre paliers successifs.
