 const q=accelerationQuote(p.action,{id:p.id});if(q.item!==p.item||q.diamonds>p.diamonds){state.constructionPrompt={...p,item:q.item,diamonds:q.diamonds};renderModal();throw Error('Le devis a changé. Vérifie le nouveau montant.');}
