action=function(a,d={},node){
 try{
  if(['r18-search-start','r18-search-next','search-next021','search-prev021','search-exit021','search-fight021'].includes(a)){
   if(a==='r18-search-start'){startSearch021();return;}
   const s=state.opponentSearch021;if(!s)return;if(a==='search-exit021'){endSearch021();return;}
   if(a==='search-prev021'){if(!s.loading&&s.index>0){s.index--;showOpponent021();}return;}
   if(a==='search-next021'||a==='r18-search-next'){nextOpponent021().catch(e=>{s.loading=false;renderSearch021();toast(e.message);});return;}
   if(a==='search-fight021'){if(s.loading||!state.energy)return;const target=s.targets[s.index];endSearch021();state.pvpTarget=target;state.searchBattlePending021=true;try{beginBattle('pvp',0);}finally{state.searchBattlePending021=false;}saveCurrentProgress();return;}
  }
  if(a==='battle'&&d.mode==='pvp'){startSearch021();return;}
  if(state.opponentSearch021)return;
  reconcileClan021();ensureTestModes021();enforceTestModes021();
  if(a==='demo-mode021'){if(!demoToolsAllowed021())return;const id=d.mode;if(!['resources','diamonds'].includes(id))return;state.demoTestModes021[id]=!state.demoTestModes021[id];enforceTestModes021();renderHUD();renderModal();saveCurrentProgress();return;}
  if(a==='clan-join021'){if(state.level<5)throw Error('Cœur niveau 5 requis.');const index=Number(d.index),names=['Les Sentinelles','Les Lames d’Astral','Les Dragons Bleus','La Guilde du Crépuscule'];if(!names[index])return;establishClan021(names[index],{role:'member',fresh:true,id:'joined-demo-clan-'+index,sample:true});open('clan','members');renderHUD();saveCurrentProgress();return;}
  if(a==='speed-plan-auto021'){const p=state.constructionPrompt;if(p){p.items=accelerationQuote('job-speed',{id:p.id}).items;renderModal();}return;}
  actionDepth021++;try{r21Action(a,d,node);}finally{actionDepth021--;}
  grantEarlyGifts021();const changed=enforceTestModes021();if(changed)renderHUD();
  if(state.modal==='pvp')renderModal();saveCurrentProgress();
 }catch(error){toast(error.message);}
};
