// Renderer partagé avec l’éditeur : coordonnées relatives à la cellule du sprite.
function makeBuildingFX022(ctx){
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rnd=n=>{let x=Math.sin(n*131.489+78.233)*43758.5453;return x-Math.floor(x)};
const colorRGBA=(hex,a=1)=>{const c=/^#[a-f0-9]{6}$/i.test(hex)?hex:'#ffffff';return `rgba(${parseInt(c.slice(1,3),16)},${parseInt(c.slice(3,5),16)},${parseInt(c.slice(5,7),16)},${clamp(a,0,1)})`};
function glow(x,y,r,c,a=.45){if(r<=0)return;ctx.save();ctx.globalCompositeOperation='lighter';const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,colorRGBA(c,a));g.addColorStop(.32,colorRGBA(c,a*.5));g.addColorStop(1,colorRGBA(c,0));ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.restore()}
function dot(x,y,r,c,a=1){ctx.save();ctx.fillStyle=colorRGBA(c,a);ctx.beginPath();ctx.arc(x,y,Math.max(.5,r),0,Math.PI*2);ctx.fill();ctx.restore()}
function ray(points,c,alpha=.9,w=2,blur=9){ctx.save();ctx.globalCompositeOperation='lighter';ctx.strokeStyle=colorRGBA(c,alpha);ctx.lineWidth=w;ctx.shadowBlur=blur;ctx.shadowColor=c;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();for(let i=0;i<points.length;i++)i?ctx.lineTo(points[i][0],points[i][1]):ctx.moveTo(points[i][0],points[i][1]);ctx.stroke();ctx.restore()}
function flare(x,y,r,c,a=1,rot=0){if(a<=0)return;ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.globalCompositeOperation='lighter';ctx.shadowColor=c;ctx.shadowBlur=Math.min(28,r*.6);ctx.lineCap='round';for(let i=0;i<2;i++){ctx.beginPath();ctx.strokeStyle=colorRGBA(i===0?c:'#ffffff',a*(i===0?.9:.8));ctx.lineWidth=i===0?Math.max(1,r*.13):1.2;ctx.moveTo(-r*(i===0?1:.55),0);ctx.lineTo(r*(i===0?1:.55),0);ctx.moveTo(0,-r*(i===0?1.45:.78));ctx.lineTo(0,r*(i===0?1.45:.78));ctx.stroke()}ctx.restore();dot(x,y,Math.max(1.5,r*.16),'#ffffff',a)}
function circleLine(x,y,r,c,a,w=2,start=0,end=Math.PI*2){ctx.save();ctx.globalCompositeOperation='lighter';ctx.beginPath();ctx.ellipse(x,y,r,r*.55,0,start,end);ctx.strokeStyle=colorRGBA(c,a);ctx.shadowBlur=10;ctx.shadowColor=c;ctx.lineWidth=w;ctx.stroke();ctx.restore()}
function drawFlame(x,y,r,c,t,power,density){
 const gain=1+Math.sqrt(power)*.12;const count=Math.min(15,Math.ceil(2+power*1.2*density));
 glow(x,y-r*.2,r*1.6,c,clamp(.09*power,0,.8));
 for(let j=0;j<3;j++){
  const px=x+(j-1)*r*.27, wiggle=Math.sin(t*(9+j*3)+j*2.7)*r*.16, h=r*(1.1+j*.12)*gain*(.85+.17*Math.sin(t*8+j*3));
  ctx.save();ctx.globalCompositeOperation='lighter';ctx.beginPath();ctx.moveTo(px-r*.34,y+r*.26);ctx.bezierCurveTo(px-r*.57,y-r*.12,px+wiggle-r*.11,y-h*.75,px+wiggle,y-h);
  ctx.bezierCurveTo(px+wiggle+r*.14,y-h*.53,px+r*.49,y-r*.16,px+r*.32,y+r*.26);ctx.closePath();
  const g=ctx.createLinearGradient(px,y+r*.25,px,y-h);g.addColorStop(0,colorRGBA('#ff461b',.77));g.addColorStop(.36,colorRGBA(c,.95));g.addColorStop(.76,colorRGBA('#ffd45a',.82));g.addColorStop(1,colorRGBA('#ffffff',.12));ctx.fillStyle=g;ctx.shadowColor=c;ctx.shadowBlur=12;ctx.fill();ctx.restore();
 }
 for(let i=0;i<count;i++){const q=(t*(.48+.13*rnd(i))+rnd(i+7))%1;const xx=x+(rnd(i+80)-.5)*r*.85+Math.sin(t*3+i)*r*.09;const yy=y-q*r*2.0;dot(xx,yy,Math.max(.8,(1-q)*r*.055),'#ffce67',clamp((1-q)*power*.35,0,.95))}
}
function drawPortal(x,y,r,c,t,power,density){
 glow(x,y,r*1.4,c,clamp(.20*Math.sqrt(power),.05,.95));
 ctx.save();ctx.beginPath();ctx.ellipse(x,y,r*.91,r*1.18,0,0,Math.PI*2);ctx.clip();
 glow(x,y,r*1.05,'#6505ad',clamp(.18*power,0,.75));
 const arms=1;
 for(let k=0;k<arms;k++){
  const pts=[];for(let i=0;i<=62;i++){const q=i/62;const a=q*Math.PI*3.2+t*1.85+k*Math.PI*2/arms;const rr=r*(.06+.95*q);pts.push([x+rr*Math.cos(a),y+rr*.90*Math.sin(a)])}
  ray(pts,c,clamp(.16+.095*power,0,.88),2.8+Math.min(3,power*.25),8+Math.min(18,power*2));
  ray(pts,'#f4baff',clamp(.10+.06*power,0,.65),.85,4);
 }
 glow(x,y,r*.37,'#ed90ff',clamp(.12*power,0,.95));ctx.restore();
 for(let j=0;j<Math.min(35,Math.round(6*density*(1+power*.13)));j++){
  const a=j*2.4+t*.95,rr=r*(.77+.24*rnd(j));const v=(Math.sin(t*2+j*2)+1)/2;
  dot(x+Math.cos(a)*rr,y+Math.sin(a)*rr*.9,1+v*2,c,clamp(v*.2*power,0,.8));
 }
}
function drawCrystal(x,y,r,c,t,power,density){
 glow(x,y,r*1.8,c,clamp(.115*Math.sqrt(power),.025,.85));
 const n=Math.min(55,Math.ceil((5+7*Math.sqrt(power))*density));
 for(let i=0;i<n;i++){
  const rr=r*(.2+1.4*Math.sqrt(rnd(i+27))),a=i*2.39996+t*(i%2?.07:-.11);
  const px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr*.95;
  const peak=Math.pow(Math.max(0,Math.sin(t*(1.4+rnd(i)*2)+i*3.7)),8);
  if(peak>.07)flare(px,py,clamp(r*(.06+peak*.19),2,31),c,clamp(peak*(.25+.17*power),0,1),t*.24+i);
 }
 const peak=Math.pow((1+Math.sin(t*2.7))/2,4);
 flare(x,y,r*(.2+.3*peak),c,clamp((.25+.2*power)*(peak+.1),0,1),t*.11);
}
function drawElectric(x,y,r,c,t,power,density){
 glow(x,y,r*1.6,c,clamp(.11*Math.sqrt(power),0,.88));
 const arcs=Math.min(16,Math.round((3+Math.sqrt(power)*1.8)*Math.sqrt(density)));
 for(let j=0;j<arcs;j++){
  const a=j*Math.PI*2/arcs+t*(j%2?.65:-.56),pts=[];
  for(let k=0;k<9;k++){
   const q=k/8,an=a+q*1.18;const rr=r*(.28+.74*q)+r*(rnd(j*10+k+Math.floor(t*12))-.5)*.2;
   pts.push([x+rr*Math.cos(an),y+rr*Math.sin(an)*.8]);
  }
  ray(pts,c,clamp(.18+.20*power,0,1),1.2+Math.min(2,power*.2),14);
  if(j%2===0)ray(pts,'#ffffff',clamp(.075+.07*power,0,.6),.6,3);
 }
 if(power>2){const k=Math.min(55,Math.floor((power-2)*4*density));for(let i=0;i<k;i++){const a=i*2.39+t*2.2,rad=r*(.7+rnd(i));flare(x+Math.cos(a)*rad,y+Math.sin(a)*rad,2+power*.35,c,.2,0)}}
}
function drawCoins(x,y,r,c,t,power,density){
 const n=Math.min(75,Math.ceil((7+power*3)*density));glow(x,y,r*1.3,c,clamp(.045*Math.sqrt(power),0,.5));
 for(let i=0;i<n;i++){
  const q=(t*(.25+rnd(i+17)*.12)+rnd(i))%1;
  const drift=(rnd(i+31)-.5)*r*1.5, xx=x+drift+Math.sin(t*2+i)*r*.07, yy=y+r*.25-q*r*1.65;
  const opacity=clamp(Math.sin(q*Math.PI)*(0.16+.22*power),0,1);if(opacity<=.01)continue;
  const coinR=clamp(r*(.04+.025*rnd(i+33)),2,11);
  ctx.save();ctx.translate(xx,yy);ctx.rotate(i+t*.22);ctx.globalAlpha=opacity;ctx.fillStyle=c;ctx.strokeStyle='#fff3a0';ctx.lineWidth=1.1;ctx.beginPath();ctx.ellipse(0,0,Math.max(1,coinR*Math.abs(Math.cos(t*3+i*2))),coinR,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();
 }
}
function drawGold(x,y,r,c,t,power,density){
 glow(x,y,r*1.65,c,clamp(.05*Math.sqrt(power),0,.5));const n=Math.min(55,Math.ceil((7+power*2.5)*density));
 for(let i=0;i<n;i++){
  const q=(t*.28+rnd(i+2))%1, xx=x+(rnd(i+38)-.5)*r*2.1, yy=y+(rnd(i+65)-.5)*r*1.6-q*r*.3;
  const peak=Math.pow(Math.max(0,Math.sin(t*2+i*2.8)),6);flare(xx,yy,2+r*peak*.10,c,clamp((.06+.3*power)*peak,0,.9),i*.1);
 }
}
function drawBubbles(x,y,r,c,t,power,density,poison=false){
 glow(x,y,r*1.4,c,clamp(.09*Math.sqrt(power),0,.8));
 const n=Math.min(75,Math.ceil((9+power*2.5)*density));
 for(let i=0;i<n;i++){
  const q=(t*(.19+.14*rnd(i+88))+rnd(i))%1;
  const bx=x+(rnd(i+30)-.5)*r*1.6+Math.sin(t*1.8+i)*r*.07,by=y+r*.75-q*r*(poison?1.8:1.3),rad=Math.max(1,r*(.018+.044*rnd(i+60)))*(1-q*.4);
  const al=clamp(Math.sin(q*Math.PI)*(.12+.21*power),0,.9);
  ctx.save();ctx.strokeStyle=colorRGBA(c,al);ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(bx,by,rad,0,Math.PI*2);ctx.stroke();ctx.restore();
  if(i%4===0)dot(bx-rad*.25,by-rad*.32,Math.max(.6,rad*.22),'#ffffff',al*.75)
 }
}
function drawHeal(x,y,r,c,t,power,density){
 glow(x,y,r*1.5,c,clamp(.10*Math.sqrt(power),0,.8));const n=Math.min(80,Math.ceil((10+power*3)*density));
 for(let i=0;i<n;i++){
  const q=(t*(.18+.07*rnd(i))+rnd(i+11))%1,angle=i*2.4+t*.18;
  const xx=x+Math.cos(angle)*r*(.25+.55*rnd(i)),yy=y+r*.4-q*r*1.6;
  const al=clamp(Math.sin(q*Math.PI)*(.25+.22*power),0,1);
  if(i%6===0){ray([[xx-3,yy],[xx+3,yy]],c,al,1.7,6);ray([[xx,yy-3],[xx,yy+3]],c,al,1.7,6)}else dot(xx,yy,1.2+2*rnd(i+20),c,al);
 }
}
function drawDust(x,y,r,c,t,power,density){
 const n=Math.min(100,Math.ceil((11+power*4)*density));
 for(let i=0;i<n;i++){
  const a=i*2.399,tick=(t*(.1+.09*rnd(i+7))+rnd(i+2))%1;
  const rr=r*Math.sqrt(rnd(i+62)),xx=x+Math.cos(a)*rr+Math.sin(t*.7+i)*r*.18,yy=y+Math.sin(a)*rr*.74-tick*r*.5;
  const al=clamp(Math.sin(tick*Math.PI)*(.13+.15*power),0,.8);dot(xx,yy,clamp(r*(.006+.013*rnd(i+32)),.7,4),c,al);
 }
}
function drawSmoke(x,y,r,c,t,power,density){
 const n=Math.min(35,Math.ceil((7+power)*density));
 for(let i=0;i<n;i++){
  const q=(t*(.11+rnd(i+6)*.06)+rnd(i+10))%1;
  const xx=x+Math.sin(i*3+t*.3)*r*.31,yy=y+r*.35-q*r*1.6,rad=r*(.12+.26*q);
  glow(xx,yy,rad,c,clamp(Math.sin(Math.PI*q)*(.025+.05*power),0,.23));
 }
}
function drawEffect(e,lay,t){
 if(!e.enabled||e.intensity<=0)return;
 const x=lay.x+lay.w*e.x, y=lay.y+lay.h*e.y, u=Math.min(lay.w,lay.h);
 const size=e.size/100, power=e.intensity/100, density=e.density/100;
 const r=u*.125*size;const c=e.color;const tm=t*e.speed/100;
 switch(e.type){
  case 'flame':drawFlame(x,y,r,c,tm,power,density);break;
  case 'portal':drawPortal(x,y,r,c,tm,power,density);break;
  case 'crystal':drawCrystal(x,y,r,c,tm,power,density);break;
  case 'electric':drawElectric(x,y,r,c,tm,power,density);break;
  case 'aura':glow(x,y,r*2.5*(1+.1*Math.sin(tm*2)),c,clamp(.12*Math.sqrt(power),0,.96));break;
  case 'mana':drawBubbles(x,y,r,c,tm,power,density);circleLine(x,y,r*1.1,c,clamp(.13*Math.sqrt(power),0,.7),1.5,tm,tm+Math.PI*1.25);break;
  case 'elixir':drawBubbles(x,y,r,c,tm,power,density);break;
  case 'poison':drawBubbles(x,y,r,c,tm,power,density,true);break;
  case 'heal':drawHeal(x,y,r,c,tm,power,density);break;
  case 'coins':drawCoins(x,y,r,c,tm,power,density);break;
  case 'gold':drawGold(x,y,r,c,tm,power,density);break;
  case 'dust':drawDust(x,y,r,c,tm,power,density);break;
  case 'smoke':drawSmoke(x,y,r,c,tm,power,density);break;
 }
}

return drawEffect;
}

// Admission limitée et transitions continues : jamais plus de dix effets.
function makeAmbientScheduler023(){
 const active=new Map(),cooldown=new Map();let last=0;
 const rand=s=>{let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))|0;return ((Math.sin(h*12.9898)*43758.5453)%1+1)%1;};
 const smooth=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);};
 return {reset(){active.clear();cooldown.clear();last=0;},select(candidates,t){
  const available=new Map(candidates.map(c=>[c.key,c]));
  for(const [k,a]of active)if(!available.has(k)||t>=a.end){active.delete(k);cooldown.set(k,t+(a.infernal?4:10+rand(k+Math.floor(t))*10));}
  const waiting=candidates.filter(c=>!active.has(c.key)&&t>=(cooldown.get(c.key)??(rand(c.key)*12))).sort((a,b)=>Number(b.infernal)-Number(a.infernal)||rand(a.key+Math.floor(t/15))-rand(b.key+Math.floor(t/15)));
  for(const c of waiting){if(active.size>=6)break;active.set(c.key,{start:t,end:t+(c.infernal?16:2+2*rand(c.key+Math.floor(t))),infernal:c.infernal});}
  last=active.size;return [...active].map(([k,a])=>({...available.get(k),alpha:Math.min(smooth((t-a.start)/.8),smooth((a.end-t)/.8))})).filter(c=>c.effect);
 },count(){return last;}};
}

