 const stage=$('#stage');if(!stage)return;
 if(!canvas022){canvas022=document.createElement('canvas');canvas022.id='building-fx022';canvas022.setAttribute('aria-hidden','true');stage.append(canvas022);paint022=makeBuildingFX022(canvas022.getContext('2d'));}
 const ctx=canvas022.getContext('2d'),bounds=stage.getBoundingClientRect(),scale=bounds.width/1600,h=stage.clientHeight;
