for(const t of root.tournaments){let row=t.rows.find(r=>r.clanId===state.clanId||r.name===state.clan);if(!row||state.tournament0291.receipts.includes(t.id))continue;let result=RULES0291.tournamentCredit(state.tournament0291,t.id,row.rank,capFor('gold')),p=RULES0291.tournamentPrize(row.rank,1);state.clanTreasury.gold+=p.treasury.gold;state.clanTreasury.elixir+=p.treasury.elixir;let rate=p.rate;state.giftMails.push({id:'tournament:'+t.id,playerId:state.id,title:'Récompense personnelle du tournoi',text:'Rang '+row.rank+' · la trésorerie a reçu un lot distinct.',claimed:false,kind:'gift',remaining:PreviewGame.v07RewardBundle({gold:Math.floor(capFor('gold')*rate),elixir:Math.floor(capFor('elixir')*rate)})});state.tournament0291=result;changed=true;}
