function translationKey030(message){let raw=[state.id,state.locale||'fr',message[0],message[1],message[2]].join('|'),n=2166136261;for(let c of raw)n=Math.imul(n^c.charCodeAt(0),16777619)>>>0;return state.id+':'+(state.locale||'fr')+':'+n;}
const chatBefore030=renderChat;renderChat=function(){chatBefore030();if(!state.chatOpen)return;for(let [id,label]of [['world','Mondial'],['national','Même langue'],['clan','Clan']]){let b=$('#chat [data-channel="'+id+'"]');if(b)b.textContent=label;}let shown=(messages[state.channel]||[]).filter(m=>!state.blocked.has(m[0]));[...document.querySelectorAll('#chat .chat-message')].forEach((row,i)=>{let m=shown[i];row.querySelectorAll('[data-action="translate0291"]').forEach(b=>b.remove());if(!m?.[5]||m[5]===(state.locale||'fr'))return;let key=translationKey030(m),cached=state.translation030[key];if(cached){let e=document.createElement('div');e.className='translated030';e.textContent=cached.text||'Traduction indisponible';e.title=cached.local?'Exemple de traduction locale · démo':'Traduction du message';row.append(e);}else row.insertAdjacentHTML('beforeend',button(translationPending030.has(key)?'…':'🌐','translate030','data-index="'+i+'" aria-label="Traduire" '+(translationPending030.has(key)?'disabled':''),'translate-button030'));});};
