referralPanel0291=function(){const db=securityRegistry0304(),parent=db.links.find(l=>l.child===state.id);return '<section class="referral0304"><h2>Inviter un aventurier</h2><p>Ton code personnel à partager en dehors des salons de discussion :</p><strong class="referral-code0304">'+esc(db.referralCodes0304[state.id])+'</strong>'+button('Copier mon code','referral-copy0304','','secondary')+'<p>Le filleul saisit le code avant le niveau 5. Deux appareils et deux réseaux distincts sont nécessaires.</p><label>Code du parrain<input id="referral-code0304" maxlength="32" placeholder="BX-…" '+(parent?'disabled':'')+'></label>'+button(parent?'Parrain déjà lié':'Lier mon parrain','referral-link0304',parent?'disabled':'')+'<p>Récompenses après vérification : 3 000 diamants au parrain et 1 500 au filleul. Le filleul doit atteindre le niveau 7 et avoir au moins 7 jours. Les liens existants restent conservés.</p><p>Les tentatives non conformes sont signalées aux administrateurs.</p></section>';};
async function linkReferral0304(){const code=$('#referral-code0304').value.trim(),db=securityRegistry0304(),id=Object.keys(db.referralCodes0304).find(id=>RULES0304.normalize(db.referralCodes0304[id])===RULES0304.normalize(code)),parent=db.players.find(p=>p.id===id),child={...consoleSnapshot0291(),level:state.level};try{if(db.links.some(l=>l.child===state.id))throw Error('Un parrain est déjà lié.');let identity;if(typeof window.blaboxIdentityVerifier0304==='function')identity=await window.blaboxIdentityVerifier0304({parentId:id,childId:state.id});else{const a=db.identityTests0304?.[id],b=db.identityTests0304?.[state.id];identity=a&&b?{verified:true,sameNetwork:a.network===b.network,sameDevice:a.device===b.device}:null;}RULES0304.referral(parent,child,identity);db.links=RULES0291.linkReferral(db.links,id,state.id);const link=db.links.find(l=>l.child===state.id);link.code0304=code;link.identityChecked0304=true;link.boundAt0304=Date.now();DEMOOPS0291.write(db);renderModal();toast('Parrain lié. Les récompenses attendent la qualification.');}catch(e){securityAlert0304(e.message,code);toast(e.message);}}
const FAQ0304=[['Comment recruter des monstres ?','Choisis une quantité puis valide. Les unités rejoignent la file d’attente et le sélecteur revient à zéro.'],['Comment utiliser mes héros ?','Affecte-les à une garnison. Un héros à 15 % de vie ou moins doit récupérer avant de combattre.'],['Comment fonctionnent les offres ?','Deux offres au maximum sont affichées. Les suivantes attendent une place ; leur compte à rebours démarre à leur affichage. Les offres personnelles sont uniques et définitivement perdues à expiration.'],['Où retrouver un achat ou un cadeau ?','Dans le courrier et l’historique des achats. Le destinataire voit qui lui offre le cadeau et ouvre le détail avant de le récupérer.'],['Comment fonctionne le parrainage ?','Partage ton code hors des salons. Le filleul doit le saisir avant le niveau 5, sur un autre appareil et un autre réseau. Les récompenses attendent les conditions de qualification et la vérification.'],['Pourquoi un message est-il bloqué ?','Les codes de parrainage sont interdits dans les salons : avertissement à la première tentative, silence d’une heure à la deuxième, y compris pour les messages similaires.'],['Comment signaler un problème ?','Ouvre Contacter un administrateur dans les paramètres. Décris le problème et joins une capture si nécessaire.'],['Pourquoi une accélération ne demande plus de confirmation ?','Tu as coché cette préférence pour les accélérations de bâtiments pendant la connexion. Les autres confirmations restent actives.']];
