const prereq0304=prerequisiteMarkup;prerequisiteMarkup=function(o){const v=buildingUpgradeView(o);if(!v||o.underConstruction)return '';return '<section class="prerequisites0304"><b>Prérequis · niveau '+(o.level+1)+'</b><ul>'+v.rows.map(r=>'<li class="'+(r.met?'met':'missing')+'"><span>'+esc(r.name)+'</span><small>'+r.actual+' / '+r.level+'</small><b>'+(r.met?'✓':'!')+'</b></li>').join('')+'<li class="'+(v.free?'met':'missing')+'"><span>Ouvriers disponibles</span><small>'+v.free+' / 1 requis</small><b>'+(v.free?'✓':'!')+'</b></li></ul>'+(v.reason?'<small>'+esc(v.reason)+'</small>':'')+'</section>';};
