function testReward0304(id){const key='closure-test:'+state.testRewardRun0304+':'+id;if(state.testClosures0304.includes(key))return toast('Cet essai a déjà été attribué.');let reward={diamonds:10};if(['daily','weekly'].includes(id)){reward={diamonds:0,gold:0,elixir:0,items:{}};for(const row of MODELS.CHALLENGES_330.challenges.filter(c=>c.kind===id)){for(const k of ['diamonds','gold','elixir'])reward[k]+=row.reward?.[k]||0;for(const[k,n]of Object.entries(row.reward?.items||{}))reward.items[k]=(reward.items[k]||0)+n;}}if(id==='contributors'){const row=PreviewGame.clanContributorRewards(state.clanData,state.clanWeek).find(r=>r.playerId===state.id);if(row)reward={gold:row.reward.gold,elixir:row.reward.elixir,diamonds:row.reward.diamonds,items:Object.fromEntries(Object.entries(row.reward.vials||{}).map(([k,v])=>['xp-'+k,v]))};}if(id==='first-purchase'||id==='first-gift')reward=commerceReward030(id);if(id==='first-gift'&&!state.commerce030.firstGift)reward.diamonds=50;if(id==='loyalty'){const day=state.loyalty.day+1;if(day===30){const hero=PreviewGame.loyaltyHero(state.loyalty.cycle,dailyKey(),[...state.ownedHeroes]);reward=hero&&!state.ownedHeroes.has(hero)?{heroes:[hero]}:{diamonds:500};}else reward=day%7===0?{items:{'shield-1d':1}}:day%3===0?{diamonds:5}:day%2?{items:{'xp-small':1}}:{gold:2000,elixir:2000};}if(id==='referral')reward={diamonds:state.id===DEMOOPS0291.read().links[0]?.parent?3000:1500};if(id==='war'||id==='tournament'){const q=RULES0291.tournamentPrize(1,capFor('gold'));reward={gold:Math.floor(capFor('gold')*q.rate),elixir:Math.floor(capFor('elixir')*q.rate)};}state.testClosures0304.push(key);mailReward030(key,'Essai de clôture · '+id,'Récompense de simulation attribuée individuellement.',reward,id==='first-purchase'?500:0);saveCurrentProgress();toast('Courrier de test ajouté : '+id);}
const modal0304=renderModal;renderModal=function(){modal0304();const root=$('#modal-body');const custom={tests0304:['Tests de la démo',tests0304],faq0304:['Questions fréquentes',faq0304],support0304:['Contacter un administrateur',support0304],offer0304:['Offre unique',offerPanel0304],'offer-checkout0304':['Vérifier l’achat',offerCheckout0304]};if(state.modal==='inbox'&&state.tab==='purchases'){root.innerHTML='<h2>Mes achats et cadeaux</h2>'+[...state.purchaseHistory].reverse().map(o=>o.kind==='bundle'?'<article class="paper-card purchase-record0303"><h3>'+esc(o.bundleName)+'</h3><p>'+esc([o.contents.workers?o.contents.workers+' ouvriers permanents':'',o.contents.hero||'',o.contents.xpPotions?o.contents.xpPotions+' potions de 1 500 XP':''].filter(Boolean).join(' · '))+'</p><b>'+esc(o.paid)+'</b><small> · '+new Date(o.at).toLocaleString('fr-FR')+'</small></article>':'<article class="paper-card purchase-record0303">'+purchaseMeta0303({...o,playerId:o.playerId||state.id})+'</article>').join('');}if(custom[state.modal]){$('#modal-title').textContent=custom[state.modal][0];root.innerHTML=custom[state.modal][1]();$('#modal-tabs').innerHTML='';}compactHeroCards0304(root);root.classList.toggle('fit-page0304',['stage','war-node','monster','research'].includes(state.modal)||state.modal==='army'&&state.tab==='formation');$('#modal').classList.toggle('offer-modal0304',['offer0304','offer-checkout0304'].includes(state.modal));if(state.modal==='settings'){root.innerHTML=settings();$('#modal-tabs').innerHTML='';}if(state.modal==='support0304'){const input=$('#support-message0304');input.oninput=()=>supportDraft0304.text=input.value;$('#support-image0304').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Choisis une image PNG, JPEG ou WebP de moins de 5 Mo.');const img=await createImageBitmap(file),canvas=document.createElement('canvas'),ratio=Math.min(1,1280/Math.max(img.width,img.height));canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);supportDraft0304.image=canvas.toDataURL('image/jpeg',.78);img.close();$('#support-image-status0304').textContent='Capture jointe';};}if(state.modal==='tests0304')enhanceSelects();};
