function actorCoverage0304(actor,coverage,x,ground,scaleX,scaleY,anchorX,anchorY){if(!state.battle||!actor.id||!coverage)return;const u=state.battle.engine.units.find(u=>u.id===actor.id)||state.battle.engine.structures.find(u=>u.id===actor.id);if(!u)return;const cell=CW(),pitch=fh()/cell,originX=x/cell-.5-u.x,originY=((layout.floors-.5)*fh()-ground)/cell-u.floor*pitch;const pointX=v=>originX+(v-anchorX)*scaleX/cell,pointY=v=>originY-(v-anchorY)*scaleY/cell,b=coverage.bounds;Object.defineProperty(u,'opaqueShape0304',{enumerable:false,configurable:true,writable:true,value:{runs:coverage.runs,sx:scaleX/cell,sy:scaleY/cell,ox:pointX(0),oy:pointY(0),bounds:{left:Math.min(pointX(b.left),pointX(b.right)),right:Math.max(pointX(b.left),pointX(b.right)),bottom:pointY(b.bottom),top:pointY(b.top)}}});}
