function flyLoot0308(k,amount,changes){updateLootHUD0308();const dest=$('[data-loot-wallet="'+k+'"]');if(!dest)return;const row=changes.find(n=>n.resource===k&&n.gain>0),source=row?.itemId?document.querySelector('.building[data-id="'+CSS.escape(row.itemId)+'"]'):null,dr=dest.getBoundingClientRect(),sr=source?.getBoundingClientRect()||{left:innerWidth*.5,top:innerHeight*.5,width:0,height:0};for(let i=0;i<Math.min(4,1+Math.floor(amount/100));i++){if(document.querySelectorAll('.loot-flight0308').length>24)break;const el=document.createElement('img');el.className='loot-flight0308';el.src=ART['item:'+k];el.style.left=(sr.left+sr.width/2)+'px';el.style.top=(sr.top+sr.height/2)+'px';document.body.append(el);const a=el.animate([{transform:'translate(0,0) scale(.6)',opacity:0},{opacity:1,offset:.15},{transform:'translate('+(dr.left-sr.left-sr.width/2+dr.width/2)+'px,'+(dr.top-sr.top-sr.height/2+dr.height/2)+'px) scale(.9)',opacity:1}],{duration:650+i*65,easing:'cubic-bezier(.2,.6,.3,1)',delay:i*35});a.onfinish=()=>el.remove();}const plus=document.createElement('span');plus.className='loot-plus0308';plus.textContent='+'+fmt(amount);plus.style.left=Math.min(innerWidth-120,($('#pillage-wallet0308')?.getBoundingClientRect().right||dr.right)+8)+'px';plus.style.top=dr.top+'px';document.body.append(plus);plus.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-35px)'}],{duration:950}).onfinish=()=>plus.remove();dest.classList.remove('loot-pulse0308');void dest.offsetWidth;dest.classList.add('loot-pulse0308');}
const oldRenderBattleHUD0308=renderBattleHUD;renderBattleHUD=function(){const r=oldRenderBattleHUD0308();updateLootHUD0308();return r;};const oldStopBattle0308=stopBattle;stopBattle=function(...args){if(state.battle?.engine?.loot0308&&!state.battle.replay)syncPillage0308(state.battle.engine,true);const r=oldStopBattle0308(...args);$('#pillage-wallet0308')?.remove();return r;};
