 if(c.rate){const p=MODELS.DIAMOND_PACKS[0];add('Diamants du lot de départ',p.diamonds,1,'item:diamonds');add('Diamants offerts · +'+Math.round(c.rate*100)+' %',Math.floor(p.diamonds*c.rate),1,'item:diamonds');}
