 if(c.xp)add('Potion · 1 500 XP',c.xp,120,'item:xp-large');if(c.xpMedium)add('Potion · 500 XP',c.xpMedium,45,'item:xp-medium');
 for(const [id,n]of Object.entries(c.items||{})){const secs=Number(id.replace('speed-','')),names={300:'5 minutes',900:'15 minutes',3600:'1 heure',86400:'1 jour'},costs={300:10,900:30,3600:40,86400:200};add('Accélérateur · '+(names[secs]||exactTime(secs)),n,costs[secs]??null,'item:'+(ART['item:'+id]?id:'speed-3600'));}
