// 0.31.0 — VIP, laboratoire, alchimie et récompenses de pillage.
const P31=PROGRESSION0310;
const p31key=()=> 'blabox-progression0310:'+state.id;
let p31;try{p31=JSON.parse(localStorage.getItem(p31key())||'null')}catch{};
const progressDefaults0320={version:1,vipXP:0,streak:0,lastCheck:null,lastReward:null,receipts:[],scrolls:[],scrollDrops:0,duplicates:{},skillXP:{},equipped:{},alchemy:[],raids:{},spellLevels:{heal:1,bubble:1,fire:1,eye:1,disarm:1,crystal:1}};
p31={...progressDefaults0320,...(p31||state.progress0310||{})};
for(const k of ['receipts','scrolls','alchemy'])if(!Array.isArray(p31[k]))p31[k]=[];
for(const k of ['duplicates','skillXP','equipped','raids','spellLevels'])if(!p31[k]||typeof p31[k]!=='object'||Array.isArray(p31[k]))p31[k]=structuredClone(progressDefaults0320[k]);
state.progress0310=p31;
