function cast31(id,floor,x){let b=state.battle?.engine,s=spells31.find(s=>s[0]===id);if(!b||!s||b.status!=='running'||state.battle.replay)throw Error('Sort indisponible.');let pool=b.mana;if(!pool||pool.amount<s[2])throw Error('Mana insuffisant : '+s[2]+' requis.');let enemies=[...b.units.filter(u=>u.side==='defense'),...b.structures].filter(u=>u.hp>0&&u.floor===floor&&Math.abs(u.x-x)<=2),allies=b.units.filter(u=>u.side==='attack'&&u.hp>0&&u.deployed!==false&&u.floor===floor&&Math.abs(u.x-x)<=2),traps=(b.traps||[]).filter(t=>t.floor===floor&&Math.abs(t.x-x)<=2),l=p31.spellLevels[id];if(id==='disarm'){let t=traps.find(t=>t.revealed31&&!t.disabled31);if(!t)throw Error('Sélectionne un piège révélé.');t.disabled31=true;t.disabled=true;t.revealed=true;t.exploded=true;t.explodesAt=Infinity;}if(id==='crystal'){let u=enemies.filter(u=>u.hero||u.troop).sort((a,c)=>Math.abs(a.x-x)-Math.abs(c.x-x))[0];if(!u)throw Error('Aucune unité ennemie dans la zone.');u.freezeUntil=b.time+3+l*.1;u.crystal31={hp:u.maxHp*.15,end:u.freezeUntil};}if(id==='eye')for(let t of traps){t.revealed31=true;t.revealed=true;}if(id==='bubble')for(let u of allies)u.ward31=b.time+4;if(id==='heal')for(let u of allies)u.heal31={until:b.time+5,perSecond:u.maxHp*(.02+l*.001)};if(id==='fire')for(let u of enemies){let before=u.hp;u.hp=Math.max(0,u.hp-(35+15*l));if(b.loot0308)PILLAGE0308.recordHit(b,u,before)}pool.amount-=s[2];state.recovery.mana.amount=pool.amount;state.targetSpell31=null;let el=$('.castle-floor[data-floor="'+floor+'"]');if(el){el.insertAdjacentHTML('beforeend','<i class="spell-fx0310" style="left:'+x*CW()+'px"></i>');setTimeout(()=>el.querySelectorAll('.spell-fx0310').forEach(n=>n.remove()),3000)}save31();toast(s[1]+' · −'+s[2]+' mana');}
function tickEffects31(b){if(!b||b.status!=='running')return;let dt=Math.min(.5,Math.max(0,b.time-(b.lastEffects31??b.time)));b.lastEffects31=b.time;for(let u of b.units){if(u.hp>0&&u.heal31?.until>b.time)u.hp=Math.min(u.maxHp,u.hp+u.heal31.perSecond*dt);if(u.crystal31){if(u.crystal31.end<=b.time||u.crystal31.hp<=0){u.freezeUntil=Math.min(u.freezeUntil,b.time);delete u.crystal31}else{let friends=[...b.units,...b.structures].filter(a=>a.side===u.side&&a.hp>0&&a!==u&&a.floor===u.floor&&Math.abs(a.x-u.x)<=2);u.crystal31.hp-=friends.reduce((n,a)=>n+(a.damage||0)*dt*.5,0)}}}}
